const refreshAiStudioUploads = async () => {
    try {
        const headers = await getApiAuthHeaders()
        const data: any = await $fetch('/api/assets', { headers, query: { limit: 80, source: 'uploads' } }).catch(() => [])
        if (Array.isArray(data)) {
            aiStudioUploads.value = data.map((a: any) => ({ id: a.id, name: a.name, url: a.url }))
        }
    } catch (e) {
        console.warn('[ai-studio] Falha ao carregar uploads:', e)
    }
}

const normalizeProductImagePickerAssets = (payload: any): Array<{ id: string; name: string; url: string; key?: string }> => {
    const items = Array.isArray(payload)
        ? payload
        : (Array.isArray(payload?.items) ? payload.items : [])

    return items
        .map((asset: any, index: number) => {
            const key = String(asset?.key || '').trim()
            const rawUrl = String(key || asset?.url || '').trim()
            const url = toWasabiProxyUrl(rawUrl) || String(asset?.url || rawUrl).trim()
            return {
                id: String(asset?.id || key || `product-image-${index + 1}`).trim(),
                name: String(asset?.name || key || 'Imagem do Wasabi').trim(),
                url,
                key: key || undefined
            }
        })
        .filter((asset: { id: string; name: string; url: string; key?: string }) => !!asset.url)
}

const refreshProductImagePickerAssets = async () => {
    productImagePickerLoading.value = true
    productImagePickerError.value = ''
    try {
        const headers = await getApiAuthHeaders()
        const search = String(productImagePickerSearch.value || '').trim()
        const data: any = await $fetch('/api/assets', {
            headers,
            query: {
                ...(search ? { q: search } : {}),
                limit: search ? 120 : 80,
                ai: '0',
                expand: '0',
                includeCache: '0'
            }
        })
        productImagePickerAssets.value = normalizeProductImagePickerAssets(data)
    } catch (e: any) {
        productImagePickerAssets.value = []
        productImagePickerError.value = String(e?.data?.statusMessage || e?.message || 'Falha ao carregar imagens do Wasabi.')
        console.warn('[product-image-picker] Falha ao carregar imagens internas:', e)
    } finally {
        productImagePickerLoading.value = false
    }
}

const searchExplicitProductFlavors = async () => {
    if (productImagePickerLoading.value || !productImageFlavorQueries.value.length) return;
    const queries = [...productImageFlavorQueries.value];
    productImagePickerLoading.value = true;
    productImagePickerError.value = '';
    try {
        const headers = await getApiAuthHeaders();
        const results = await Promise.allSettled(queries.map(async item => {
            const data = await $fetch('/api/assets', { headers, query: { q: item.query, limit: 60, ai: '0', fresh: '1', includeCache: '0' } });
            return normalizeProductImagePickerAssets(data);
        }));
        productImagePickerSearch.value = '';
        const assets = results.flatMap(result => result.status === 'fulfilled' ? result.value : []);
        productImagePickerAssets.value = [...new Map(assets.map(asset => [asset.url, asset])).values()];
        const missing = queries.filter((_, index) => results[index]?.status === 'rejected' || (results[index] as PromiseFulfilledResult<any[]>).value?.length === 0);
        if (missing.length) productImagePickerError.value = `Sem imagens disponíveis para: ${missing.map(item => item.flavor).join(', ')}. Você pode enviar uma imagem desse sabor.`;
    } catch { productImagePickerError.value = 'Não foi possível buscar os sabores. Tente novamente.'; }
    finally { productImagePickerLoading.value = false; }
};

const searchProductImagePickerUploads = async () => {
    const query = String(productImagePickerSearch.value || '').trim()
    if (!query) {
        await refreshProductImagePickerAssets()
        return
    }
    await refreshProductImagePickerAssets()
}

