const designLoadActualCounts = ref<{ objects: number; images: number } | null>(null)
const designLoadImageProgress = ref<{ expected: number; loaded: number; failed: number } | null>(null)

type ImageLoadTracker = {
    sessionId: number
    expected: number
    loaded: number
    failed: number
    remainingBySrc: Map<string, number>
}

let activeImageLoadTracker: ImageLoadTracker | null = null
let imageProgressRafId: number | null = null
// Cada imagem remota tem duas tentativas de 30s e fallback isolado. O limite
// global precisa deixar margem para o Fabric montar grupos/filtros e carregar
// os placeholders, sem interromper a sessão antes do tratamento individual.
const CANVAS_LOAD_TIMEOUT_BASE_MS = 70_000
const CANVAS_LOAD_TIMEOUT_PER_IMAGE_MS = 300
const CANVAS_LOAD_TIMEOUT_MAX_MS = 80_000
const CANVAS_IMAGE_LOAD_TIMEOUT_NAME = 'CanvasImageLoadTimeoutError'

const getCanvasLoadTimeoutMs = (sessionId: number): number => {
    const expected = activeImageLoadTracker?.sessionId === sessionId
        ? Math.max(0, Number(activeImageLoadTracker.expected || 0))
        : 0
    const extraImages = Math.max(0, expected - 8)
    return Math.min(
        CANVAS_LOAD_TIMEOUT_MAX_MS,
        CANVAS_LOAD_TIMEOUT_BASE_MS + (extraImages * CANVAS_LOAD_TIMEOUT_PER_IMAGE_MS)
    )
}

const createCanvasImageLoadTimeoutError = (timeoutMs = CANVAS_LOAD_TIMEOUT_BASE_MS): Error => {
    const error = new Error(
        `Fabric loadFromJSON excedeu ${timeoutMs}ms aguardando imagens`
    )
    error.name = CANVAS_IMAGE_LOAD_TIMEOUT_NAME
    ;(error as any).timeoutMs = timeoutMs
    return error
}

const scheduleImageProgressFlush = () => {
    if (typeof window === 'undefined') return
    if (imageProgressRafId != null) return
    imageProgressRafId = window.requestAnimationFrame(() => {
        imageProgressRafId = null
        const tracker = activeImageLoadTracker
        if (!tracker) return
        // Ignore stale sessions
        if (tracker.sessionId !== activePageLoadSessionId) return
        designLoadImageProgress.value = {
            expected: tracker.expected,
            loaded: tracker.loaded,
            failed: tracker.failed
        }
    })
}

// collectTrackableImageSrcCounts extraido para utils/canvasImageTracking.ts.

const startImageLoadTracking = (sessionId: number, canvasData: any) => {
    const counts = collectTrackableImageSrcCounts(canvasData)
    let expected = 0
    counts.forEach((n) => { expected += Number(n || 0) || 0 })
    if (!expected) {
        activeImageLoadTracker = null
        designLoadImageProgress.value = null
        return
    }

    activeImageLoadTracker = {
        sessionId,
        expected,
        loaded: 0,
        failed: 0,
        remainingBySrc: new Map(counts)
    }
    designLoadImageProgress.value = { expected, loaded: 0, failed: 0 }
}

const stopImageLoadTracking = (sessionId: number) => {
    if (activeImageLoadTracker?.sessionId === sessionId) {
        // Keep last known progress for the overlay, but stop counting new loads.
        activeImageLoadTracker = null
    }
}

