        )
    }
    return stats
}

const loadFromJSONWithImageProgress = async (json: any, sessionId: number): Promise<number> => {
    if (!canvas.value) throw new Error('Canvas indisponível para loadFromJSON')
    // Reset progress for each attempt; it reflects the current load pipeline.
    startImageLoadTracking(sessionId, json)
    scheduleImageProgressFlush()
    const abortController = typeof AbortController !== 'undefined' ? new AbortController() : null
    activePageImageLoadAbort?.abort()
    activePageImageLoadAbort = abortController
    let timeoutHandle: ReturnType<typeof setTimeout> | null = null
    let loadTimedOut = false
    let failedImages = 0
    const unregisterImageSession = abortController
        ? registerCanvasImageLoadSession(fabric.FabricImage || fabric.Image, abortController.signal, {
            timeoutMs: 30_000,
            retryCount: 1,
            onSettled: (src, failed) => {
                if (failed) failedImages += 1
                const tracker = activeImageLoadTracker
                if (!tracker || tracker.sessionId !== sessionId) return
                const remaining = tracker.remainingBySrc.get(src) || 0
                if (remaining <= 0) return
                tracker.remainingBySrc.set(src, remaining - 1)
                if (failed) tracker.failed += 1
                else tracker.loaded += 1
                scheduleImageProgressFlush()
            }
        })
        : () => {}
    const timeoutMs = getCanvasLoadTimeoutMs(sessionId)
    try {
        sanitizeCanvasJsonBeforeLoad(json)
        // Fabric carrega as imagens com CORS; um preloader paralelo duplicava as requisições.
        if (sessionId !== activePageLoadSessionId || isCanvasDestroyed.value) {
            throw new Error('Load session became stale')
        }
        if (!canvas.value) throw new Error('Canvas indisponível para loadFromJSON')
        // Fabric 7 accepts an AbortSignal as the third argument. Race it with
        // an explicit timeout as a second safety net for browsers/polyfills
        // that do not propagate aborts through an image element.
        const loadPromise = canvas.value.loadFromJSON(
            json,
            undefined,
            abortController ? { signal: abortController.signal } : undefined
        )
        const timeoutPromise = new Promise<never>((_, reject) => {
            timeoutHandle = setTimeout(() => {
                loadTimedOut = true
                try {
                    abortController?.abort()
                } catch {
                    // Best effort: the race below still releases the UI.
                }
                reject(createCanvasImageLoadTimeoutError(timeoutMs))
            }, timeoutMs)
        })
        await Promise.race([loadPromise, timeoutPromise])
        if (sessionId !== activePageLoadSessionId || isCanvasDestroyed.value) throw new Error('Load session became stale')
        restoreCanvasStickerOutlines(canvas.value)
        return failedImages
    } catch (error) {
        if (loadTimedOut) {
            // Keep a stable error name so the page-load fallback can skip
            // repeated retries of the same hanging URLs.
            throw createCanvasImageLoadTimeoutError(timeoutMs)
        }
        throw error
    } finally {
        if (timeoutHandle) clearTimeout(timeoutHandle)
        if (activePageImageLoadAbort === abortController) activePageImageLoadAbort = null
        unregisterImageSession()
        // Publica antes de limpar: o RAF pendente não pode ler o tracker apagado.
        const tracker = activeImageLoadTracker
        if (tracker?.sessionId === sessionId) {
            designLoadImageProgress.value = {
                expected: tracker.expected, loaded: tracker.loaded, failed: tracker.failed
            }
        }
        stopImageLoadTracking(sessionId)
    }
}

const scheduleIdleStatePersistence = (opts: any, timeoutMs = 2200) => {
    const scheduledForPageId = getActiveProjectPageId()
    const run = () => {
        if (isCanvasDestroyed.value) return

        if (scheduledForPageId) {
            const currentPageId = getActiveProjectPageId()
            if (!currentPageId || currentPageId !== scheduledForPageId) {
                return
            }
        }

        const nextOpts = { ...(opts || {}) }
        if (scheduledForPageId && !nextOpts.expectedPageId) {
            nextOpts.expectedPageId = scheduledForPageId
        }
        saveCurrentState(nextOpts)
    }

    scheduleIdleWork(run, timeoutMs);
}

// scheduleIdleWork extraido para utils/idleSchedule.ts.

// Wrapper local que injeta o projectId atual no helper puro extraido.
const getPreparedCanvasDataCacheKey = (page: any): string | null =>
    buildPreparedCanvasDataCacheKey(page, project.id)

let preparedCanvasPrewarmRunId = 0

const schedulePreparedCanvasDataPrewarm = (activePageId?: string | null) => {
    if (typeof window === 'undefined' || isCanvasDestroyed.value) return

    const runId = ++preparedCanvasPrewarmRunId
    const normalizedActivePageId = String(activePageId || '').trim()
    const pagesToPrewarm = (Array.isArray(project.pages) ? project.pages : [])
        .filter((page: any) => {
            if (!page?.canvasData || typeof page.canvasData !== 'object') return false
            const pageId = String(page?.id || '').trim()
            return !!pageId && pageId !== normalizedActivePageId
        })
        .map((page: any) => ({
            canvasData: page.canvasData,
            cacheKey: getPreparedCanvasDataCacheKey(page)
        }))

    if (!pagesToPrewarm.length) return

    let index = 0
    const pump = () => {
        if (runId !== preparedCanvasPrewarmRunId || isCanvasDestroyed.value) return
        const next = pagesToPrewarm[index++]
        if (!next) return

        try {
            prepareCanvasDataForLoad(next.canvasData, {
                cacheKey: next.cacheKey,
                silent: true
            })
        } catch (err) {
            console.warn('[load-prepare] Falha ao preaquecer cache de página inativa:', err)
        }

        if (index < pagesToPrewarm.length) {
            scheduleIdleWork(pump, 1800)
        }
    }

    scheduleIdleWork(pump, 1400)
}

