const applyQuickProductNameColor = async (value: string | null) => {
    const selected = quickSelectedNameCard.value
    if (!selected || (value !== null && !/^#[\da-f]{6}$/i.test(value))) return
    const zone = findProductZoneById(selected.parentZoneId)
