const applyQuickTypographyToAll = async () => {
    const source = getQuickFontTargets()
    if (source.length !== 1) return
    const original = source[0]
    const properties = ['fontFamily', 'fontSize', 'fontWeight', 'fontStyle', 'lineHeight', 'charSpacing']
    const values = Object.fromEntries(properties.map(key => [key, original[key]]))
    const textCase = getDynamicBusinessTextCase(original)
    for (const object of getQuickFontTargets(true)) {
        if (object === original) continue
        if (object.styles) {
            for (const line of Object.values(object.styles) as any[]) {
                for (const style of Object.values(line) as any[]) properties.forEach(key => delete style[key])
            }
        }
        object.__manualTypography = true
        object.__manualTransform = true
        object.set(values)
        applyDynamicBusinessTextCase(object, textCase)
        object.initDimensions?.()
        if (isDynamicBusinessFieldObject(object)) {
            object.dynamicFieldBaseFontSize = values.fontSize
            object.dynamicFieldAutoFitFontSize = values.fontSize
            object.dynamicFieldHeight = Math.max(Number(original.height) || 0, Number(object.height) || 0)
            object.set('height', object.dynamicFieldHeight)
        }
        object.dirty = true
        object.setCoords?.()
        touchQuickModeObjectAncestors(object)
    }
    refreshCanvasObjects({ immediate: true })
    refreshSelectedRef()
    safeRequestRenderAll()
    await persistQuickModeDataChange('quick-typography-all')
}
const quickFontSize = computed(() => {
    const sizes = [...new Set(quickModeNativeTextObjects.value.map((o: any) => Number(o.fontSize)))]
    return sizes.length === 1 ? sizes[0] : undefined
})
const quickTypography = computed(() => {
    const targets = quickModeNativeTextObjects.value
    const common = (key: string) => {
        const values = [...new Set(targets.map((object: any) => Number(object[key])))]
        return values.length === 1 && Number.isFinite(values[0]) ? values[0] : undefined
    }
    return { height: common('height'), lineHeight: common('lineHeight'), charSpacing: common('charSpacing') }
})
const applyQuickTypography = (change: { property: string; value: number | string }) => {
    const { property, value } = change
    if (!['height', 'lineHeight', 'charSpacing', 'textCase'].includes(property)) return
    if (property !== 'textCase' && (!Number.isFinite(Number(value)) ||
        (property !== 'charSpacing' && Number(value) <= 0))) return
    for (const object of getQuickFontTargets()) {
        object.__manualTypography = true
        object.__manualTransform = true
        if (property === 'textCase') applyDynamicBusinessTextCase(object, value)
        else {
            object.set(property, Number(value))
            if (property === 'height') {
                if (isDynamicBusinessFieldObject(object)) {
                    object.dynamicFieldHeight = Number(value)
                    fitDynamicBusinessTextObject(object)
                }
            } else object.initDimensions?.()
        }
        object.dirty = true
        object.setCoords?.()
        touchQuickModeObjectAncestors(object)
    }
    refreshCanvasObjects({ immediate: true })
    safeRequestRenderAll()
    refreshSelectedRef()
    debouncedSaveCurrentState()
}
const applyQuickFontSize = async (value: number) => {
    if (!Number.isFinite(value) || value < 1 || value > 500) return
    for (const object of getQuickFontTargets()) {
        const top = object.getPointByOrigin?.('center', 'top')
        object.dynamicFieldAutoHeight = true
        object.__manualTypography = true
        object.__manualTransform = true
        object.set({ fontSize: value })
        // Imported rich text may carry a size per character that overrides
        // the Textbox size. An explicit whole-text edit replaces those sizes.
        if (object.styles) {
            for (const line of Object.values(object.styles) as any[]) {
                for (const style of Object.values(line) as any[]) delete style.fontSize
            }
        }
        object.dirty = true
        if (object.quickDataField || object.businessProfileField) {
            object.dynamicFieldBaseFontSize = value
            object.dynamicFieldAutoFitFontSize = value
            object.initDimensions?.()
            // An explicit size change also updates the field's height budget.
            // Future content still fits the field instead of restoring the old size.
            object.dynamicFieldHeight = object.height
        }
        object.initDimensions?.()
        if (top) object.setPositionByOrigin?.(top, 'center', 'top')
        object.setCoords?.()
        touchQuickModeObjectAncestors(object)
    }
    refreshCanvasObjects({ immediate: true })
    safeRequestRenderAll()
    refreshSelectedRef()
    await persistQuickModeDataChange('quick-font-size')
}

const quickCardColorSettings = computed(() => {
    void canvasObjects.value
    const zone = findProductZoneById(quickModeTargetZoneId.value)
    const styles = zone ? getZoneGlobalStyles(zone) : {}
    return { styles, mode: styles.cardColorMode || 'auto', color: styles.cardColorMode === 'manual' ? (styles.cardColor || '#ffffff') : (styles.highlightCardColor || '#ffffff') }
})
const applyQuickCardColors = async (settings: { mode: 'auto' | 'manual'; color?: string; allPages: boolean }) => {
    if (!canvas.value || isProcessing.value) return
    const current = project.pages[project.activePageIndex]
    if (!current) return
    isProcessing.value = true
    try {
        const color = settings.color || findFlyerAccent(canvas.value.getObjects()) || '#ffffff'
        const pending: Array<{ index: number; data: any }> = []
        // Load before changing anything: a failed page read must not produce a partial batch.
        if (settings.allPages) {
            for (let index = 0; index < project.pages.length; index++) {
                const page = project.pages[index]!
                if (page.id === current.id || page.width !== current.width || page.height !== current.height) continue
                const loaded = await ensurePageCanvasDataLoaded(page.id)
                if (!loaded?.canvasData) throw new Error('Não foi possível carregar todas as páginas. Tente novamente.')
                const data = JSON.parse(JSON.stringify(loaded.canvasData))
                const cards = flattenCardColorObjects(data.objects || []).filter(node => node.parentZoneId && node._productData)
                if (cards.length === 1) pending.push({ index, data })
            }
        }
        const apply = (roots: any[], onlyZone?: string) => {
            const objects = flattenCardColorObjects(roots)
            for (const zone of objects.filter(node => node.isProductZone && (!onlyZone || node._customId === onlyZone))) {
                const cards = objects.filter(node => node.parentZoneId === zone._customId && node._productData).sort((a, b) => (a._zoneOrder || 0) - (b._zoneOrder || 0))
                zone._zoneGlobalStyles = { ...zone._zoneGlobalStyles, productPalette: settings.mode === 'auto' && settings.color ? { ...zone._zoneGlobalStyles?.productPalette, highlightCardColor: color } : settings.mode === 'auto' ? {} : zone._zoneGlobalStyles?.productPalette, cardColorMode: settings.mode, highlightCardColor: color, cardColor: settings.mode === 'manual' ? color : '#ffffff', isProdBgTransparent: false }
                if (zone._zoneStateSnapshot) zone._zoneStateSnapshot.globalStyles = { ...zone._zoneStateSnapshot.globalStyles, ...zone._zoneGlobalStyles }
                const highlight = getZoneHighlightPredicate(zone, cards)
                cards.forEach((card, index) => {
                    card._cardHighlighted = highlight.isHighlighted(card, index)
                    const bg = (card.getObjects?.() || card.objects || []).find((obj: any) => obj.name === 'offerBackground')
                    if (!bg) return
                    const fill = resolveProductCardColor(zone._zoneGlobalStyles, card._cardHighlighted, card._cardStyleOverrides)
                    if (bg.set) bg.set('fill', fill); else bg.fill = fill
                    syncProductNameColor(card, zone._zoneGlobalStyles)
                    card.dirty = true
                })
            }
        }
        apply(canvas.value.getObjects(), quickModeTargetZoneId.value || undefined)
        for (const { index, data } of pending) { apply(data.objects || []); updatePageData(index, data) }
        refreshCanvasObjects({ immediate: true })
        safeRequestRenderAll()
        await saveCurrentState({ reason: 'quick-card-colors', source: 'user', skipCoalesce: true, skipIfUnchanged: false })
        notifyEditorInfo(`Cores aplicadas${pending.length ? ` em ${pending.length + 1} páginas` : ''}. Cores individuais escolhidas manualmente foram mantidas.`)
    } catch (error) {
        notifyEditorInfo(error instanceof Error ? error.message : 'Não foi possível aplicar as cores.')
    } finally { isProcessing.value = false }
}

const quickMobileSection = ref('preview')
const quickModeColorTargets = computed(() => {
    void selectedObjectRef.value
    if (!isQuickMode.value) return []
    const targets = collectQuickEditableColorTargets(canvasObjects.value)
    const selected = canvas.value?.getActiveObjects?.() || []
    const backgrounds = targets.filter(target => target.kind === 'product-card' && target.objects.some(({ object }) => {
        let node = object
        while (node) {
            if (selected.includes(node)) return true
            node = node.group
