const touchQuickModeObjectAncestors = (object: any) => {
    let parent = object?.group
    const visited = new Set<any>()
    while (parent && !visited.has(parent)) {
        visited.add(parent)
        parent.dirty = true
        parent.setCoords?.()
        parent = parent.group
    }
}

const applyQuickModeNativeFont = async (fontFamily: string) => {
    if (!isQuickMode.value || !canvas.value) return
    const normalizedFont = String(fontFamily || '').trim()
    if (!normalizedFont) return

    if (typeof document !== 'undefined' && document.fonts?.load) {
        await document.fonts.load(`16px "${normalizedFont.replace(/"/g, '')}"`).catch(() => undefined)
    }

    const targets = getQuickFontTargets()
    if (!targets.length) return
    targets.forEach((object: any) => {
        object.__manualTypography = true
        object.__manualTransform = true
        object.set?.({ fontFamily: normalizedFont })
        object.initDimensions?.()
        object.setCoords?.()
        touchQuickModeObjectAncestors(object)
    })
    refreshCanvasObjects({ immediate: true })
    safeRequestRenderAll()
    refreshSelectedRef()
    await Promise.resolve(saveCurrentState({
        reason: 'quick-native-font',
        source: 'user',
        skipCoalesce: true,
        skipIfUnchanged: false
    }))
}

const normalizeQuickModeColor = (value: string): string | null => {
    const normalized = String(value || '').trim().toLowerCase()
    if (/^#[0-9a-f]{6}$/i.test(normalized)) return normalized
    if (/^#[0-9a-f]{3}$/i.test(normalized)) {
        return `#${normalized.slice(1).split('').map(char => `${char}${char}`).join('')}`
    }
    return null
}

type QuickModeColorChange = { targetId: string; value: string }
type QuickModeOpacityChange = { targetId: string; value: number }

const getQuickModeColorTarget = (targetId: string) => (
    quickModeColorTargets.value.find(target => target.id === String(targetId || '').trim()) || null
)

const persistQuickModeColorChange = async (reason: string) => {
    refreshCanvasObjects({ immediate: true })
    safeRequestRenderAll()
    refreshSelectedRef()
    await Promise.resolve(saveCurrentState({
        reason,
        source: 'user',
        skipCoalesce: true,
        skipIfUnchanged: false
    }))
}

const applyQuickModeColorChange = async (payload: QuickModeColorChange) => {
    if (!isQuickMode.value || !canvas.value) return
    const target = getQuickModeColorTarget(payload?.targetId)
    const color = normalizeQuickModeColor(payload?.value)
    if (!target || !color) return

    target.objects.forEach(({ object, property }) => {
        object.set?.({ [property]: color })
        if (property === 'fill') applyDynamicBusinessTextColor(object, color)
        if (target.kind === 'product-card' && object.group) {
            object.group._cardStyleOverrides = { ...object.group._cardStyleOverrides, cardColor: color, isProdBgTransparent: false }
            syncProductNameColor(object.group, getZoneGlobalStyles(findProductZoneById(object.group.parentZoneId)))
        }
        object.setCoords?.()
        touchQuickModeObjectAncestors(object)
    })
    await persistQuickModeColorChange(`quick-color-${target.kind}`)
}

const clearQuickModeColor = async (targetId: string) => {
    if (!isQuickMode.value || !canvas.value) return
    const target = getQuickModeColorTarget(targetId)
    if (!target) return

    target.objects.forEach(({ object, property }) => {
        object.set?.({ [property]: 'transparent', ...(target.kind === 'product-card' ? { stroke: 'transparent' } : {}) })
        if (property === 'fill') applyDynamicBusinessTextColor(object, 'transparent')
        if (target.kind === 'product-card' && object.group) {
            object.group._cardStyleOverrides = { ...object.group._cardStyleOverrides, isProdBgTransparent: true, cardBorderWidth: 0 }
        }
        object.setCoords?.()
        touchQuickModeObjectAncestors(object)
    })
    await persistQuickModeColorChange(`quick-color-clear-${target.kind}`)
}

const applyQuickModeOpacityChange = async (payload: QuickModeOpacityChange) => {
    if (!isQuickMode.value || !canvas.value) return
    const target = getQuickModeColorTarget(payload?.targetId)
    const opacity = Number(payload?.value)
    if (!target || !Number.isFinite(opacity)) return

    const normalizedOpacity = Math.max(0, Math.min(1, opacity))
    target.objects.forEach(({ object }) => {
        object.set?.({ opacity: normalizedOpacity })
        object.setCoords?.()
        touchQuickModeObjectAncestors(object)
    })
    await persistQuickModeColorChange(`quick-opacity-${target.kind}`)
}

const selectedObjectId = ref<string | null>(null)
const selectedObjectIds = ref<string[]>([])
const selectedObjectRef = shallowRef<any>(null) // Direct reference for properties panel (shallow for performance)
// watch reads its computed source immediately, so the selection ref must exist first.
watch(quickSelectedProductName, () => { quickProductNameColorScope.value = 'selected' })
const selectedProductImageSubTarget = shallowRef<any>(null)
const selectedProductImageSelectionKind = ref<'image' | 'card' | 'other' | 'none'>('none')
// O Fabric altera objetos fora da reatividade do Vue. Esta versao permite que
// o inspector da zona atualize quando cards e vinculos sao reidratados.
const productZoneUiVersion = ref(0)
const invalidateQuickModeUi = () => {
    productZoneUiVersion.value += 1
}

/** Refresh selectedObjectRef with a fresh snapshot so Vue detects changes in PropertiesPanel props */
const refreshSelectedRef = (extra?: Record<string, any>) => {
    refreshSelectedRefWithRecovery({
        canvas: canvas.value,
        selectedObjectRef,
        snapshotForPropertiesPanel,
        triggerSelectedObjectRef: () => triggerRef(selectedObjectRef),
        extra
    })
    invalidateQuickModeUi()
}

const selectedObjectPos = ref<{top: number, left: number, width: number, height: number, visible: boolean}>({ top: 0, left: 0, width: 0, height: 0, visible: false })

const priceGroupsWithDeepSelect = new Set<any>()
const priceGroupUiVersion = ref(0)
const selectedPriceGroupSubTarget = shallowRef<any>(null)
const selectedPriceGroupSelectionKind = ref<'label' | 'card' | 'other' | 'none'>('none')

const isPriceGroupObject = (obj: any): boolean => (
    !!obj &&
    String(obj.type || '').toLowerCase() === 'group' &&
    String(obj.name || '').trim() === 'priceGroup'
)

const isPriceGroupBackground = (obj: any): boolean => isProductLabelBackgroundName(obj?.name)

const resolvePriceGroupAncestor = (obj: any): any | null => {
    if (!obj) return null
    const pending = [obj]
    const visited = new Set<any>()
    while (pending.length > 0) {
        const current = pending.pop()
        if (!current || visited.has(current)) continue
        visited.add(current)
        if (isPriceGroupObject(current)) return current
        if (String(current.type || '').toLowerCase() === 'activeselection' && typeof current.getObjects === 'function') {
            pending.push(...(current.getObjects() || []))
        }
        if (current.group) pending.push(current.group)
        // Fabric keeps the original parent while a nested object temporarily
        // belongs to an ActiveSelection. Follow both links during that state.
        if (current.parent && current.parent !== current.group) pending.push(current.parent)
    }
    return null
}

const setPriceGroupInteractionMode = (priceGroup: any, mode: ProductLabelInteractionMode) => {
    if (!isPriceGroupObject(priceGroup) || typeof priceGroup.getObjects !== 'function') return false

    const editingChildren = mode === 'edit'
    if (editingChildren) priceGroupsWithDeepSelect.add(priceGroup)
    else priceGroupsWithDeepSelect.delete(priceGroup)

    priceGroup.set?.({
        ...getProductLabelGroupInteractionProps(mode),
        dirty: true
    })

    priceGroup.getObjects().forEach((child: any) => {
        if (!child) return
        const childProps = getProductLabelChildInteractionProps(mode, isPriceGroupBackground(child))
        child.set?.(childProps)
        if (typeof enableCardElementRotationControl === 'function') enableCardElementRotationControl(child, childProps.selectable)
        child.setCoords?.()
    })

    priceGroup.setCoords?.()
    priceGroupUiVersion.value += 1
    return true
}

const updatePriceGroupSelectionIntent = (event: any, opts: { preserveLabelForCard?: boolean } = {}) => {
    const target = event?.target || event?.selected?.[0] || canvas.value?.getActiveObject?.()
    const subTargets = Array.isArray(event?.subTargets) ? event.subTargets.filter(Boolean) : []
    const candidates = [...subTargets].reverse().concat(target ? [target] : [])
    const priceGroup = candidates.map((candidate: any) => resolvePriceGroupAncestor(candidate)).find(Boolean) || null

    if (priceGroup) {
        selectedPriceGroupSubTarget.value = priceGroup
        selectedPriceGroupSelectionKind.value = 'label'
        return
    }

    if (opts.preserveLabelForCard && selectedPriceGroupSelectionKind.value === 'label') {
        const currentPriceGroup = resolvePriceGroupAncestor(selectedPriceGroupSubTarget.value)
        const currentCard = getCardGroupFromAny(currentPriceGroup)
        const targetCard = candidates.map((candidate: any) => getCardGroupFromAny(candidate)).find(Boolean)
        if (currentPriceGroup && currentCard && targetCard === currentCard && subTargets.length === 0) return
    }

    selectedPriceGroupSubTarget.value = null
    const cardCandidate = candidates.find((candidate: any) => getCardGroupFromAny(candidate))
    if (cardCandidate) {
        selectedPriceGroupSelectionKind.value = cardCandidate === target ? 'card' : 'other'
        return
    }
    selectedPriceGroupSelectionKind.value = 'none'
}

const resolveZoneQuickActionsAnchor = () => {
    const zone = getCurrentZoneObject();
    return zone && isLikelyProductZone(zone) ? zone : null;
}

// Debounced save for properties panel (prevents lag during rapid input changes)
let propertySaveTimer: ReturnType<typeof setTimeout> | null = null;
// Padrao "single-flight com pending bit": garante que mudancas chegadas
// durante um save em andamento nao sao descartadas. Quando o save em voo
// termina, se houve novas edicoes (propertySavePending=true), reroda.
let propertySaveTask: Promise<void> | null = null;
let propertySavePending = false;
const runPropertySave = (reason: string): Promise<void> => {
    propertySavePending = true;
    if (propertySaveTask) return propertySaveTask;
    propertySaveTask = (async () => {
        try {
            do {
                propertySavePending = false;
                await saveCurrentState({ reason, skipCoalesce: true });
            } while (propertySavePending);
        } finally {
            propertySaveTask = null;
        }
    })();
    return propertySaveTask;
};
const debouncedSaveCurrentState = () => {
    if (propertySaveTimer) clearTimeout(propertySaveTimer);
    propertySaveTimer = setTimeout(() => {
        propertySaveTimer = null;
        void runPropertySave('properties-panel');
    }, 150); // 150ms debounce for snappy feel but coalesces rapid changes
};
const flushPropertySave = async () => {
    if (propertySaveTimer) {
        clearTimeout(propertySaveTimer);
        propertySaveTimer = null;
    }
    await runPropertySave('properties-panel-flush');
};

// Debounced save for text editing (typing in i-text/textbox does not always emit object:modified).
let textEditSaveTimer: ReturnType<typeof setTimeout> | null = null;
const queueTextEditSave = (reason = 'text-edit') => {
    if (textEditSaveTimer) clearTimeout(textEditSaveTimer);
    textEditSaveTimer = setTimeout(() => {
        saveCurrentState({ reason });
    }, 180);
};
const flushTextEditSave = (reason = 'text-edit-exit') => {
    if (textEditSaveTimer) {
        clearTimeout(textEditSaveTimer);
        textEditSaveTimer = null;
    }
    saveCurrentState({ reason });
};

let lifecycleFlushTask: Promise<void> | null = null;
let lastLifecycleFlushAt = 0;
let hasPendingCoalescedSave = false;

const finalizeActiveTextEditingForPersist = () => {
    if (!canvas.value) return;
    try {
        const active = canvas.value.getActiveObject() as any;
        if (!active) return;
        const t = String(active.type || '').toLowerCase();
        if ((t === 'i-text' || t === 'textbox') && active.isEditing && typeof active.exitEditing === 'function') {
            active.exitEditing();
            active.setCoords?.();
        }
    } catch {
        // ignore
    }
};

const hasActiveTextEditingForPersist = () => {
    if (!canvas.value) return false;
    try {
        const active = canvas.value.getActiveObject() as any;
        if (!active) return false;
        const t = String(active.type || '').toLowerCase();
        return (t === 'i-text' || t === 'textbox') && !!active.isEditing;
    } catch {
        return false;
    }
};

const clearPendingPersistenceTimers = () => {
    if (propertySaveTimer) {
        clearTimeout(propertySaveTimer);
        propertySaveTimer = null;
    }
    if (textEditSaveTimer) {
        clearTimeout(textEditSaveTimer);
        textEditSaveTimer = null;
    }
    if (globalStylesSaveTimer) {
        clearTimeout(globalStylesSaveTimer);
        globalStylesSaveTimer = null;
    }
    if (viewportStateSaveTimer) {
        clearTimeout(viewportStateSaveTimer);
        viewportStateSaveTimer = null;
    }
    if (cancelPendingCoalescedSave) {
        cancelPendingCoalescedSave();
    }
};

const performPersistenceFlush = async (reason: string, opts: { force?: boolean } = {}) => {
    const now = Date.now();
    const force = !!opts.force;
    if (!force && now - lastLifecycleFlushAt < 250) return;
    lastLifecycleFlushAt = now;


    {
        const hadPendingPropertySave = !!propertySaveTimer || !!propertySaveTask;
        if (propertySaveTask) await propertySaveTask;
        const hadPendingTextEditSave = !!textEditSaveTimer;
        const hadPendingGlobalStylesSave = !!globalStylesSaveTimer;
        const hadPendingViewportSave = !!viewportStateSaveTimer;
        const hadPendingCoalescedSave = hasPendingCoalescedSave;
        const hadActiveTextEditing = hasActiveTextEditingForPersist();
        const hadPendingProjectSync = hasUnsavedChanges.value || project.pages.some((page: any) => !!page?.dirty || !!page?.thumbnailDirty);
        const shouldPersistLocalState = hadPendingPropertySave
            || hadPendingTextEditSave
            || hadPendingGlobalStylesSave
            || hadPendingViewportSave
            || hadPendingCoalescedSave
            || hadActiveTextEditing;

        if (!shouldPersistLocalState && !hadPendingProjectSync) {
            return;
        }

        clearPendingPersistenceTimers();

        if (hadActiveTextEditing) {
            finalizeActiveTextEditingForPersist();
        }

        if (shouldPersistLocalState) {
            // FIX: During the post-undo/redo cooldown, skip persisting the canvas
            // state — the canvas contains the restored snapshot and saving it would
            // overwrite the user's original data with the undo target.
            if (Date.now() < _historyRestoreCooldownUntil) {
                console.log(`⏳ [flushPersistence] Suprimido durante cooldown pós-undo/redo (reason=${reason})`)
            } else {
                // Save to in-memory project + local draft immediately (sync path inside saveState/updatePageData).
                try {
                    await Promise.resolve(saveCurrentState({
                        reason: `lifecycle:${reason}`,
                        source: 'system',
                        markUnsaved: true,
                        skipIfUnchanged: true,
                        skipCoalesce: true
                    }));
                } catch (err) {
                    console.warn('[persist] Falha ao salvar estado em flush de lifecycle:', err);
                }
            }
        }

        try {
            flushPendingLocalDrafts();
        } catch (err) {
            console.warn('[persist] Falha ao flushar drafts locais pendentes:', err);
        }

        // Also force remote save path whenever possible.
        const hasPendingProjectSyncNow = hadPendingProjectSync || hasUnsavedChanges.value || project.pages.some((page: any) => !!page?.dirty);
        if (hasPendingProjectSyncNow) {
            if (hasUnsavedChanges.value) triggerAutoSave();
            await flushAutoSave().catch((err: any) => {
                console.warn('[persist] Falha no flushAutoSave:', err);
            });
        }
    }
};

// Navegação concorrente aguarda o flush em andamento e captura a última edição.
const flushPersistenceNow = (reason: string, opts: { force?: boolean } = {}): Promise<void> => {
    const previous = lifecycleFlushTask;
    const task = (async () => {
        if (previous) await previous;
        await performPersistenceFlush(reason, opts);
    })();
    lifecycleFlushTask = task;
    void task.finally(() => {
        if (lifecycleFlushTask === task) lifecycleFlushTask = null;
    }).catch(() => {});
    return task;
};

// CORRECAO: provide/inject so desce de pai para filho em Vue.
// O editor pai (pages/editor/[id].vue) precisa acionar flushPersistenceNow
// antes do route leave — exposto por defineExpose + template ref.
// Mantemos o provide para qualquer descendente que tambem precise acionar.
provide('editorFlushPersistence', flushPersistenceNow);
defineExpose({ flushPersistenceNow });

useEditorLifecyclePersistence({
    project,
    hasUnsavedChanges,
    flushPersistenceNow,
    emergencySnapshotDirtyPages,
    handleOpenPageHistoryEvent
})

onUnmounted(() => {
    renderScheduler.dispose();
    if (propertySaveTimer) {
        clearTimeout(propertySaveTimer);
        propertySaveTimer = null;
    }
    if (textEditSaveTimer) {
        clearTimeout(textEditSaveTimer);
        textEditSaveTimer = null;
    }
});

