const remapDuplicatedSelectionBindings = (
    clones: any[],
    opts: { reason?: string; relayout?: boolean } = {}
) => {
    if (!canvas.value || !Array.isArray(clones) || clones.length === 0) return;

    const allNodes: any[] = [];
    const visit = (node: any) => {
        if (!node || typeof node !== 'object') return;
        allNodes.push(node);
        if (typeof node.getObjects === 'function') {
            try {
                (node.getObjects() || []).forEach((child: any) => visit(child));
            } catch {
                // ignore malformed clone children
            }
        }
        if (node.clipPath && typeof node.clipPath === 'object') visit(node.clipPath);
    };
    clones.forEach((clone: any) => visit(clone));

    const idMap = new Map<string, string>();
    allNodes.forEach((node: any) => {
        const oldId = String((node as any).__duplicateSourceCustomId || '').trim();
        const newId = String((node as any)._customId || '').trim();
        if (oldId && newId && oldId !== newId) idMap.set(oldId, newId);
    });
    if (idMap.size === 0) {
        allNodes.forEach((node: any) => {
            try { delete (node as any).__duplicateSourceCustomId; } catch { /* ignore */ }
        });
        return;
    }

    const remapRef = (raw: any): string => {
        const id = String(raw || '').trim();
        return id ? (idMap.get(id) || id) : '';
    };
    const remapPlainMetadata = (value: any, seen = new Set<any>()) => {
        if (!value || typeof value !== 'object' || seen.has(value)) return;
        seen.add(value);
        ['parentFrameId', 'parentZoneId', 'zoneId', 'zoneInstanceId', 'targetZoneId', 'canvasObjectId', 'objectId', 'groupId', 'parentId'].forEach((key) => {
            if (typeof value[key] === 'string') {
                const next = remapRef(value[key]);
                if (next && next !== value[key]) value[key] = next;
            }
        });
        if (value._zoneSlot && typeof value._zoneSlot === 'object') {
            const nextZoneId = remapRef(value._zoneSlot.zoneId);
            if (nextZoneId && nextZoneId !== value._zoneSlot.zoneId) {
                value._zoneSlot = { ...value._zoneSlot, zoneId: nextZoneId };
            }
        }
        Object.keys(value).forEach((key) => {
            const child = value[key];
            if (child && typeof child === 'object') remapPlainMetadata(child, seen);
        });
    };

    invalidateContainmentZoneCache();

    const affectedZones = new Map<string, any>();
    allNodes.forEach((node: any) => {
        const obj = node as any;
        if (typeof obj.parentFrameId === 'string') obj.parentFrameId = remapRef(obj.parentFrameId);
        if (typeof obj.parentZoneId === 'string') obj.parentZoneId = remapRef(obj.parentZoneId);
        if (typeof obj.zoneInstanceId === 'string') obj.zoneInstanceId = remapRef(obj.zoneInstanceId);
        if (typeof obj.zoneId === 'string') obj.zoneId = remapRef(obj.zoneId);
        if (obj._zoneSlot && typeof obj._zoneSlot === 'object') {
            const nextZoneId = remapRef(obj._zoneSlot.zoneId);
            if (nextZoneId) obj._zoneSlot = { ...obj._zoneSlot, zoneId: nextZoneId };
        }
        remapPlainMetadata(obj._productData);
        remapPlainMetadata(obj._zoneStateSnapshot);

        const zoneId = String(obj.parentZoneId || obj._zoneSlot?.zoneId || '').trim();
        if ((isProductCardContainer(obj) || isLikelyProductCard(obj)) && zoneId) {
            normalizeProductCardIdentity(obj, {
                zoneInstanceId: zoneId,
                forceNewInstance: true,
                reason: opts.reason || 'duplicate-selection'
            });
            const zone = findContainmentZoneById(zoneId);
            if (zone) affectedZones.set(zoneId, zone);
        }
        delete obj.__duplicateSourceCustomId;
    });

    affectedZones.forEach((zone: any) => {
        syncZoneCardFrameBindings(zone, getZoneChildren(zone));
        if (opts.relayout !== false) {
            recalculateZoneLayout(zone, getZoneChildren(zone), { save: false, preserveStyles: true });
        }
        syncZoneDerivedMetadata(zone, undefined, { updateStateSnapshot: true });
    });

    const duplicatedZone = clones.find((obj: any) => obj && !obj?.group && isLikelyProductZone(obj));
    if (duplicatedZone && isLikelyProductZone(duplicatedZone)) {
        targetGridZone.value = duplicatedZone;
        targetGridZones.value = resolveRelatedImportZones(duplicatedZone);
    }

    if (import.meta.dev) {
        console.debug('[product-zone:duplicate-selection-remap]', {
            reason: opts.reason || 'duplicate-selection',
            remappedIds: idMap.size,
            affectedZones: Array.from(affectedZones.keys()),
            targetZoneId: String((duplicatedZone as any)?._customId || '').trim() || null
        });
    }
};

// isUsableFabricObjectClone extraido para utils/canvasValidation.ts.

const cloneFabricObjectSafely = async (
    original: any,
    cloneProps: ReadonlyArray<string>,
    logPrefix = 'duplicate'
) => {
    if (!original) return null;

    let cloned: any = null;
    const isGroup = String((original as any)?.type || '').toLowerCase() === 'group';

    if (isGroup) {
        try {
            const json = typeof original.toObject === 'function' ? original.toObject(cloneProps) : null;
            if (json && fabric?.util?.enlivenObjects) {
                const objs = await fabric.util.enlivenObjects([json]);
                cloned = Array.isArray(objs) && objs.length > 0 ? objs[0] : null;
            }
        } catch (err) {
            console.warn(`[${logPrefix}] Falha no serialize+enliven do grupo`, err);
            cloned = null;
        }
    }

    if (!isUsableFabricObjectClone(cloned)) {
        try {
            const maybe = typeof (original as any).clone === 'function'
                ? (original as any).clone(cloneProps)
                : null;
            if (maybe && typeof maybe.then === 'function') {
                cloned = await maybe;
            } else if (isUsableFabricObjectClone(maybe)) {
                cloned = maybe;
            }
        } catch (err) {
            console.warn(`[${logPrefix}] Falha no clone nativo`, err);
            cloned = null;
        }
    }

    if (!isUsableFabricObjectClone(cloned) && !isGroup) {
        try {
            const json = typeof original.toObject === 'function' ? original.toObject(cloneProps) : null;
            if (json && fabric?.util?.enlivenObjects) {
                const objs = await fabric.util.enlivenObjects([json]);
                cloned = Array.isArray(objs) && objs.length > 0 ? objs[0] : null;
            }
        } catch (err) {
            console.warn(`[${logPrefix}] Falha no fallback serialize+enliven`, err);
            cloned = null;
        }
    }

    if (
        isUsableFabricObjectClone(cloned) &&
        String((cloned as any)?.type || '').toLowerCase() === 'group' &&
        typeof (cloned as any).getObjects === 'function'
    ) {
        const children = (cloned as any).getObjects() || [];
        const allValid = children.every((child: any) => (
            child &&
            typeof child === 'object' &&
            typeof child.set === 'function' &&
            typeof child.setCoords === 'function'
        ));

        if (!allValid) {
            try {
                const json = typeof original.toObject === 'function' ? original.toObject(cloneProps) : null;
                if (json && fabric?.util?.enlivenObjects) {
                    const objs = await fabric.util.enlivenObjects([json]);
                    cloned = Array.isArray(objs) && objs.length > 0 ? objs[0] : null;
                }
            } catch (err) {
                console.warn(`[${logPrefix}] Falha ao revalidar clone do grupo`, err);
                cloned = null;
            }
        }
    }

    return isUsableFabricObjectClone(cloned) ? cloned : null;
};

// resetDuplicatedObjectRuntime extraido para utils/fabricObjectOps.ts.

const findProductCardParentGroup = (obj: any) => {
    if (!obj || !canvas.value) return null;
    const direct = (obj as any).group;
    if (isProductCardContainer(direct)) return direct;
    const directParent = (obj as any).parent;
    if (isProductCardContainer(directParent)) return directParent;

    const targetId = String((obj as any)?._customId || '').trim();
    const all = canvas.value.getObjects();

    const containsObjectDeep = (node: any): boolean => {
        if (!node) return false;
        if (node === obj) return true;
        if (targetId && String((node as any)?._customId || '').trim() === targetId) return true;
        if (typeof (node as any)?.getObjects === 'function') {
            const children = (node as any).getObjects() || [];
            for (const child of children) {
                if (containsObjectDeep(child)) return true;
            }
        }
        return false;
    };

    for (const candidate of all) {
        if (!isProductCardContainer(candidate) || typeof candidate.getObjects !== 'function') continue;
        const activeChildren = Array.isArray((candidate as any)?._activeObjects)
            ? (candidate as any)._activeObjects
            : [];
        const contains =
            containsObjectDeep(candidate) ||
            activeChildren.some((child: any) => containsObjectDeep(child));
        if (contains) return candidate;
    }
    return null;
};

type ProductImageActionContext = {
    card: any
    image: any
    zone: any | null
}

const isProductImageActionTarget = (obj: any): boolean => {
    if (!obj || String(obj.type || '').toLowerCase() !== 'image') return false
    if (isNamedProductCardImage(obj)) return true
    const smartType = String((obj as any)?.data?.smartType || '').trim().toLowerCase()
    const name = String((obj as any)?.name || '').trim().toLowerCase()
    return smartType === 'product-image' || name === 'smart_image' || name === 'product_image'
}

const resolveSelectedProductImageActionContext = (active?: any): ProductImageActionContext | null => {
    const target = active || canvas.value?.getActiveObject?.()
    if (!target) return null

    const targetType = String(target.type || '').toLowerCase()
    if (targetType === 'group' && !isProductCardContainer(target) && !isLikelyProductCard(target)) {
        return null
    }
    const isCardTarget = isProductCardContainer(target) || isLikelyProductCard(target)
    let resolved: { card: any | null; image: any | null } = { card: null, image: null }
    if (isCardTarget) {
        // A card selection must stay a card selection.  Fabric can resolve the
        // preferred image from any card, but doing that here made the image
        // toolbar appear after a normal card click (and made Duplicate act on
        // the image instead of the whole product).  Only a deliberate image
        // sub-target may opt into the image actions.
        if (selectedProductImageSelectionKind.value !== 'image' || !selectedProductImageSubTarget.value) {
            return null
        }
        const selectedImageContext = resolveSelectedProductCardContext(selectedProductImageSubTarget.value)
        if (selectedImageContext.card !== target || !selectedImageContext.image || selectedImageContext.image !== selectedProductImageSubTarget.value) {
            return null
        }
        resolved = selectedImageContext
    } else if (targetType === 'image') {
        resolved = resolveSelectedProductCardContext(target)
    } else if (targetType === 'activeselection' && typeof target.getObjects === 'function') {
        if (selectedProductImageSelectionKind.value !== 'image') return null
        const selectedMembers = target.getObjects() || []
        const imageMember = selectedProductImageSubTarget.value || selectedMembers.find((member: any) => String(member?.type || '').toLowerCase() === 'image')
        resolved = resolveSelectedProductCardContext(imageMember)
    } else {
        return null
    }
    if (!resolved.card || !resolved.image || !isProductImageActionTarget(resolved.image)) return null

    const zoneId = String(
        (resolved.card as any)?.parentZoneId ||
        (resolved.card as any)?._zoneSlot?.zoneId ||
        ''
    ).trim()
    return {
        card: resolved.card,
        image: resolved.image,
        zone: zoneId ? findProductZoneById(zoneId) : null
    }
}

const updateProductImageSelectionIntent = (event: any) => {
    const target = event?.target
    const subTargets = Array.isArray(event?.subTargets) ? event.subTargets.filter(Boolean) : []
    // Prefer Fabric's actual event target.  `subTargets` can contain a stale
    // image from the previous deep selection when the pointer is over the
    // card's background; using it first made an ordinary card click keep the
    // image toolbar open.  A direct image target is unambiguous.
    if (isProductImageActionTarget(target)) {
        selectedProductImageSubTarget.value = target
        selectedProductImageSelectionKind.value = 'image'
        return
    }
    // Product cards expose their children through subTargetCheck, but the
    // group remains the authoritative click target for card/background areas.
    // Do not promote a child image solely because it appears in subTargets;
    // the image becomes an image selection when Fabric targets it directly.
    if (isProductCardContainer(target) || isLikelyProductCard(target)) {
        selectedProductImageSubTarget.value = null
        selectedProductImageSelectionKind.value = 'card'
        return
    }
    const nonImageCardSubTarget = [...subTargets].reverse().find((item: any) => (
        item !== target &&
        !!findProductCardParentGroup(item) &&
        String(item?.name || '').trim().toLowerCase() !== 'offerbackground'
    ))
    if (nonImageCardSubTarget) {
        selectedProductImageSubTarget.value = null
        selectedProductImageSelectionKind.value = 'other'
        return
    }
    if (target && findProductCardParentGroup(target)) {
        selectedProductImageSubTarget.value = null
        selectedProductImageSelectionKind.value = 'other'
        return
    }
    selectedProductImageSubTarget.value = null
    selectedProductImageSelectionKind.value = 'none'
}

const insertObjectIntoGroupWithoutRelayout = (
    group: any,
    object: any,
    opts: {
        insertAfter?: any;
        localLeft?: number;
        localTop?: number;
    } = {}
): boolean => {
    if (!canvas.value || !group || !object) return false;

    const localLeft = Number(opts.localLeft);
    const localTop = Number(opts.localTop);
    if (Number.isFinite(localLeft) || Number.isFinite(localTop)) {
        object.set?.({
            left: Number.isFinite(localLeft) ? localLeft : (Number((object as any).left) || 0),
            top: Number.isFinite(localTop) ? localTop : (Number((object as any).top) || 0)
        });
    }

    const layoutManager = (group as any).layoutManager;
    const originalPerformLayout = layoutManager?.performLayout;
    if (layoutManager) layoutManager.performLayout = () => {};

    try {
        const groupObjects = typeof (group as any).getObjects === 'function'
            ? ((group as any).getObjects() || [])
            : (Array.isArray((group as any)._objects) ? (group as any)._objects : []);
        const insertAfter = opts.insertAfter;
        const sourceIndex = insertAfter ? groupObjects.indexOf(insertAfter) : -1;
        const insertIndex = sourceIndex >= 0
            ? Math.min(sourceIndex + 1, groupObjects.length)
            : -1;

        if (insertIndex >= 0 && typeof (group as any).insertAt === 'function') {
            (group as any).insertAt(insertIndex, object);
        } else if (Array.isArray((group as any)._objects)) {
            if (insertIndex >= 0) {
                (group as any)._objects.splice(insertIndex, 0, object);
            } else {
                (group as any)._objects.push(object);
            }
            (object as any).group = group;
            object.canvas = canvas.value;
        } else if (typeof (group as any).add === 'function') {
            (group as any).add(object);
        } else {
            return false;
        }
    } finally {
        if (layoutManager) layoutManager.performLayout = originalPerformLayout;
    }

    object.set?.({
        selectable: true,
        evented: true,
        hasControls: true,
        hasBorders: true,
        objectCaching: false,
        noScaleCache: false,
        statefullCache: false,
        dirty: true
    });
    object.setCoords?.();

    group.set?.({ subTargetCheck: true, interactive: true, dirty: true });
    group.setCoords?.();

    if (shouldApplyContainmentConstraints(object)) {
        applyContainmentConstraints(object);
    }

    return true;
};

const getConfiguredProductImageLayout = (card: any): ProductImageCompositionLayout | null => {
    const raw = String((card as any)?._productImageLayout || '').trim().toLowerCase();
    if (raw === 'horizontal' || raw === 'vertical' || raw === 'grid') return raw;
    return null;
};

const layoutProductImagesInCard = (
    card: any,
    opts: {
        layout?: ProductImageCompositionLayout | 'auto';
        preferredCenterY?: number | null;
    } = {}
): number => {
    if (!card || (!isProductCardContainer(card) && !isLikelyProductCard(card))) return 0;
    const images = collectDirectProductCardImages(card);
    if (images.length < 2) return images.length;

    const cardWidth = Math.max(40, Math.abs(Number((card as any)?._cardWidth ?? card?.width ?? 0)) || 40);
    const cardHeight = Math.max(40, Math.abs(Number((card as any)?._cardHeight ?? card?.height ?? 0)) || 40);
    const requestedLayout = opts.layout || getConfiguredProductImageLayout(card) || 'auto';
    const layout = resolveProductImageCompositionLayout(images.length, requestedLayout);
    const plan = buildProductImageCompositionPlan({
        images,
        cardWidth,
        cardHeight,
        layout,
        preferredCenterY: opts.preferredCenterY
    });

    images.forEach((image: any, index: number) => {
        const placement = plan[index];
        if (!placement) return;
        const nextName = index === 0 ? 'smart_image' : `extra_image_${index}`;
        image.set?.({
            left: placement.left,
            top: placement.top,
            scaleX: placement.scaleX,
            scaleY: placement.scaleY,
            originX: 'center',
            originY: 'center',
            name: nextName,
            data: {
                ...((image as any).data && typeof (image as any).data === 'object' ? (image as any).data : {}),
                smartType: 'product-image'
            },
            visible: true,
            flipX: false,
            flipY: false,
            lockScalingFlip: true,
            lockSkewingX: true,
            lockSkewingY: true,
            dirty: true
        });
        (image as any).__manualTransform = true;
        (image as any).__manualTransformCardW = cardWidth;
        (image as any).__manualTransformCardH = cardHeight;
        image.setCoords?.();
        if (shouldApplyContainmentConstraints(image)) applyContainmentConstraints(image);
    });

    (card as any)._productImageLayout = layout;
    (card as any)._productImageLayoutVersion = PRODUCT_IMAGE_COMPOSITION_VERSION;
    try { delete (card as any).__lastCardRelayoutSignature; } catch {}
    card.set?.({ subTargetCheck: true, interactive: true, dirty: true });
    card.setCoords?.();
    return images.length;
};

const repairStackedProductImagesInCard = (card: any, preferredCenterY?: number | null): number => {
    const images = collectDirectProductCardImages(card);
    if (images.length < 2) return images.length;

    const configuredLayout = getConfiguredProductImageLayout(card);
    if (configuredLayout === 'vertical') return images.length;
    const cardWidth = Math.max(40, Math.abs(Number((card as any)?._cardWidth ?? card?.width ?? 0)) || 40);
    const cardHeight = Math.max(40, Math.abs(Number((card as any)?._cardHeight ?? card?.height ?? 0)) || 40);
    const shouldRepair = !!configuredLayout || isStackedDuplicateImageComposition({
        images,
        cardWidth,
        cardHeight,
        requireSameSource: true
    });
    if (!shouldRepair) return images.length;

    return layoutProductImagesInCard(card, {
        layout: configuredLayout || 'horizontal',
        preferredCenterY
    });
};

const duplicateObjectWithContext = async (
    original: any,
    opts: { offsetX?: number; offsetY?: number } = {}
) => {
    if (!canvas.value || !original) return null;
    const offsetX = Number(opts.offsetX ?? DUPLICATE_OFFSET) || 0;
    const offsetY = Number(opts.offsetY ?? DUPLICATE_OFFSET) || 0;

    let cloned: any = null;
    cloned = await cloneFabricObjectSafely(original, DUPLICATE_CLONE_PROPS, 'duplicate');
    if (!cloned) return null;

    assignNewCustomIdsDeep(cloned);
    resetDuplicatedObjectRuntime(cloned);

    const parentCardGroup = findProductCardParentGroup(original);
    const cloneInsideCard =
        !!parentCardGroup &&
        original !== parentCardGroup &&
        !isProductCardContainer(original) &&
        !isActiveSelectionObject(original);

    if (cloneInsideCard && parentCardGroup) {
        const localLeft = Number((original as any).left) || 0;
        const localTop = Number((original as any).top) || 0;
        const canInsertWithoutRelayout = (original as any)?.group === parentCardGroup;

        cloned.set({
            left: canInsertWithoutRelayout ? (localLeft + offsetX) : groupLocalToCanvasPoint(parentCardGroup, localLeft + offsetX, localTop + offsetY).x,
            top: canInsertWithoutRelayout ? (localTop + offsetY) : groupLocalToCanvasPoint(parentCardGroup, localLeft + offsetX, localTop + offsetY).y,
            originX: (original as any).originX || 'center',
            originY: (original as any).originY || 'center',
            angle: (original as any).angle || 0,
            scaleX: (original as any).scaleX || 1,
            scaleY: (original as any).scaleY || 1,
            flipX: !!(original as any).flipX,
            flipY: !!(original as any).flipY,
            opacity: (original as any).opacity ?? 1,
            selectable: true,
            evented: true,
            hasControls: true,
            hasBorders: true,
        });

        // Child clones inside product cards should not carry top-level zone/frame bindings.
        cloned.parentZoneId = undefined;
        cloned.parentFrameId = undefined;

        const inserted = canInsertWithoutRelayout
            ? insertObjectIntoGroupWithoutRelayout(parentCardGroup, cloned, {
                insertAfter: original,
                localLeft: localLeft + offsetX,
                localTop: localTop + offsetY
            })
            : false;

        if (!inserted) {
            safeAddWithUpdate(parentCardGroup, cloned);
            parentCardGroup.set({ subTargetCheck: true, interactive: true });
            parentCardGroup.setCoords?.();
            if (shouldApplyContainmentConstraints(cloned)) {
                applyContainmentConstraints(cloned);
            }
        }
        return cloned;
    }

    cloned.set({
        left: (Number((original as any).left) || 0) + offsetX,
        top: (Number((original as any).top) || 0) + offsetY,
        originX: (original as any).originX || cloned.originX || 'center',
        originY: (original as any).originY || cloned.originY || 'center',
        angle: (original as any).angle || cloned.angle || 0,
        scaleX: (original as any).scaleX || cloned.scaleX || 1,
        scaleY: (original as any).scaleY || cloned.scaleY || 1,
        flipX: !!(original as any).flipX,
        flipY: !!(original as any).flipY,
        opacity: (original as any).opacity ?? cloned.opacity ?? 1,
        selectable: true,
        evented: true,
    });
    if (isProductCardContainer(cloned) || isLikelyProductCard(cloned)) {
        const slot = (cloned as any)?._zoneSlot;
        if (slot && typeof slot === 'object') {
            (cloned as any)._zoneSlot = {
                ...slot,
                left: Number(slot.left || 0) + offsetX,
                top: Number(slot.top || 0) + offsetY
            };
        }
        const zoneId = String((cloned as any).parentZoneId || '').trim();
        if (zoneId) {
            const zone = getContainmentZoneById(zoneId);
            const siblings = zone ? getZoneChildren(zone) : [];
            const maxOrder = siblings.reduce((max: number, card: any) => {
                const order = Number((card as any)?._zoneOrder);
                return Number.isFinite(order) ? Math.max(max, order) : max;
            }, -1);
            (cloned as any)._zoneOrder = maxOrder + 1;
        }
        normalizeProductCardIdentity(cloned, {
            zoneInstanceId: String((cloned as any).parentZoneId || '').trim() || null,
            forceNewInstance: true,
            reason: 'duplicate-card'
        });
        if (import.meta.dev) {
            console.debug('[product-card:duplicate]', {
                sourceObjectId: String((original as any)?._customId || '').trim(),
                clonedObjectId: String((cloned as any)?._customId || '').trim(),
                zoneInstanceId: String((cloned as any)?.parentZoneId || '').trim() || null,
                productId: String((cloned as any)?._productData?.productId || '').trim() || null,
                sourceProductInstanceId: String((original as any)?._productData?.productInstanceId || (original as any)?.productInstanceId || '').trim() || null,
                clonedProductInstanceId: String((cloned as any)?._productData?.productInstanceId || (cloned as any)?.productInstanceId || '').trim() || null,
                selectedObjectId: String(canvas.value.getActiveObject?.()?._customId || '').trim() || null
            });
        }
    }
    canvas.value.add(cloned);

    return cloned;
};

const duplicateProductZoneWithCards = async (
    zone: any,
    opts: { offsetX?: number; offsetY?: number } = {}
) => {
    if (!canvas.value || !zone || !isLikelyProductZone(zone)) return [] as any[];
    const offsetX = Number(opts.offsetX ?? DUPLICATE_OFFSET) || 0;
    const offsetY = Number(opts.offsetY ?? DUPLICATE_OFFSET) || 0;

    if (!(zone as any)._customId) (zone as any)._customId = makeCanvasObjectId();
    const clonedZone = await cloneFabricObjectSafely(zone, DUPLICATE_CLONE_PROPS, 'duplicate-zone');
    if (!clonedZone) return [];

    assignNewCustomIdsDeep(clonedZone);
    resetDuplicatedObjectRuntime(clonedZone);
    clonedZone.set?.({
        left: (Number((zone as any).left) || 0) + offsetX,
        top: (Number((zone as any).top) || 0) + offsetY,
        originX: (zone as any).originX || 'center',
        originY: (zone as any).originY || 'center',
        angle: (zone as any).angle || 0,
        scaleX: (zone as any).scaleX || 1,
        scaleY: (zone as any).scaleY || 1,
        selectable: true,
        evented: true
    });
    clonedZone.isGridZone = true;
    clonedZone.isProductZone = true;
    clonedZone.parentFrameId = (zone as any).parentFrameId;
    clonedZone.clipPath = null;
    delete (clonedZone as any)._frameClipOwner;
    clonedZone.setCoords?.();

    const newZoneId = String((clonedZone as any)._customId || '').trim();
    const zoneFrameId = getResolvedZoneFrameId(clonedZone);
    const sourceCards = getZoneChildren(zone);
    const cardClones: any[] = [];

    for (const card of sourceCards) {
        const clonedCard = await cloneFabricObjectSafely(card, DUPLICATE_CLONE_PROPS, 'duplicate-zone-card');
        if (!clonedCard) continue;
        assignNewCustomIdsDeep(clonedCard);
        resetDuplicatedObjectRuntime(clonedCard);
        clonedCard.set?.({
            left: (Number((card as any).left) || 0) + offsetX,
            top: (Number((card as any).top) || 0) + offsetY,
            originX: (card as any).originX || 'center',
            originY: (card as any).originY || 'center',
            angle: (card as any).angle || 0,
            scaleX: (card as any).scaleX || 1,
            scaleY: (card as any).scaleY || 1,
            selectable: true,
            evented: true
        });
        clonedCard.isProductCard = true;
        clonedCard.isSmartObject = true;
        clonedCard.parentZoneId = newZoneId;
        clonedCard.parentFrameId = zoneFrameId;
        normalizeProductCardIdentity(clonedCard, {
            zoneInstanceId: newZoneId,
            forceNewInstance: true,
            reason: 'duplicate-zone-card'
        });
        clonedCard.clipPath = null;
        delete (clonedCard as any)._frameClipOwner;
        const slot = (card as any)?._zoneSlot;
        clonedCard._zoneSlot = slot && typeof slot === 'object'
            ? {
                ...slot,
                zoneId: newZoneId,
                left: Number(slot.left || 0) + offsetX,
                top: Number(slot.top || 0) + offsetY
            }
            : null;
        clonedCard.setCoords?.();
        cardClones.push(clonedCard);
    }

    if (import.meta.dev) {
        console.debug('[product-zone:duplicate]', {
            sourceZoneInstanceId: String((zone as any)._customId || '').trim(),
            clonedZoneInstanceId: newZoneId,
            selectedObjectId: String(canvas.value.getActiveObject?.()?._customId || '').trim() || null,
            products: sourceCards.map((card: any, index: number) => ({
                sourceObjectId: String((card as any)?._customId || '').trim(),
                clonedObjectId: String((cardClones[index] as any)?._customId || '').trim(),
                productId: String((cardClones[index] as any)?._productData?.productId || (card as any)?._productData?.productId || (card as any)?._productData?.id || '').trim(),
                sourceProductInstanceId: String((card as any)?._productData?.productInstanceId || (card as any)?.productInstanceId || '').trim(),
                clonedProductInstanceId: String((cardClones[index] as any)?._productData?.productInstanceId || (cardClones[index] as any)?.productInstanceId || '').trim()
            }))
        });
    }

    const clones = [clonedZone, ...cardClones];
    clones.forEach((clone: any) => canvas.value?.add(clone));
    finalizeDuplicatedObjects(clones);
    syncZoneCardFrameBindings(clonedZone, cardClones);
    if (cardClones.length > 0) {
        recalculateZoneLayout(clonedZone, cardClones, {
            save: false,
            requestRender: false,
            trustCachedChildren: true,
            preserveStyles: true
        });
    }
    syncZoneDerivedMetadata(clonedZone, undefined, { updateStateSnapshot: true });
    targetGridZone.value = clonedZone;
    targetGridZones.value = resolveRelatedImportZones(clonedZone);
    canvas.value.setActiveObject(clonedZone);
    safeRequestRenderAll();
    refreshCanvasObjects();
    updateSelection();
    return clones;
};

const duplicateActiveObjectWithContext = async (
    active: any,
    opts: { offsetX?: number; offsetY?: number } = {}
) => {
    if (!canvas.value || !active) return [] as any[];

    if (isActiveSelectionObject(active) && typeof (active as any).getObjects === 'function') {
        const members = ((active as any).getObjects?.() || []).slice();
        canvas.value.discardActiveObject();
        const clones: any[] = [];
        for (const member of members) {
            const cloned = await duplicateObjectWithContext(member, opts);
            if (cloned) clones.push(cloned);
        }
        remapDuplicatedSelectionBindings(clones, { reason: 'duplicate-active-selection' });
        return clones;
    }

    const cloned = await duplicateObjectWithContext(active, opts);
    return cloned ? [cloned] : [];
};

// O clipboard Fabric existe somente em memória e é usado por comandos explícitos
// do editor. Ctrl/Cmd+V sempre recebe o conteúdo atual do clipboard do sistema
// pelo evento nativo `paste`; Ctrl/Cmd+Shift+V é o atalho explícito da cópia
// interna, útil ao mudar de página.
const clearLegacyPersistedEditorClipboard = () => {
    if (!import.meta.client) return;
    try {
        window.localStorage.removeItem(LEGACY_CROSS_TAB_CLIPBOARD_STORAGE_KEY);
    } catch {
        // localStorage pode estar indisponível em contextos privados/restritos.
    }
};

const syncEditorClipboardSummary = () => {
    if (!import.meta.client) return;

    const clipboard = (window as any)._clipboard;
    if (clipboard?.kind !== 'fabric-items-v2' || !Array.isArray(clipboard.items) || clipboard.items.length === 0) {
        editorClipboardSummary.value = null;
        return;
    }

    editorClipboardSummary.value = {
        itemCount: clipboard.items.length,
        sourcePageId: String(clipboard.sourcePageId || ''),
        copiedAt: Number(clipboard.copiedAt || 0)
    };
};

const getSelectedClipboardTargetFrame = (candidate: any): { id: string; center: { x: number; y: number } } | null => {
    if (!candidate || (!(candidate as any).isFrame && !isFrameLikeObject(candidate))) return null;
    const id = String((candidate as any)._customId || '').trim();
    if (!id) return null;
    return { id, center: getObjectAbsoluteCenter(candidate) };
};

/**
 * Em uma colagem entre páginas, um Frame explicitamente selecionado é o
 * contêiner de destino. Mantemos vínculos internos quando a própria cópia
 * traz um Frame aninhado, mas todo root restante passa a pertencer ao Frame
 * clicado para que o recorte funcione imediatamente.
 */
const bindPastedRootsToSelectedFrame = (pasted: any[], targetFrameId: string) => {
    if (!targetFrameId || !Array.isArray(pasted) || pasted.length === 0) return;
    const copiedFrameIds = new Set(
        pasted
            .filter((object: any) => !!object && ((object as any).isFrame || isFrameLikeObject(object)))
            .map((object: any) => String((object as any)._customId || '').trim())
            .filter(Boolean)
    );

    pasted.forEach((object: any) => {
        if (!object) return;
        const parentFrameId = String((object as any).parentFrameId || '').trim();
        if (parentFrameId && copiedFrameIds.has(parentFrameId)) return;
        if (typeof object.set === 'function') object.set({ parentFrameId: targetFrameId });
        else object.parentFrameId = targetFrameId;
        object.dirty = true;
        object.setCoords?.();
    });
    invalidateFrameRuntimeCache();
};

// getObjectAbsoluteCenter + computeCentersBoundingCenter extraidos para utils/fabricMeasure.ts.

// regenerateCustomIdsRecursive + remapOrClearBindingsRecursive extraidos
// para utils/fabricObjectOps.ts. Wrapper local injeta makeCanvasObjectId.
const regenerateCustomIdsRecursive = (root: any, idMap: Map<string, string>) =>
    regenerateCustomIdsRecursiveHelper(root, idMap, makeCanvasObjectId)

const reapplyRuntimeVisualPatchesTree = (root: any) => {
    const patchNode = (node: any) => {
        if (!node) return;

        if (isRectObject(node) && (node as any).cornerRadii) {
            applyRectCornerRadiiPatch(node);
        }

        const type = String((node as any)?.type || '').toLowerCase();
        if (type === 'image') {
            // Filters can be present but stale after clone; force a lightweight refresh.
            if (Array.isArray((node as any).filters) && (node as any).filters.length > 0 && typeof (node as any).applyFilters === 'function') {
                try { (node as any).applyFilters(); } catch {}
            }

            // Sticker outline uses a runtime render patch and cache that must be rebuilt on clones.
            if ((node as any).__stickerOutlineEnabled) {
                applyStickerOutlinePatch(node);
                setTimeout(() => {
                    if ((node as any)?.__stickerOutlineEnabled && !(node as any)?.__stickerOutlineCache) {
                        applyStickerOutlinePatch(node);
                    }
                }, 1200);
                setTimeout(() => {
                    if ((node as any)?.__stickerOutlineEnabled && !(node as any)?.__stickerOutlineCache) {
                        applyStickerOutlinePatch(node);
                    }
                }, 3200);
            }
        }

        if (type === 'group' && typeof (node as any).getObjects === 'function') {
            ((node as any).getObjects() || []).forEach((child: any) => patchNode(child));
        }
    };

    patchNode(root);
};

const finalizeDuplicatedObjects = (clones: any[]) => {
    if (!canvas.value || !Array.isArray(clones) || clones.length === 0) return;

    const affectedZones = new Map<string, any>();
    clones.forEach((obj: any) => {
        if (!obj) return;
        resetDuplicatedObjectRuntime(obj);
        reapplyRuntimeVisualPatchesTree(obj);
        if (isProductCardContainer(obj) || isLikelyProductCard(obj)) {
            normalizeProductCardIdentity(obj, {
                zoneInstanceId: String((obj as any)?.parentZoneId || '').trim() || null,
                forceNewInstance: !(obj as any).__productIdentityFresh,
                reason: 'finalize-duplicate'
            });
            (obj as any).__productIdentityFresh = true;
        }
        if (obj?.isFrame) {
            getOrCreateFrameClipRect(obj);
            syncFrameClips(obj);
        } else if (obj?.parentFrameId || obj?._frameClipOwner) {
            syncObjectFrameClip(obj);
        }

        if (shouldApplyContainmentConstraints(obj)) {
            applyContainmentConstraints(obj);
        }

        const zoneId = String((obj as any)?.parentZoneId || '').trim();
        if (!zoneId) return;
        const zone = getContainmentZoneById(zoneId) || canvas.value?.getObjects()?.find((o: any) => (
            isLikelyProductZone(o) && String((o as any)?._customId || '').trim() === zoneId
        ));
        if (!zone) return;
        applyCardFrameBinding(obj, getResolvedZoneFrameId(zone));
        affectedZones.set(zoneId, zone);
    });

    affectedZones.forEach((zone: any) => {
        ensureZoneSanity(zone);
        recalculateZoneLayout(zone, getZoneChildren(zone), { save: false, preserveStyles: true });
    });

    const duplicatedZone = clones.find((obj: any) => obj && !obj?.group && isLikelyProductZone(obj));
    if (duplicatedZone && isLikelyProductZone(duplicatedZone)) {
        targetGridZone.value = duplicatedZone;
        targetGridZones.value = resolveRelatedImportZones(duplicatedZone);
    }

    const topLevelClones = clones.filter((obj: any) => !obj?.group);
    canvas.value.discardActiveObject();
    if (topLevelClones.length > 1 && fabric?.ActiveSelection) {
        const selection = new fabric.ActiveSelection(topLevelClones, { canvas: canvas.value });
        selection.setCoords?.();
        canvas.value.setActiveObject(selection);
    } else {
        clones[0]?.setCoords?.();
        canvas.value.setActiveObject(clones[0]);
    }

    safeRequestRenderAll();
    refreshCanvasObjects();
    updateSelection();
};

/**
 * Reaplica a receita da zona depois que um card foi removido.
 *
 * A remoção altera o total de produtos e, portanto, a variante de estrutura
 * (colunas/linhas, destaque e comportamento da última linha) pode mudar. O
 * relayout precisa acontecer depois do remove, usando apenas os cards ainda
 * vivos; `preserveStyles` mantém as escolhas visuais do card enquanto adapta
 * tamanho e posição ao novo slot.
 */
const relayoutProductZonesAfterCardRemoval = (zones: Iterable<any>): boolean => {
    if (!canvas.value) return false;

    // Removing a child from a nested Fabric group does not necessarily emit a
    // canvas-level `object:removed`, so invalidate the runtime card index
    // explicitly before asking the zone for its remaining children.
    invalidateZoneRuntimeIndex();

    const liveObjects = new Set(canvas.value.getObjects?.() || []);
    let didRelayout = false;
    for (const zone of zones) {
        if (!zone || !isLikelyProductZone(zone) || !liveObjects.has(zone)) continue;
        const cards = getZoneChildren(zone);
        ensureZoneSanity(zone);
        if (cards.length > 0) {
            // A remoção muda a estrutura selecionada por quantidade. Force o
            // relayout dos cards restantes mesmo quando o slot calculado acaba
            // com a mesma dimensão persistida; isso garante que imagens
            // duplicadas e a etiqueta recebam a nova receita da zona.
            cards.forEach((card: any) => {
                (card as any).__forceCardRelayout = true;
                (card as any).__lastCardRelayoutSignature = null;
                (card as any).__lastCardRelayoutAt = 0;
            });
            recalculateZoneLayout(zone, cards, {
                save: false,
                preserveStyles: true
            });
        }
        syncZoneDerivedMetadata(zone);
        didRelayout = true;
    }

    if (didRelayout) {
        refreshCanvasObjects();
        safeRequestRenderAll();
    }
    return didRelayout;
};

const deleteActiveSelectionFromCanvas = (confirmed = false): boolean => {
    if (!canvas.value) return false;

    // Node-editing delete parity (same behavior as keyboard Delete/Backspace).
    if (isNodeEditing.value && selectedPathNodeIndex.value !== null && currentEditingPath.value) {
        removePathPoint(currentEditingPath.value, selectedPathNodeIndex.value);
        return true;
    }

    const active = (canvas.value.getActiveObjects?.() || []).filter((o: any) => !!o);
    if (!active.length) return false;

    // No modo rápido a zona pertence ao modelo e não pode ser removida junto
    // com os produtos. A exclusão disponível nesse fluxo é apenas de páginas
    // já criadas no projeto, nunca de estruturas do template.
    if (isQuickMode.value && active.some((obj: any) => isQuickModeLockedObject(obj))) {
        canvas.value.discardActiveObject?.();
        return false;
    }

    const containsFrameLikeObject = (items: any[]): boolean =>
        items.some((item: any) => !!item && (item.isFrame || isFrameLikeObject(item)));

    if (containsFrameLikeObject(active) && !confirmed) {
        void confirmInSystem('Excluir frame e todo o conteúdo dentro dele?').then(ok => {
            if (ok) deleteActiveSelectionFromCanvas(true);
        });
        return false;
    }

    const deleteTargets = new Set<any>(active);

    // Ao remover um frame, remover em cascata TODO o conteúdo interno (incluindo nested frames).
    active.forEach((obj: any) => {
        if (!obj) return;
        if (!(obj.isFrame || isFrameLikeObject(obj))) return;
        const frameTargets = collectFrameVisibilityTargets(obj);
        frameTargets.forEach((target: any) => {
            if (!target) return;
            if (isControlLikeObject(target) || isTransientCanvasObject(target)) return;
            if (String(target.id || '') === 'artboard-bg') return;
            deleteTargets.add(target);
        });
    });

    // BUG #7: Ao remover uma zona de produtos, remover em cascata todos os cards filhos.
    // CORRECAO: considerar AMBOS parentZoneId e _zoneSlot.zoneId — apos undo/drag, um
    // pode estar stale. Pegar a uniao evita deixar cards "zumbis" no canvas.
    active.forEach((obj: any) => {
        if (!obj || !isLikelyProductZone(obj)) return;
        const zoneId = String((obj as any)._customId || '').trim();
        if (!zoneId) return;
        const allObjects = canvas.value!.getObjects() || [];
        allObjects.forEach((child: any) => {
            if (!child) return;
            const childZoneId = String((child as any).parentZoneId || '').trim();
            const slotZoneId = String((child as any)?._zoneSlot?.zoneId || '').trim();
            if (childZoneId === zoneId || slotZoneId === zoneId) {
                deleteTargets.add(child);
            }
        });
    });

    const activeWithCascade = Array.from(deleteTargets);

    // Keep the zones touched by product-card deletions.  After the object is
    // removed, their configured structure must be resolved again from the new
    // product count instead of leaving the remaining cards in the old slots.
    const affectedProductZones = new Map<string, any>();
    activeWithCascade.forEach((obj: any) => {
        if (!obj || !isLikelyProductCard(obj)) return;
        const zoneId = String(
            (obj as any).parentZoneId ||
            (obj as any)?._zoneSlot?.zoneId ||
            ''
        ).trim();
        if (!zoneId) return;
        const zone = getContainmentZoneById(zoneId) || findProductZoneById(zoneId);
        if (zone) affectedProductZones.set(zoneId, zone);
    });

    // Collect objects to delete - separate those in real groups vs canvas root
    const toDeleteFromCanvas: any[] = [];
    const toDeleteFromGroup: { obj: any, group: any }[] = [];

    for (const obj of activeWithCascade) {
        // Get the group reference, but IGNORE ActiveSelection
        let parentGroup = (obj as any).group;

        // CRITICAL: ActiveSelection is NOT a real parent group - skip it
        if (parentGroup && (
            parentGroup.type === 'activeSelection' ||
            parentGroup.type === 'ActiveSelection' ||
            String(parentGroup.type || '').toLowerCase() === 'activeselection'
        )) {
            parentGroup = null;
        }

        // Try global search if no direct parent found
        if (!parentGroup) {
            parentGroup = findParentGroupForObjectGlobal(obj);
        }

        // Double-check it's not an ActiveSelection
        if (parentGroup && (
            parentGroup.type === 'activeSelection' ||
            parentGroup.type === 'ActiveSelection' ||
            String(parentGroup.type || '').toLowerCase() === 'activeselection'
        )) {
            parentGroup = null;
        }

        if (parentGroup && typeof parentGroup.remove === 'function') {
            toDeleteFromGroup.push({ obj, group: parentGroup });
        } else {
            toDeleteFromCanvas.push(obj);
        }
    }

    // First discard active selection to release objects
    canvas.value.discardActiveObject();

    // Delete from groups first
    for (const { obj, group } of toDeleteFromGroup) {
        try {
            group.remove(obj);
            group.set('dirty', true);
            if (typeof group.setCoords === 'function') group.setCoords();
        } catch (err) {
            console.warn('[Delete] Erro ao remover do grupo, tentando canvas:', err);
            try { canvas.value.remove(obj); } catch {}
        }
    }

    // Delete from canvas
    for (const obj of toDeleteFromCanvas) {
        try {
            // Grid cell: also delete all sibling cells and their children
            if ((obj as any).isGridCell && (obj as any).gridGroupId) {
                const gid = (obj as any).gridGroupId;
                const siblings = canvas.value.getObjects().filter(
                    (o: any) => o !== obj && o.gridGroupId === gid && o.isGridCell
                );
                for (const sib of siblings) {
                    // Remove children parented to this cell
                    const children = canvas.value.getObjects().filter(
                        (ch: any) => ch.parentFrameId === sib._customId
                    );
                    children.forEach((ch: any) => { try { canvas.value!.remove(ch); } catch {} });
                    try { canvas.value.remove(sib); } catch {}
                }
                // Remove children of the deleted cell itself
                const ownChildren = canvas.value.getObjects().filter(
                    (ch: any) => ch.parentFrameId === (obj as any)._customId
                );
                ownChildren.forEach((ch: any) => { try { canvas.value!.remove(ch); } catch {} });
            }
            canvas.value.remove(obj);
        } catch (err) {
            console.warn('[Delete] Erro ao remover do canvas:', err);
        }
    }

    // CORRECAO: quando um frame e deletado, limpar os filhos diferidos dele (e dos
    // descendentes). Sem isso, o serializador injeta de volta filhos de frames
    // invisiveis que ja foram excluidos, "ressuscitando" conteudo deletado.
    if (deferredFrameChildren.size > 0) {
        for (const obj of activeWithCascade) {
            if (!obj) continue;
            if (!(obj as any).isFrame && !isFrameLikeObject(obj)) continue;
            const frameId = String((obj as any)._customId || (obj as any).customId || '').trim();
            if (frameId && deferredFrameChildren.has(frameId)) {
                deferredFrameChildren.delete(frameId);
            }
        }
        // Limpa tambem entradas cujo parente nao exista mais no canvas.
        if (deferredFrameChildren.size > 0) {
            const liveFrameIds = new Set<string>();
            for (const o of canvas.value.getObjects() || []) {
                if ((o as any)?.isFrame) {
                    const id = String((o as any)._customId || (o as any).customId || '').trim();
                    if (id) liveFrameIds.add(id);
                }
            }
            for (const key of Array.from(deferredFrameChildren.keys())) {
                if (!liveFrameIds.has(key)) deferredFrameChildren.delete(key);
            }
        }
    }

    relayoutProductZonesAfterCardRemoval(affectedProductZones.values());

    safeRequestRenderAll();
    refreshCanvasObjects();
    updateSelection();
    saveCurrentState({ reason: affectedProductZones.size > 0 ? 'product-card-delete' : 'delete' });
    return true;
};

const handleKeyDown = async (
    e: KeyboardEvent,
    options: { explicitEditorPaste?: boolean } = {}
) => {
    const pasteShortcut = ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'v') || (e.shiftKey && e.key === 'Insert');
    if (isQuickMode.value && (options.explicitEditorPaste || pasteShortcut)
        && !isEditableClipboardTarget(e.target)
        && !(canvas.value?.getActiveObject?.() as any)?.isEditing) {
        e.preventDefault();
        e.stopPropagation();
        return;
    }
    return getEditorCanvasActionsController().handleKeyDown(e, options);
};

const runEditorClipboardCommand = async (action: 'copy' | 'paste') => {
    if (isQuickMode.value && action === 'paste') return;
    await handleKeyDown(
        new KeyboardEvent('keydown', {
            key: action === 'copy' ? 'c' : 'v',
            ctrlKey: true,
            shiftKey: action === 'paste'
        }),
        { explicitEditorPaste: action === 'paste' }
    );
};

