    setDomCanvasTouchEndHandler: (value: ((e: TouchEvent) => void) | null) => { domCanvasTouchEndHandler = value },
    setDomCanvasTouchCancelHandler: (value: ((e: TouchEvent) => void) | null) => { domCanvasTouchCancelHandler = value },
    getLastDomDblClickAt: () => lastDomDblClickAt,
    setLastDomDblClickAt: (value: number) => { lastDomDblClickAt = value },
    getIsSpacePanPressed: () => isSpacePanPressed,
