    getTeardownReactivity: () => teardownReactivity,
    setTeardownReactivity: (value: (() => void) | null) => { teardownReactivity = value },
    getSaveCurrentState: () => saveCurrentState,
    getIsBulkProductMutation: () => isBulkProductMutation,
    getIsCanvasJsonLoadInProgress: () => isCanvasJsonLoadInProgress,
    getHistoryRestoreCooldownUntil: () => _historyRestoreCooldownUntil,
    setLastTransformMutationAt: (value: number) => { lastTransformMutationAt = value },
    setResetAllDeepSelectPriceGroupsRef: (value: (() => void) | null) => { resetAllDeepSelectPriceGroupsRef = value }
})

const getEditorReactivityController = () =>
    createEditorReactivityController(getEditorReactivityContext())

const setupReactivity = () => getEditorReactivityController().setupReactivity()

// Properties Updates
const updatePageSettings = (prop: string, value: any) => {
    if (prop === 'backgroundColor') {
        pageSettings.value.backgroundColor = value;
        if (canvas.value) {
            // Convert rgba to hex if needed for canvas background
            let bgColor = value;
            if (value.startsWith('rgba')) {
                // Extract RGB values (ignore alpha for canvas background)
                const rgba = value.match(/rgba?\(([^)]+)\)/);
                if (rgba) {
                    const parts = rgba[1].split(',').map((s: string) => s.trim());
                    const r = parseInt(parts[0]);
                    const g = parseInt(parts[1]);
                    const b = parseInt(parts[2]);
                    bgColor = `rgb(${r}, ${g}, ${b})`;
                }
            }
            canvas.value.backgroundColor = bgColor;
            safeRequestRenderAll();
            saveCurrentState();
        }
        // Also update activePage background
        if (activePage.value) {
            (activePage.value as any).backgroundColor = value;
            const currentCanvasData = project.pages?.[project.activePageIndex]?.canvasData;
            if (currentCanvasData && typeof currentCanvasData === 'object') {
                updatePageData(project.activePageIndex, { ...currentCanvasData, backgroundColor: value });
            }
        }
    }
}

// Wrapper local: injeta fabric.util.invertTransform/transformPoint no helper puro.
const getViewportBounds = () => {
    if (!canvas.value || !fabric?.util) return null;
    return computeViewportBoundsInWorld(
        canvas.value.viewportTransform,
        canvas.value.getWidth(),
        canvas.value.getHeight(),
        fabric.util.invertTransform,
        fabric.util.transformPoint
    );
};

const alignSelectionHorizontally = (mode: 'left' | 'center' | 'right') => {
    if (!canvas.value || !fabric?.Point) return;
    const active = canvas.value.getActiveObject();
    if (!active) return;

    const alignOne = (obj: any, ref: { left: number; right: number; centerX: number }) => {
        if (obj?.lockMovementX || obj?.lockMovementY) return;
        const br = obj.getBoundingRect(true);
        const currentCenter = obj.getCenterPoint ? obj.getCenterPoint() : { x: obj.left, y: obj.top };
        let nextCenterX = currentCenter.x;
        if (mode === 'left') nextCenterX = ref.left + (br.width / 2);
        if (mode === 'center') nextCenterX = ref.centerX;
        if (mode === 'right') nextCenterX = ref.right - (br.width / 2);

        obj.setPositionByOrigin(new fabric.Point(nextCenterX, currentCenter.y), 'center', 'center');
        obj.setCoords();
    };

    if (active.type === 'activeSelection' && typeof active.getObjects === 'function') {
        const sel = active.getBoundingRect(true);
        const ref = { left: sel.left, right: sel.left + sel.width, centerX: sel.left + (sel.width / 2) };
        active.getObjects().forEach((obj: any) => alignOne(obj, ref));
        safeAddWithUpdate(active);
        active.setCoords();
    } else {
        // Single object: align to parent frame if any, else align to page (0..W/H).
        const parentFrameId = String((active as any)?.parentFrameId || '').trim();
        const frame = parentFrameId ? getFrameById(parentFrameId) : null;
        const fb = frame ? getFrameBounds(frame) : null;
        const pageW = activePage.value?.width ?? 1080;
        const ref = fb
            ? { left: fb.left, right: fb.left + fb.width, centerX: fb.left + (fb.width / 2) }
            : { left: 0, right: pageW, centerX: pageW / 2 };
        alignOne(active, ref);
    }

    safeRequestRenderAll();
    saveCurrentState();
    triggerRef(selectedObjectRef);
};

const alignSelectionVertically = (mode: 'top' | 'middle' | 'bottom') => {
    if (!canvas.value || !fabric?.Point) return;
    const active = canvas.value.getActiveObject();
    if (!active) return;

    const alignOne = (obj: any, ref: { top: number; bottom: number; centerY: number }) => {
        if (obj?.lockMovementX || obj?.lockMovementY) return;
        const br = obj.getBoundingRect(true);
        const currentCenter = obj.getCenterPoint ? obj.getCenterPoint() : { x: obj.left, y: obj.top };
        let nextCenterY = currentCenter.y;
        if (mode === 'top') nextCenterY = ref.top + (br.height / 2);
        if (mode === 'middle') nextCenterY = ref.centerY;
        if (mode === 'bottom') nextCenterY = ref.bottom - (br.height / 2);

        obj.setPositionByOrigin(new fabric.Point(currentCenter.x, nextCenterY), 'center', 'center');
        obj.setCoords();
    };

    if (active.type === 'activeSelection' && typeof active.getObjects === 'function') {
        const sel = active.getBoundingRect(true);
        const ref = { top: sel.top, bottom: sel.top + sel.height, centerY: sel.top + (sel.height / 2) };
        active.getObjects().forEach((obj: any) => alignOne(obj, ref));
        safeAddWithUpdate(active);
        active.setCoords();
    } else {
        const parentFrameId = String((active as any)?.parentFrameId || '').trim();
        const frame = parentFrameId ? getFrameById(parentFrameId) : null;
        const fb = frame ? getFrameBounds(frame) : null;
        const pageH = activePage.value?.height ?? 1920;
        const ref = fb
            ? { top: fb.top, bottom: fb.top + fb.height, centerY: fb.top + (fb.height / 2) }
            : { top: 0, bottom: pageH, centerY: pageH / 2 };
        alignOne(active, ref);
    }

    safeRequestRenderAll();
    saveCurrentState();
    triggerRef(selectedObjectRef);
};

const centerSelectionInContainer = (mode: 'h' | 'v' | 'both') => {
    if (!canvas.value || !fabric?.Point) return;
    const active = canvas.value.getActiveObject();
    if (!active) return;

    const getContainer = (obj: any) => {
        const parentFrameId = String((obj as any)?.parentFrameId || '').trim();
        const frame = parentFrameId ? getFrameById(parentFrameId) : null;
        const fb = frame ? getFrameBounds(frame) : null;
        const pageW = activePage.value?.width ?? 1080;
        const pageH = activePage.value?.height ?? 1920;
        return fb
            ? { left: fb.left, top: fb.top, right: fb.left + fb.width, bottom: fb.top + fb.height, centerX: fb.left + (fb.width / 2), centerY: fb.top + (fb.height / 2) }
            : { left: 0, top: 0, right: pageW, bottom: pageH, centerX: pageW / 2, centerY: pageH / 2 };
    };

    const applyTo = (obj: any, container: any) => {
        if (obj?.lockMovementX || obj?.lockMovementY) return;
        const center = obj.getCenterPoint ? obj.getCenterPoint() : { x: obj.left, y: obj.top };
        const nextX = mode === 'v' ? center.x : container.centerX;
        const nextY = mode === 'h' ? center.y : container.centerY;
        obj.setPositionByOrigin(new fabric.Point(nextX, nextY), 'center', 'center');
        obj.setCoords();
    };

    if (active.type === 'activeSelection' && typeof active.getObjects === 'function') {
        // Multi-selection: center relative to selection bounds.
        const sel = active.getBoundingRect(true);
        const container = { centerX: sel.left + (sel.width / 2), centerY: sel.top + (sel.height / 2) };
        active.getObjects().forEach((obj: any) => applyTo(obj, container));
        safeAddWithUpdate(active);
        active.setCoords();
    } else {
        const container = getContainer(active);
        applyTo(active, container);
    }

    safeRequestRenderAll();
    saveCurrentState();
    triggerRef(selectedObjectRef);
};

// INSPECTOR_TRANSFORM_PROPS extraida para utils/globalStylePropClassifiers.ts.

const resolveInspectorSnapshotTarget = (active: any) => {
    if (!active || active.type === 'activeSelection') return active;

    const snapshot = selectedObjectRef.value as any;
    const snapshotId = String(snapshot?._customId || '').trim();
    const activeId = String((active as any)?._customId || '').trim();
    if (!snapshotId || snapshotId === activeId) {
        if (String(snapshot?.type || '').toLowerCase() === 'group' && String(snapshot?.name || '').trim() === 'priceGroup') {
            return getPriceGroupFromAny(active) || active;
        }
        return active;
    }

    const found = findObjectByCustomId(snapshotId)?.obj;
    if (!found) return active;

    const sameCard = (() => {
        const activeCard = getCardGroupFromAny(active);
        const foundCard = getCardGroupFromAny(found);
        return !!(activeCard && foundCard && activeCard === foundCard);
    })();
    const samePriceGroup = (() => {
        const activePriceGroup = getPriceGroupFromAny(active);
        const foundPriceGroup = getPriceGroupFromAny(found);
        return !!(activePriceGroup && foundPriceGroup && activePriceGroup === foundPriceGroup);
    })();

    if (found === active || found.group === active || active.group === found || sameCard || samePriceGroup) {
        return found;
    }

    const deepActive = (active as any)?._activeObject;
    const deepActiveId = String((deepActive as any)?._customId || '').trim();
    if (deepActive && deepActiveId === snapshotId) {
        return deepActive;
    }

    return active;
};

const markInspectorTransformAsManual = (target: any, prop: string) => {
    if (!target || !INSPECTOR_TRANSFORM_PROPS.has(prop)) return;

    const priceGroup = getPriceGroupFromAny(target);
    const cardHost = (
        getCardHostForPriceGroup(priceGroup) ||
        getCardGroupFromAny(target) ||
        getCardGroupFromAny(priceGroup)
    );
    const cardW = Number((cardHost as any)?._cardWidth ?? cardHost?.width ?? cardHost?.getScaledWidth?.() ?? 0);
    const cardH = Number((cardHost as any)?._cardHeight ?? cardHost?.height ?? cardHost?.getScaledHeight?.() ?? 0);

    const markOne = (obj: any) => {
        if (!obj || typeof obj !== 'object') return;
        (obj as any).__manualTransform = true;
        if (Number.isFinite(cardW) && cardW > 0) {
            (obj as any).__manualTransformCardW = cardW;
        }
        if (Number.isFinite(cardH) && cardH > 0) {
            (obj as any).__manualTransformCardH = cardH;
        }
    };

    markOne(target);
    // Apenas transformações aplicadas ao bloco externo da etiqueta devem
    // vencer a receita de posição/tamanho configurada em Cards. Alterações em
    // textos ou outros nós internos mantêm __manualTransform para preservar o
    // conteúdo, mas não congelam a etiqueta no centro do card.
    if (priceGroup && priceGroup === target) {
        (priceGroup as any).__manualPricePosition = true;
    }
    if (priceGroup && priceGroup !== target) {
        markOne(priceGroup);
    }
};

const markPriceGroupTransformAsManual = (group: any) => {
    if (!group || String(group?.type || '').toLowerCase() !== 'group') return;
    if (String(group?.name || '') !== 'priceGroup') return;
    (group as any).__manualPricePosition = true;
    markInspectorTransformAsManual(group, 'top');
    markPriceGroupAsManuallyCustomized(group, { captureSnapshot: false });
};

const updatePriceGroupManualScaleOverride = (group: any, axis: 'x' | 'y', nextScaleRaw: unknown) => {
    if (!group || String(group?.type || '').toLowerCase() !== 'group') return null;
    if (String(group?.name || '').trim() !== 'priceGroup') return null;

    const scaleKey = axis === 'x' ? 'scaleX' : 'scaleY';
    const manualKey = axis === 'x' ? '__manualScaleX' : '__manualScaleY';
    const currentScale = Math.abs(Number(group?.[scaleKey] ?? 1)) || 1;
    const nextScale = Math.max(0.01, Math.abs(Number(nextScaleRaw)) || currentScale);
    const currentManual = Math.abs(Number((group as any)?.[manualKey] ?? 1)) || 1;
    const ratio = currentScale > 0.0001 ? (nextScale / currentScale) : 1;

    if (Number.isFinite(ratio) && ratio > 0) {
        (group as any)[manualKey] = currentManual * ratio;
    }

    return nextScale;
};

const updateObjectProperty = (prop: string, value: any) =>
    getEditorCanvasActionsController().updateObjectProperty(prop, value);

const applySmartStyle = (group: any, key: string, value: any) => {
    // Traverse group to find specific sub-elements
    const objects = group.getObjects();

    // 1. Price Components
    if (key.startsWith('price')) {
         const priceGroup = objects.find((o: any) => o.name === 'priceGroup');
         if (priceGroup) {
             const priceParts = priceGroup.getObjects();
             priceParts.forEach((p: any) => {
                 if (key === 'priceFill') p.set('fill', value);
                 if (key === 'priceFont') p.set('fontFamily', value);
             });
         }
    }

    // 2. Splash/Background
    if (key === 'splashFill') {
        const bg = objects.find((o: any) => o.name === 'offerBackground');
        if (bg && !(value === null || value === undefined || value === '')) bg.set('fill', value);
    }

    safeAddWithUpdate(group);
}

const updateSmartGroup = (keyOrUpdates: any, value?: any) => {
    if (!canvas.value) return;

    // Handle Global Sync (Object payload)
    if (typeof keyOrUpdates === 'object' && keyOrUpdates.targetType) {
        const { targetType, property, value } = keyOrUpdates;

        // Find all groups in the same zone (if applicable, or all smart groups)
        // For now, let's target ALL smartGroups on canvas for maximum effect as requested ("Alterar um, alterar todos")
        const allSmartGroups = canvas.value.getObjects().filter((o: any) => o.subTargetCheck && o.data?.isProductCard);

        allSmartGroups.forEach((group: any) => {
             const objects = group.getObjects();

             // Recursively find matching child
             const findAndUpdate = (objs: any[]) => {
                 objs.forEach(obj => {
                     if (obj.data?.smartType === targetType) {
                         obj.set(property, value);
                         // Special case for font, might need re-positioning?
                         // Fabric usually handles it, but group might need recalc
                     }

                     if (obj.type === 'group') {
                         findAndUpdate(obj.getObjects());
                     }
                 })
             }

             findAndUpdate(objects);
             safeAddWithUpdate(group);
        });

        safeRequestRenderAll();
        saveCurrentState();
        return;
    }

    // Existing Logic (Price Mode etc)
    let updates: any = {};
    if (typeof keyOrUpdates === 'string') {
        updates[keyOrUpdates] = value;
    } else {
        updates = keyOrUpdates;
    }

    // Identificar o card selecionado — só ele será alterado para mudanças estruturais.
    const active = canvas.value.getActiveObject();
    let selectedCard: any = null;
    if (active) {
        if ((active as any).isSmartObject || (active as any).isProductCard) {
            selectedCard = active;
        } else if (active.group && ((active.group as any).isSmartObject || (active.group as any).isProductCard)) {
            selectedCard = active.group;
        }
    }

    // Para mudanças visuais (cor, fonte, bg), aplicar no card selecionado.
    // Para mudanças estruturais (priceMode), aplicar SOMENTE no card selecionado.
    const targetCards = selectedCard ? [selectedCard] : [];

    // Helper para buscar filhos recursivamente por nome (suporta nomes legacy e atacarejo)
    const findChildDeep = (parent: any, ...names: string[]): any => {
        if (!parent || typeof parent.getObjects !== 'function') return null;
        const all = collectObjectsDeep(parent);
        for (const name of names) {
            const found = all.find((o: any) => o?.name === name);
            if (found) return found;
        }
        return null;
    };

    targetCards.forEach((group: any) => {
        // --- Style Updates ---
        if (updates.priceColor) {
             // Buscar tanto nomes legados quanto atacarejo
             const richTxt = findChildDeep(group, 'price_value_text', 'retail_price_text', 'wholesale_price_text');
             if (richTxt) {
                 setRichPriceSegmentStyle(richTxt, 'integer', { fill: updates.priceColor });
                 setRichPriceSegmentStyle(richTxt, 'decimal', { fill: updates.priceColor });
                 richTxt.set('fill', updates.priceColor);
             }
             const intTxt = findChildDeep(group, 'priceInteger', 'price_integer_text', 'retail_integer_text');
             if (intTxt) intTxt.set('fill', updates.priceColor);
             const decTxt = findChildDeep(group, 'priceDecimal', 'price_decimal_text', 'retail_decimal_text');
             if (decTxt) decTxt.set('fill', updates.priceColor);
             const symTxt = findChildDeep(group, 'priceSymbol', 'price_currency_text', 'retail_currency_text');
             if (symTxt) symTxt.set('fill', updates.priceColor);
        }

        if (updates.priceFont) {
             const richTxt = findChildDeep(group, 'price_value_text', 'retail_price_text', 'wholesale_price_text');
             if (richTxt) {
                 setRichPriceSegmentStyle(richTxt, 'integer', { fontFamily: updates.priceFont });
                 setRichPriceSegmentStyle(richTxt, 'decimal', { fontFamily: updates.priceFont });
                 richTxt.set('fontFamily', updates.priceFont);
             }
             const intTxt = findChildDeep(group, 'priceInteger', 'price_integer_text', 'retail_integer_text');
             if (intTxt) intTxt.set('fontFamily', updates.priceFont);
             const decTxt = findChildDeep(group, 'priceDecimal', 'price_decimal_text', 'retail_decimal_text');
             if (decTxt) decTxt.set('fontFamily', updates.priceFont);
             const symTxt = findChildDeep(group, 'priceSymbol', 'price_currency_text', 'retail_currency_text');
             if (symTxt) symTxt.set('fontFamily', updates.priceFont);
        }

        if(updates.bgColor) {
             const bg = findChildDeep(group, 'offerBackground');
             if (bg) bg.set('fill', updates.bgColor);
        }

        // --- Structural Updates (Price Mode Engine) ---
        if (updates.priceMode !== undefined || updates.priceFrom !== undefined || updates.priceClub !== undefined) {
             // 1. Atualizar metadados no grupo
             if (updates.priceMode) group.priceMode = updates.priceMode;
             if (updates.priceFrom !== undefined) group.priceFrom = updates.priceFrom;
             if (updates.priceClub !== undefined) group.priceClub = updates.priceClub;
             // Campos atacarejo
             if (updates.priceWholesale !== undefined) group.priceWholesale = updates.priceWholesale;
             if (updates.wholesaleTrigger !== undefined) group.wholesaleTrigger = updates.wholesaleTrigger;
             if (updates.wholesaleTriggerUnit !== undefined) group.wholesaleTriggerUnit = updates.wholesaleTriggerUnit;
             if (updates.packQuantity !== undefined) group.packQuantity = updates.packQuantity;
             if (updates.packUnit !== undefined) group.packUnit = updates.packUnit;

             // 2. Extrair dados do card para reconstruir (busca nomes legacy + atacarejo)
              const intTxt = findChildDeep(group, 'priceInteger', 'price_integer_text', 'retail_integer_text', 'wholesale_integer_text');
              const decTxt = findChildDeep(group, 'priceDecimal', 'price_decimal_text', 'retail_decimal_text', 'wholesale_decimal_text');
               const richTxt = findChildDeep(group, 'price_value_text', 'retail_price_text', 'wholesale_price_text');
              const currentPrice = richTxt?.text
                 ? String(richTxt.text)
                 : (intTxt && decTxt)
                 ? (intTxt.text + decTxt.text).replace(',', '.')
                 : "0.00";

              const unitObj = findChildDeep(group, 'priceUnit', 'price_unit_text', 'retail_unit_text', 'wholesale_unit_text');

             // Recuperar dados de produto armazenados no card (se existirem)
             const storedData = (group as any)._productData || {};

             const mockProduct = {
                 name: storedData.name || group.productName || '',
                 offerFormat: storedData.offerFormat,
                 price: currentPrice,
                 priceUnit: storedData.priceUnit ?? (group as any).priceUnit ?? currentPrice,
                 pricePack: storedData.pricePack ?? (group as any).pricePack ?? null,
                 priceSpecial: storedData.priceSpecial ?? (group as any).priceSpecial ?? null,
                 priceSpecialUnit: storedData.priceSpecialUnit ?? (group as any).priceSpecialUnit ?? null,
                 priceMode: group.priceMode,
                 priceFrom: group.priceFrom,
                 priceClub: group.priceClub,
                  priceColor: richTxt?.fill ?? intTxt?.fill ?? 'red',
                 // Sem fallback fantasma para 'UN': se o produto/etiqueta nao tem
                 // unidade definida, deixa vazio e a renderizacao decide pelo template.
                 unit: unitObj ? unitObj.text : (storedData.unit || ''),
                 // Atacarejo
                 priceWholesale: group.priceWholesale,
                 wholesaleTrigger: group.wholesaleTrigger,
                 wholesaleTriggerUnit: group.wholesaleTriggerUnit,
                 packQuantity: group.packQuantity ?? storedData.packQuantity,
                 packUnit: group.packUnit ?? storedData.packUnit,
                 packageLabel: (group as any).packageLabel ?? storedData.packageLabel,
                 specialCondition: (group as any).specialCondition ?? storedData.specialCondition,
                 observation: storedData.observation ?? storedData.observacao,
             };

             // 3. Localizar grupo de preço antigo
             const objects = group.getObjects();
             const oldPg = objects.find((o: any) => o.name === 'priceGroup');
             const bg = objects.find((o: any) => o.name === 'offerBackground');
             const internalWidth = bg ? bg.width : ((group as any)._cardWidth || 200);

             if (oldPg) {
                 const oldTop = oldPg.top;
                 const cardH = bg ? bg.height : ((group as any)._cardHeight || (internalWidth * 1.4));

                 // 4. Gerar novo layout de preço (agora suporta todos os modos)
                 const newPriceGroup = createPriceLayout(mockProduct, internalWidth, oldTop);

                 // 5. Trocar
                 group.remove(oldPg);
                 group.add(newPriceGroup);

                 // 6. Reaplicar estilos da zona (escala, cor, fonte) no novo price group
                 //    Sem isso o novo price group perde escala e propriedades visuais da zona.
                 const parentZoneId = String((group as any)?.parentZoneId || '').trim();
                 const parentZone = parentZoneId ? findProductZoneById(parentZoneId) : null;
                 const zoneStyles = parentZone
                     ? getZoneGlobalStyles(parentZone)
                     : (typeof normalizeGlobalStyles === 'function' ? normalizeGlobalStyles(productZoneState.globalStyles.value) : null);

                 if (zoneStyles && cardH > 0 && internalWidth > 0) {
                     // Aplicar estilos visuais (fonte, cor, escala) no novo price group
                     applyGlobalStylesToCards(zoneStyles, parentZone || null, { cards: [group] });
                 }
             }
        }

        safeAddWithUpdate(group);
    });

    safeRequestRenderAll();
    saveCurrentState();
}

const buildRemoveBgRequest = async (imageUrl: string) => {
    if (imageUrl.startsWith('blob:') || imageUrl.startsWith('data:')) {
        const blob = await (await fetch(imageUrl)).blob();
        const formData = new FormData();
        const mime = String(blob.type || '').toLowerCase();
        const ext = mime.includes('jpeg') || mime.includes('jpg')
            ? 'jpg'
            : mime.includes('png')
                ? 'png'
                : mime.includes('webp')
                    ? 'webp'
                    : 'png';
        formData.append('file', blob, `image.${ext}`);
        formData.append('overwrite', '1');
        return { body: formData as any };
    }

    // Garantir URL absoluta para o backend (Node fetch não aceita URL relativa).
    let normalizedUrl = imageUrl;
    if (imageUrl.startsWith('/')) {
        normalizedUrl = new URL(imageUrl, window.location.origin).toString();
    }

    let sourceKey: string | null = null;
    try {
        const parsed = new URL(normalizedUrl);
        if (/\/api\/storage\/(?:proxy|p)\/?$/i.test(String(parsed.pathname || ''))) {
            sourceKey = parsed.searchParams.get('key');
        }
    } catch {
        // ignore
    }

    return {
        body: {
            imageUrl: normalizedUrl,
            sourceKey: sourceKey || undefined,
            overwrite: true
        } as any
    };
};

const resolveActiveTextObjectForInspectorAction = (active: any) => {
    if (isTextStyleObject(active)) return active;

    const deepActive = (active as any)?._activeObject;
    if (isTextStyleObject(deepActive)) return deepActive;

    const snapshot = selectedObjectRef.value as any;
    const snapshotId = String(snapshot?._customId || '').trim();
    if (snapshotId) {
        const found = findObjectByCustomId(snapshotId)?.obj;
        if (found && isTextStyleObject(found)) return found;
    }

    const snapName = String(snapshot?.name || '').trim();
    const snapText = String(snapshot?.text ?? '');
    const walkForText = (node: any): any => {
        if (!node) return null;
        if (isTextStyleObject(node)) {
            const sameName = snapName && String(node?.name || '').trim() === snapName;
            const sameText = snapText && String(node?.text ?? '') === snapText;
            if (sameName || sameText) return node;
        }
        const t = String(node?.type || '').toLowerCase();
        if ((t === 'group' || t === 'activeselection') && typeof node.getObjects === 'function') {
            const children = node.getObjects() || [];
            for (const child of children) {
                const nested = walkForText(child);
                if (nested) return nested;
            }
        }
        return null;
    };

    const fromActive = walkForText(active);
    if (fromActive) return fromActive;
    if (canvas.value) {
        for (const obj of canvas.value.getObjects()) {
            const nested = walkForText(obj);
            if (nested) return nested;
        }
    }
    return null;
};

// Wrapper local que extrai dimensoes do target Fabric e injeta
// no helper puro computeLinearGradientCoords + instancia Gradient.
const buildLinearGradientFill = (
    target: any,
    colorStops: ReadonlyArray<{ offset: number; color: string }>,
    angleDeg: number = 90
) => {
    const width = Number(target?.width || target?.getScaledWidth?.() || 1)
    const height = Number(target?.height || target?.getScaledHeight?.() || 1)
    return new fabric.Gradient({
        type: 'linear',
        coords: computeLinearGradientCoords(width, height, angleDeg),
        colorStops
    })
}

const applyTextGradientPreset = (textObj: any, preset: 'gold' | 'sunset' = 'gold') => {
    const presets = {
        gold: {
            angle: 90,
            stops: [
                { offset: 0, color: '#7A1B00' },
                { offset: 0.2, color: '#C63A00' },
                { offset: 0.48, color: '#FFD45D' },
                { offset: 0.62, color: '#FFF5BD' },
                { offset: 0.82, color: '#FFB33D' },
                { offset: 1, color: '#9B2600' }
            ]
        },
        sunset: {
            angle: 72,
            stops: [
                { offset: 0, color: '#7F1D1D' },
                { offset: 0.36, color: '#FB923C' },
                { offset: 0.68, color: '#FDE047' },
                { offset: 1, color: '#B91C1C' }
            ]
        }
    } as const;

    const selected = presets[preset] || presets.gold;
    textObj.set('fill', buildLinearGradientFill(textObj, selected.stops, selected.angle));
    textObj.dirty = true;
};

