// Wrapper local: usa o helper puro computeViewportCenterInWorld.
const getCenterOfView = () => {
    if (!canvas.value) return { x: 0, y: 0 };
    return computeViewportCenterInWorld(
        canvas.value.viewportTransform,
        canvas.value.getWidth?.() || 0,
        canvas.value.getHeight?.() || 0,
        canvas.value.getZoom?.() || 1
    );
}

const { uploadFile } = useUpload()

const resolveTrimmedInsertUrl = async (rawUrl: string, version?: any): Promise<string> => {
    const proxiedUrl = toWasabiProxyUrl(rawUrl, { version: version || null }) || rawUrl
    try {
        const trimmedFile = await fetchAndTrimImageFile(proxiedUrl)
        if (!trimmedFile) return proxiedUrl
        const uploaded = await uploadFile(trimmedFile)
        if (uploaded?.success && uploaded.url) {
            return toWasabiProxyUrl(uploaded.url) || uploaded.url
        }
        return URL.createObjectURL(trimmedFile)
    } catch {
        return proxiedUrl
    }
}

const insertAssetToCanvas = async (asset: any, opts?: { pos?: { x: number; y: number } }) => {
    if (!canvas.value || !fabric) return;
    if (!asset?.url) return;

    try {
        // Se houver um card de produto selecionado dentro da zona de produtos,
        // aplicar a imagem diretamente no card (em vez de inserir solta no canvas).
        // Aqui o comportamento deve ser não-destrutivo: uploads/assets vindos do sidebar
        // podem representar OUTRO produto do combo, então não substituímos a imagem atual
        // automaticamente. Quem quiser trocar usa os botões explícitos de "Substituir imagem".
        const shouldAutoPlaceInSelectedCard = !opts?.pos;
        if (shouldAutoPlaceInSelectedCard) {
            const active = canvas.value.getActiveObject?.();
            const ctx = resolveSelectedProductCardContext(active);
            const card = ctx?.card;
            const cardInZone = !!(card && hasParentZoneBinding(card));

            if (card && cardInZone) {
                const added = await addImageToProductCardByUrl(card, asset.url, {
                    save: true,
                    setActive: true
                });
                if (added) return;
            }
        }

        const center = opts?.pos ?? getCenterOfView();
        const proxiedUrl = await resolveTrimmedInsertUrl(
            asset.url,
            asset?.lastModified || asset?.updatedAt || null
        );
        const img: any = await fabric.Image.fromURL(proxiedUrl, { crossOrigin: 'anonymous' });
        await autoTrimFabricImageAsync(img, { preserveVisualPosition: true });
        markProductImageTrimmed(img);

        const pageW = activePage.value?.width || 1080;
        const pageH = activePage.value?.height || 1920;
        const maxW = pageW * 0.55;
        const maxH = pageH * 0.55;
        const iw = img.width || 1;
        const ih = img.height || 1;
        const scale = Math.min(maxW / iw, maxH / ih, 1);

        img.set({
            left: center.x,
            top: center.y,
            originX: 'center',
            originY: 'center',
            scaleX: scale,
            scaleY: scale,
            name: (asset.name || 'Imagem').toString(),
            selectable: true,
            evented: true
        });
        (img as any)._customId = makeId();

        canvas.value.add(img);
        // Keep the new asset visible above the page/frame.
        const c: any = canvas.value as any;
        if (typeof c.bringObjectToFront === 'function') c.bringObjectToFront(img);
        else if (typeof c.bringToFront === 'function') c.bringToFront(img);

        canvas.value.setActiveObject(img);
        safeRequestRenderAll();
        saveCurrentState();
    } catch (e) {
        console.warn('[assets] Failed to insert asset to canvas', e);
    }
};

// ─── Insert Element from ElementsPanel ────────────────────────────────────
const insertElementToCanvas = (element: { type: string; data: any }) => {
    if (!canvas.value || !fabric) return;
    const { type, data } = element;

    if (type === 'shape') {
        // Reutiliza addShape existente, passando options customizadas
        addShape(data.shape, data.options || {});
    } else if (type === 'path') {
        // Cria fabric.Path a partir de pathData SVG
        try {
            const center = getCenterOfView();
            const pathObj: any = new fabric.Path(data.path, {
                fill: data.fill ?? '#cccccc',
                stroke: data.stroke ?? '#cccccc',
                strokeWidth: data.strokeWidth ?? 0,
                strokeUniform: true,
                strokeLineCap: data.strokeLineCap || 'butt',
                strokeLineJoin: data.strokeLineJoin || 'miter',
                fillRule: data.fillRule || 'nonzero',
                objectCaching: false,
                noScaleCache: true,
                statefullCache: false,
            });
            // Escalar para ~100px de largura mantendo proporção
            const bw = pathObj.width || 100;
            const bh = pathObj.height || 100;
            const targetSize = 120;
            const scale = targetSize / Math.max(bw, bh);
            pathObj.set({
                scaleX: scale,
                scaleY: scale,
                left: center.x,
                top: center.y,
                originX: 'center',
                originY: 'center',
            });
            pathObj._customId = makeId();
            canvas.value.add(pathObj);
            canvas.value.setActiveObject(pathObj);
            safeRequestRenderAll();
            saveCurrentState();
        } catch (err) {
            console.warn('[elements] Failed to create path element', err);
        }
    } else if (type === 'frame') {
        // Cria frame com dimensões customizadas
        addFrame({
            width: Number(data?.width),
            height: Number(data?.height)
        });
    } else if (type === 'grid') {
        // Cria grade de frames estilo Canva (cada célula é um Frame com clipPath)
        const cols = data.columns || 2;
        const rows = data.rows || 2;
        const gap = data.gap ?? 8;
        addGridFrames(cols, rows, gap);
    } else if (type === 'store-field') {
        void addStoreDynamicField(data || {});
    }
};

const addStoreDynamicField = async (data: Record<string, any>) => {
    if (!canvas.value || !fabric) return;
    const field = String(data?.field || '').trim();
    const kind = String(data?.kind || 'text');
    const sample = String(data?.sample || data?.label || 'Texto da loja');
    const center = getCenterOfView();
    const profile = getQuickBusinessProfilePayload(quickBusinessProfile.value);
    const liveValue = field && project.isTemplate !== true ? getQuickBusinessProfileValue(profile, field) : '';
    const textValue = String(liveValue || sample).trim() || sample;

    if (kind === 'logo') {
        const slot = createQuickLogoSlot({
            isQuickGenerated: true,
            quickFieldEnabled: true
        });
        if (!slot) return;
        slot.set({
            left: center.x,
            top: center.y,
            originX: 'center',
            originY: 'center'
        });
        styleEmptyLogoPlaceholder(slot);
        canvas.value.add(slot);
        syncObjectFrameClip(slot);
        await syncQuickLogoBinding(profile);
        // A ligação pode trocar o Rect pela Image, mas preserva o _customId.
        // Reencontre o objeto vivo antes de selecioná-lo.
        const persistedLogo = canvas.value.getObjects().find((object: any) => (
            object === slot ||
            String(object?._customId || '').trim() === String(slot?._customId || '').trim()
        ));
        if (persistedLogo) canvas.value.setActiveObject(persistedLogo);
        refreshCanvasObjects();
        safeRequestRenderAll();
        // A inserção da logo é estrutural: persiste localmente e confirma o
        // flush remoto antes de encerrar a operação, em vez de depender do
        // debounce comum de object:added.
        await Promise.resolve(saveCurrentState({
            allowEmptyOverwrite: true,
            reason: 'store-dynamic-field:logo',
            source: 'user',
            skipCoalesce: true,
            skipIfUnchanged: false
        }));
        await flushPersistenceNow('store-dynamic-field:logo', { force: true });
        return;
    }

    const object = new fabric.Textbox(textValue, {
        left: center.x,
        top: center.y,
        width: kind === 'validity' ? 420 : 360,
        originX: 'center',
        originY: 'center',
        fontFamily: DEFAULT_EDITOR_FONT_FAMILY,
        fontSize: Number(data?.fontSize || 18),
        fontWeight: data?.fontWeight || 600,
        fill: '#172033',
        textAlign: 'center',
        editable: true,
        selectable: true,
        evented: true,
        hasControls: true,
        hasBorders: true,
        lockScalingX: false,
        lockScalingY: false,
        objectCaching: false,
        ...getDynamicBusinessTextOptions(field || (kind === 'validity' ? 'validity' : '')),
        businessProfileField: kind === 'validity' ? undefined : field || undefined,
        quickDataField: kind === 'validity' ? 'validity' : undefined,
        quickFieldEnabled: true,
        layerName: String(data?.label || 'Dado da loja')
    });
    object._customId = makeId();
    configureDynamicBusinessTextObject(object, fabric);
    fitDynamicBusinessTextObject(object);
    canvas.value.add(object);
    syncObjectFrameClip(object);
    canvas.value.setActiveObject(object);
    refreshCanvasObjects();
    safeRequestRenderAll();
    saveCurrentState();
};

