const addImageToProductCardByUrl = async (
    card: any,
    newUrl: string,
    opts: { save?: boolean; setActive?: boolean } = {}
) => {
    if (!canvas.value || !fabric || !card || !newUrl) return false;
    if (!isProductCardContainer(card) && !isLikelyProductCard(card)) return false;
    const shouldSave = opts.save !== false;
    const shouldSetActive = opts.setActive !== false;

    try {
        const proxiedUrl = await resolveTrimmedInsertUrl(newUrl);
        const newImg: any = await fabric.Image.fromURL(proxiedUrl, { crossOrigin: 'anonymous' });
        if (!newImg) return false;

        await autoTrimFabricImageAsync(newImg, { preserveVisualPosition: true });
        markProductImageTrimmed(newImg);

        const existingProductImage = getPreferredProductImageFromGroup(card);
        const cardW = Number(card._cardWidth || card.width || 100);
        const cardH = Number(card._cardHeight || card.height || 100);
        const maxW = Math.min(cardW * 0.86, existingProductImage
            ? Math.abs(existingProductImage.width * existingProductImage.scaleX) : cardW * 0.86);
        const maxH = Math.min(cardH * 0.64, existingProductImage
            ? Math.abs(existingProductImage.height * existingProductImage.scaleY) : cardH * 0.64);
        const scale = Math.min(maxW / Math.max(1, newImg.width), maxH / Math.max(1, newImg.height));
        const halfW = newImg.width * scale / 2;
        const halfH = newImg.height * scale / 2;
        const targetLeft = Math.max(-cardW / 2 + halfW, Math.min(cardW / 2 - halfW, Number(existingProductImage?.left || 0)));
        const targetTop = Math.max(-cardH / 2 + halfH, Math.min(cardH / 2 - halfH, Number(existingProductImage?.top || 0)));
        const imageName = existingProductImage ? `extra_image_${Date.now()}` : 'smart_image';

        newImg.set({
            left: targetLeft,
            top: targetTop,
            scaleX: scale,
            scaleY: scale,
            originX: 'center',
            originY: 'center',
            selectable: true,
            evented: true,
            hasControls: true,
            hasBorders: true,
            name: imageName,
            _customId: makeCanvasObjectId()
        });
        (newImg as any).src = proxiedUrl;
        if (existingProductImage) {
            (newImg as any).__manualTransform = true;
            (newImg as any).__manualTransformCardW = Number((card as any)?._cardWidth ?? card?.width ?? 0) || undefined;
            (newImg as any).__manualTransformCardH = Number((card as any)?._cardHeight ?? card?.height ?? 0) || undefined;
        }

        // Group.add recebe coordenadas de cena. Converta também a escala do
        // card, não só a posição, antes de inserir a imagem em seu plano local.
        fabric.util.applyTransformToObject(newImg, fabric.util.multiplyTransformMatrices(
            card.calcTransformMatrix(), newImg.calcOwnMatrix()
        ));
        safeAddWithUpdate(card, newImg);
        card.set({ subTargetCheck: true, interactive: true });
        card.setCoords?.();
        card.dirty = true;

        if (!existingProductImage) {
            (card as any).imageUrl = newUrl;
            if ((card as any)._productData && typeof (card as any)._productData === 'object') {
                (card as any)._productData = {
                    ...(card as any)._productData,
                    imageUrl: newUrl,
                    image: newUrl
                };
            }
        }

        if (shouldSetActive) {
            canvas.value.setActiveObject(newImg);
        }
        safeRequestRenderAll();
        refreshCanvasObjects();
        if (shouldSave) {
            saveCurrentState();
        }
        return true;
    } catch (e) {
        console.warn('[product-image] Falha ao adicionar imagem ao card:', e);
        return false;
    }
};

const replaceImageByCustomId = async (
    targetId: string,
    newUrl: string,
    opts: { save?: boolean; setActive?: boolean; fit?: 'contain'; scope?: 'single' | 'all' } = {}
): Promise<boolean> => {
    if (!canvas.value || !fabric || !targetId || !newUrl) return false;
    const shouldSave = opts.save !== false;
    const shouldSetActive = opts.setActive !== false;

    const found = findObjectByCustomId(targetId);
    if (!found) return false;

    const target = found.obj;
    if (String(target?.type || '').toLowerCase() !== 'image') return false;

    try {
        if (found.parent && (isProductCardContainer(found.parent) || isLikelyProductCard(found.parent))) {
            const card = found.parent;
            // Carrega uma vez. O crop referencia a mesma imagem persistente,
            // evitando salvar dimensões de um arquivo aparado com a URL antiga.
            const source = toWasabiProxyUrl(newUrl) || newUrl;
            const replacement = await fabric.Image.fromURL(source, { crossOrigin: 'anonymous' });
            await autoTrimFabricImageAsync(replacement, { preserveVisualPosition: true });
            const images = replaceProductImageCopies(card, target, replacement, source, opts.scope);
            if (!images.length) return false;
            images.forEach(markProductImageTrimmed);
            const primary = collectDirectProductCardImages(card)[0];
            const primarySource = String(primary?.__originalSrc || primary?.src || source);
            card.imageUrl = primarySource;
            card._productData = { ...card._productData, imageUrl: primarySource, image: primarySource,
                images: collectDirectProductCardImages(card).map((image: any) => ({ x: 0, y: 0, scale: 1, ...(card._productData?.images || []).find((item: any) => item.id === image._customId), id: image._customId, src: image.__originalSrc || image.src || image.getSrc?.() })) };

            if (shouldSetActive) canvas.value.setActiveObject(card);
            refreshCanvasObjects({ immediate: true });
            updateSelection();
            safeRequestRenderAll();
            if (shouldSave) await saveCurrentState({ reason: 'replace-product-image-copies', skipIfUnchanged: false });
            return true;
        }
        const oldDisplayW = Math.abs((target.width || 1) * (target.scaleX || 1));
        const oldDisplayH = Math.abs((target.height || 1) * (target.scaleY || 1));
        const proxiedNewUrl = await resolveTrimmedInsertUrl(newUrl);
        const newImg: any = await fabric.Image.fromURL(proxiedNewUrl, { crossOrigin: 'anonymous' });
        if (!newImg) return false;

        await autoTrimFabricImageAsync(newImg, { preserveVisualPosition: true });
        markProductImageTrimmed(newImg);

        const newW = newImg.width || 1;
        const newH = newImg.height || 1;
        const newScaleX = oldDisplayW / newW;
        const newScaleY = oldDisplayH / newH;

        newImg.set({
            left: target.left,
            top: target.top,
            scaleX: opts.fit ? Math.min(newScaleX, newScaleY) : newScaleX,
            scaleY: opts.fit ? Math.min(newScaleX, newScaleY) : newScaleY,
            angle: target.angle || 0,
            originX: target.originX || 'center',
            originY: target.originY || 'center',
            name: (target as any).name,
            _customId: (target as any)._customId,
            opacity: (target as any).opacity,
            flipX: (target as any).flipX,
            flipY: (target as any).flipY,
            clipPath: (target as any).clipPath,
            filters: (target as any).filters
        });
        if (opts.fit) {
            for (const prop of CANVAS_CUSTOM_PROPS) if (target[prop] !== undefined) newImg[prop] = target[prop]
            newImg.setPositionByOrigin(target.getRelativeCenterPoint(), 'center', 'center')
        }
        (newImg as any).src = newUrl;

        if (found.parent) {
            const parent = found.parent;
            const list = typeof parent.getObjects === 'function' ? parent.getObjects() : [];
            const idx = list.indexOf(target);
            parent.remove(target);
            // FIX: Dispose old image to free memory
            try { target.dispose?.(); } catch {}
            if (typeof (parent as any).insertAt === 'function' && idx >= 0) (parent as any).insertAt(idx, newImg);
            else parent.add(newImg);
            safeAddWithUpdate(parent);
            parent.setCoords?.();

            if (isProductCardContainer(parent) || isLikelyProductCard(parent)) {
                (parent as any).imageUrl = newUrl;
                if ((parent as any)._productData && typeof (parent as any)._productData === 'object') {
                    (parent as any)._productData = {
                        ...(parent as any)._productData,
                        imageUrl: newUrl,
                        image: newUrl
                    };
                }
            }

            if (shouldSetActive) {
                canvas.value.setActiveObject(parent);
            }
        } else {
            const oldIndex = canvas.value.getObjects().indexOf(target);
            canvas.value.remove(target);
            // FIX: Dispose old image to free memory
            try { target.dispose?.(); } catch {}
            if (oldIndex >= 0 && typeof (canvas.value as any).insertAt === 'function') {
                (canvas.value as any).insertAt(oldIndex, newImg);
            } else {
                canvas.value.add(newImg);
            }
            if (shouldSetActive) {
                canvas.value.setActiveObject(newImg);
            }
        }

        safeRequestRenderAll();
        if (shouldSave) {
            saveCurrentState();
        }
        return true;
    } catch (e) {
        console.warn('[ai-studio] Falha ao substituir imagem:', e);
        return false;
    }
};

