const resolveOrCreateZoneForFrame = (frame: any): any | null => {
    if (!canvas.value || !fabric || !frame) return null
    const frameId = String((frame as any)?._customId || '').trim()
    if (!frameId) return null

    const zonesForFrame = canvas.value
        .getObjects()
        .filter((obj: any) => isLikelyProductZone(obj) && String((obj as any)?.parentFrameId || '').trim() === frameId)

    if (zonesForFrame.length === 1) {
        ensureZoneSanity(zonesForFrame[0])
        return zonesForFrame[0]
    }

    if (zonesForFrame.length > 1) {
        const pickLargest = zonesForFrame.reduce((best: any, candidate: any) => {
            const b = getZoneMetrics(best) || best?.getBoundingRect?.(true)
            const c = getZoneMetrics(candidate) || candidate?.getBoundingRect?.(true)
            const bestArea = Number(b?.width || 0) * Number(b?.height || 0)
            const candidateArea = Number(c?.width || 0) * Number(c?.height || 0)
            return candidateArea > bestArea ? candidate : best
        }, zonesForFrame[0])
        ensureZoneSanity(pickLargest)
        return pickLargest
    }

    const frameBounds = getFrameBounds(frame)
    if (!frameBounds) return null

    const innerPadding = Math.max(12, Math.min(64, Math.round(Math.min(frameBounds.width, frameBounds.height) * 0.04)))
    const zoneWidth = Math.max(80, frameBounds.width - innerPadding * 2)
    const zoneHeight = Math.max(80, frameBounds.height - innerPadding * 2)
    const zoneCenterX = frameBounds.left + (frameBounds.width / 2)
    const zoneCenterY = frameBounds.top + (frameBounds.height / 2)

    const zoneRect = new fabric.Rect({
        width: zoneWidth,
        height: zoneHeight,
        fill: 'rgba(0,0,0,0)',
        stroke: '#404040',
        strokeWidth: 2,
        strokeDashArray: [10, 10],
        strokeUniform: true,
        rx: 16,
        ry: 16,
        originX: 'center',
        originY: 'center',
        name: 'zoneRect',
        selectable: false,
        evented: false
    })

    const zone = new fabric.Group([zoneRect], {
        left: zoneCenterX,
        top: zoneCenterY,
        originX: 'center',
        originY: 'center',
        isGridZone: true,
        isProductZone: true,
        name: 'productZoneContainer',
        columns: 0,
        rows: 0,
        gapHorizontal: 20,
        gapVertical: 20,
        cardAspectRatio: 'fill',
        lastRowBehavior: 'fill',
        layoutDirection: 'horizontal',
        verticalAlign: 'stretch',
        subTargetCheck: false,
        hoverCursor: 'move',
        moveCursor: 'move',
        lockMovementX: false,
        lockMovementY: false,
        lockScalingFlip: true,
        selectable: true,
        evented: true,
        hasControls: true,
        hasBorders: true,
        transparentCorners: false,
        cornerColor: '#6d28d9',
        cornerStrokeColor: '#1e1b4b',
        cornerStyle: 'circle',
        cornerSize: 13,
        padding: 0,
        excludeFromExport: false,
        objectCaching: false,
        statefullCache: false
    })

    ;(zone as any)._customId = makeCanvasObjectId()
    ;(zone as any).zoneName = getNextProductZoneName(zone)
    ;(zone as any).role = 'grid'
    ;(zone as any).contentSource = 'multi-frame'
    ;(zone as any).contentStatus = 'empty'
    ;(zone as any).overflowPolicy = 'warn'
    ;(zone as any)._zonePadding = 20
    ;(zone as any)._zoneWidth = zoneWidth
    ;(zone as any)._zoneHeight = zoneHeight
    ;(zone as any).parentFrameId = frameId
    // New zones should start from defaults (not from the previous page's last-selected styles).
    ;(zone as any)._zoneGlobalStyles = normalizeGlobalStyles(DEFAULT_GLOBAL_STYLES)

    canvas.value.add(zone)
    ensureZoneSanity(zone)
    getResolvedZoneFrameId(zone)
    zone.setCoords?.()
    ensureFramesBelowContents()
    return zone
}

const importProductsToMultipleFrames = async (products: any[], opts?: ProductImportOptions) => {
    if (!canvas.value || !Array.isArray(products) || products.length === 0) return

    const selectedFrameIds = Array.from(
        new Set(
            (Array.isArray(opts?.selectedFrameIds) ? opts?.selectedFrameIds : [])
                .map((id: any) => String(id || '').trim())
                .filter(Boolean)
        )
    )
    const frameById = new Map<string, any>()
    getAllFrames().forEach((frame: any) => {
        const id = String(frame?._customId || frame?.id || '').trim()
        if (id) frameById.set(id, frame)
    })

    const validFrameIds = selectedFrameIds.filter(id => frameById.has(id))
    if (validFrameIds.length === 0) {
        console.warn('[importProductsToMultipleFrames] No valid selected frames to import.')
        return
    }

    const productById = new Map<string, any>()
    const orderedProductIds: string[] = []
    products.forEach((product: any, index: number) => {
        const id = getProductImportIdentityKey(product, index)
        if (!productById.has(id)) {
            productById.set(id, product)
            orderedProductIds.push(id)
        }
    })

    const validFrameIdSet = new Set(validFrameIds)
    const pairs: Array<{ product: any; productId: string; frameId: string }> = []
    const usedFrameIds = new Set<string>()
    const usedProductIds = new Set<string>()

    const rawAssignments = Array.isArray(opts?.frameAssignments) ? opts.frameAssignments : []
    rawAssignments.forEach((assignment: any) => {
        const productId = String(assignment?.productId || '').trim()
        const frameId = String(assignment?.frameId || '').trim()
        if (!productId || !frameId) return
        if (!validFrameIdSet.has(frameId)) return
        if (!productById.has(productId)) return
        if (usedFrameIds.has(frameId)) return
        if (usedProductIds.has(productId)) return

        usedFrameIds.add(frameId)
        usedProductIds.add(productId)
        pairs.push({
            product: productById.get(productId),
            productId,
            frameId
        })
    })

    if (pairs.length === 0) {
        const fallbackLimit = Math.min(orderedProductIds.length, validFrameIds.length)
        for (let i = 0; i < fallbackLimit; i += 1) {
            const productId = orderedProductIds[i]
            const frameId = validFrameIds[i]
            if (!productId || !frameId) continue
            pairs.push({
                product: productById.get(productId),
                productId,
                frameId
            })
        }
    }

    const effectiveLimit = Math.min(orderedProductIds.length, validFrameIds.length)
    const effectivePairs = pairs.slice(0, effectiveLimit)
    if (effectivePairs.length === 0) {
        console.warn('[importProductsToMultipleFrames] No valid product/frame pairs to import.')
        return
    }

    const labelTemplateId = typeof opts?.labelTemplateId === 'string' ? opts.labelTemplateId : undefined
    let applied = 0

    for (const pair of effectivePairs) {
        const frame = frameById.get(pair.frameId)
        if (!frame) continue
        const zone = resolveOrCreateZoneForFrame(frame)
        if (!zone) {
            console.warn('[importProductsToMultipleFrames] Could not resolve zone for frame:', pair.frameId)
            continue
        }

        await simulateSmartGrid(
            [pair.product],
            { margin: 10, gap: 15, orphanBehavior: 'fill' },
            zone,
            {
                mode: 'replace',
                labelTemplateId,
                sourceMode: 'multi-frame',
                autoLayout: opts?.autoLayout,
                persist: false
            }
        )
        ;(zone as any).contentSource = 'multi-frame'
        syncZoneDerivedMetadata(zone)
        applied += 1
    }

    if (applied > 0) {
        refreshCanvasObjects()
        safeRequestRenderAll()
        refreshSelectedRef()
        await saveCurrentState({
            allowEmptyOverwrite: true,
            reason: 'simulate-smart-grid-multi-frame',
            source: 'user',
            skipCoalesce: true,
            skipIfUnchanged: false
        })
        await flushPersistenceNow('simulate-smart-grid-multi-frame', { force: true })
    }
}

// buildProductSlicesForZones extraido para utils/product-zone-helpers.ts.
// Wrapper local injeta getZoneChildren (que requer canvas).
const buildProductSlicesForZones = (products: any[], zones: any[], mode: 'replace' | 'append'): any[][] =>
    buildProductSlicesForZonesHelper(products, zones, mode, (zone: any) => getZoneChildren(zone).length)

const clearProductZoneCards = (zone: any) => {
    if (!canvas.value || !zone || !isLikelyProductZone(zone)) return
    let cards: any[] = []
    try {
        cards = getZoneChildren(zone)
    } catch {
        cards = []
    }
    cards.forEach((card: any) => {
        try {
            canvas.value?.remove(card)
        } catch {
            // ignore individual stale card removal
        }
    })
    syncZoneDerivedMetadata(zone)
}

const importProductsToMultipleZones = async (products: any[], zones: any[], opts?: ProductImportOptions) => {
    if (!canvas.value || !Array.isArray(products) || products.length === 0) return

    const validZones = sortProductZonesByVisualOrder(
        zones.filter((zone: any) => zone && isLikelyProductZone(zone))
    )
    if (validZones.length === 0) return
    if (validZones.length === 1) {
        const labelTemplateId = typeof opts?.labelTemplateId === 'string' ? opts.labelTemplateId : undefined
        const mode = (opts?.mode === 'append' || opts?.mode === 'replace') ? opts.mode : productReviewInitialImportMode.value
        const sourceMode = opts?.sourceMode === 'paste-list' || opts?.sourceMode === 'file-import'
            ? opts.sourceMode
            : 'manual'
        await simulateSmartGrid(products, { margin: 10, gap: 15, orphanBehavior: 'fill' }, validZones[0], {
            mode,
            labelTemplateId,
            sourceMode,
            autoLayout: opts?.autoLayout
        })
        return
    }

    const mode: 'replace' | 'append' = (opts?.mode === 'append' || opts?.mode === 'replace')
        ? opts.mode
        : productReviewInitialImportMode.value
    const labelTemplateId = typeof opts?.labelTemplateId === 'string' ? opts.labelTemplateId : undefined
    const nextSource = opts?.sourceMode === 'paste-list' || opts?.sourceMode === 'file-import'
        ? opts.sourceMode
        : 'manual'
    const zoneById = new Map<string, any>()
    validZones.forEach((zone: any) => {
        const id = String((zone as any)?._customId || (zone as any)?.id || '').trim()
        if (id) zoneById.set(id, zone)
    })
    const productById = new Map<string, any>()
    products.forEach((product: any, index: number) => {
        const id = getProductImportIdentityKey(product, index)
        if (id && !productById.has(id)) productById.set(id, product)
    })
    const rawZoneAssignments = Array.isArray(opts?.zoneAssignments) ? opts.zoneAssignments : []
    const hasManualZoneAssignments = rawZoneAssignments.some((assignment: any) => {
        const productId = String(assignment?.productId || '').trim()
        const zoneId = String(assignment?.zoneId || '').trim()
        return productId && zoneId && productById.has(productId) && zoneById.has(zoneId)
    })
    const slices = hasManualZoneAssignments
        ? validZones.map((zone: any) => {
            const zoneId = String((zone as any)?._customId || (zone as any)?.id || '').trim()
            return rawZoneAssignments
                .filter((assignment: any) => String(assignment?.zoneId || '').trim() === zoneId)
                .map((assignment: any) => productById.get(String(assignment?.productId || '').trim()))
                .filter(Boolean)
        })
        : buildProductSlicesForZones(products, validZones, mode)
    let applied = 0

    for (let index = 0; index < validZones.length; index += 1) {
        const zone = validZones[index]
        const slice = slices[index] || []
        if (slice.length === 0) {
            if (mode === 'replace' && !hasManualZoneAssignments) {
                clearProductZoneCards(zone)
                ;(zone as any).contentSource = nextSource
                applied += 1
            }
            continue
        }

        await simulateSmartGrid(slice, { margin: 10, gap: 15, orphanBehavior: 'fill' }, zone, {
            mode,
            labelTemplateId,
            sourceMode: nextSource,
            autoLayout: opts?.autoLayout,
            persist: false
        })
        ;(zone as any).contentSource = nextSource
        syncZoneDerivedMetadata(zone)
        applied += 1
    }

    if (applied > 0) {
        refreshCanvasObjects()
        safeRequestRenderAll()
        refreshSelectedRef()
        await saveCurrentState({
            allowEmptyOverwrite: true,
            reason: 'simulate-smart-grid-multi-zone',
            source: 'user',
            skipCoalesce: true,
            skipIfUnchanged: false
        })
        await flushPersistenceNow('simulate-smart-grid-multi-zone', { force: true })
    }
}

// Reuse the ordinary renderer; keep intermediate cards out of autosave/history.
const importOneProductPerPage = async (products: any[], opts?: ProductImportOptions) => {
    const sourcePage = activePage.value
    const zone = (opts?.targetZoneId ? findProductZoneById(opts.targetZoneId) : null) || resolveImportTargetZone()
    if (!sourcePage || !zone || !canvas.value) throw new Error('Selecione uma zona de produtos na página que será usada como base.')
    await saveCurrentState({ reason: 'before-one-product-per-page', source: 'system', markUnsaved: true, skipCoalesce: true })
    const original = sourcePage.canvasData ? JSON.parse(JSON.stringify(sourcePage.canvasData)) : null
    if (!original || !Array.isArray(original.objects)) throw new Error('Não foi possível salvar a página base. Tente novamente antes de criar os encartes.')
    const snapshots: any[] = []
    const getCards = () => collectObjectsDeep(canvas.value).filter((obj: any) => {
        if (isLikelyProductZone(obj) || !(isProductCardContainer(obj) || isLikelyProductCard(obj))) return false
        for (let parent = obj.group; parent; parent = parent.group) {
            if (!isLikelyProductZone(parent) && (isProductCardContainer(parent) || isLikelyProductCard(parent))) return false
        }
        return true
    })
    const zoneId = getProductZoneId(zone)
    isHistoryProcessing.value = true
    try {
        // Other product zones must not carry products into each generated page.
        for (const card of getCards()) {
            if (card.group?.remove) card.group.remove(card)
            else canvas.value.remove(card)
        }
        for (const product of products) {
            await simulateSmartGrid([product], { margin: 10, gap: 15, orphanBehavior: 'fill' }, findProductZoneById(zoneId) || zone, {
                mode: 'replace', labelTemplateId: opts?.labelTemplateId, autoLayout: true, persist: false
            })
            syncAllZoneStateSnapshots(canvas.value, 'one-product-per-page')
            restoreViewportCulledObjects(canvas.value.getObjects())
            const json = canvas.value.toObject([...CANVAS_CUSTOM_PROPS])
            const cards = getCards()
            if (cards.length !== 1) {
                console.error('[one-product-per-page]', cards.length, canvas.value.getObjects().map((obj: any) => ({ name: obj.name, type: obj.type, card: obj.isProductCard, smart: obj.isSmartObject, zone: obj.isProductZone })))
                throw new Error('Não foi possível montar uma página com apenas um produto.')
            }
            snapshots.push(JSON.parse(JSON.stringify(json)))
        }
    } finally {
        try { await loadFromJsonSafe(original) } finally { isHistoryProcessing.value = false }
        refreshCanvasObjects({ immediate: true })
        safeRequestRenderAll()
    }
    // A página escolhida recebe o primeiro produto; só os demais precisam de cópias.
    isHistoryProcessing.value = true
    try { await loadFromJsonSafe(snapshots[0]) } finally { isHistoryProcessing.value = false }
    refreshCanvasObjects({ immediate: true })
    safeRequestRenderAll()
    await saveCurrentState({ reason: 'one-product-per-page-first', source: 'user', skipCoalesce: true, skipIfUnchanged: false })
    const sourceIndex = project.pages.findIndex((page: any) => page.id === sourcePage.id)
    for (let index = 1; index < snapshots.length; index++) {
        await createPageFromTemplateSource({ ...sourcePage, canvasData: snapshots[index], canvasDataPath: undefined, thumbnailUrl: undefined }, {
            activate: false,
            insertAfterIndex: sourceIndex + index - 1,
            name: String(products[index]?.name || products[index]?.productName || `Produto ${index + 1}`)
        })
    }
    await flushPersistenceNow('one-product-per-page', { force: true })
    notifyEditorInfo(`${snapshots.length} produtos distribuídos: o primeiro na página atual e os demais nas cópias.`)
}

const quickCompletedProductReviews = ref(0)

// Confirm import from review modal
const confirmProductImport = async (products: any[], opts?: ProductImportOptions) => {
    if (isConfirmingProductImport.value) {
        console.warn('[confirmProductImport] Import already running, ignoring duplicate trigger.')
        return
    }
    console.log('[DEBUG confirmProductImport] targetGridZone:', targetGridZone.value?._customId, 'targetGridZones count:', targetGridZones.value?.length);

    isConfirmingProductImport.value = true
    showProductReviewModal.value = false

    try {
        if (!products || products.length === 0) {
            console.warn('[confirmProductImport] No products to import!')
            return
        }

        if (opts?.oneProductPerPage) {
            await importOneProductPerPage(products, opts)
            if (isQuickMode.value) quickCompletedProductReviews.value += 1
            return
        }
        const targetMode: ImportTargetMode = opts?.targetMode === 'multi-frame' ? 'multi-frame' : 'zone'
        if (targetMode === 'multi-frame') {
            await importProductsToMultipleFrames(products, opts)
        } else {
            // Recover the real zone object from current selection. Do not fall
            // back to zones[0]; with multiple zones that silently imports into
            // the first created zone instead of the user-selected one.
            const explicitZoneId = String(opts?.targetZoneId || '').trim()
            const zone = (explicitZoneId ? findProductZoneById(explicitZoneId) : null) || resolveImportTargetZone()
            console.log('[DEBUG confirmProductImport] final zone:', zone?._customId);
            if (!zone) {
                console.warn('[confirmProductImport] Could not resolve target product zone. Import aborted to avoid detached cards.')
                notifyEditorError('Selecione uma Zona de Produtos antes de importar.')
                return
            }
            targetGridZone.value = zone
            targetGridZones.value = resolveRelatedImportZones(zone)
            setActiveProductZone(zone)

            const targetZones = [zone]
            if (targetZones.length > 1) {
                await importProductsToMultipleZones(products, targetZones, opts)
            } else {
                // Add to canvas using the products received from the modal (with edits applied)
                const mode = (opts?.mode === 'append' || opts?.mode === 'replace') ? opts.mode : 'replace'
                const labelTemplateId = typeof opts?.labelTemplateId === 'string' ? opts.labelTemplateId : undefined
                const nextSource = opts?.sourceMode === 'paste-list' || opts?.sourceMode === 'file-import'
                    ? opts.sourceMode
                    : 'manual'
                await simulateSmartGrid(products, { margin: 10, gap: 15, orphanBehavior: 'fill' }, zone, {
                    mode,
                    labelTemplateId,
                    sourceMode: nextSource,
                    autoLayout: opts?.autoLayout
                })
                ;(zone as any).contentSource = nextSource
                syncZoneDerivedMetadata(zone)
            }
        }
        if (isQuickMode.value) quickCompletedProductReviews.value += 1
    } catch (error: any) {
        notifyEditorError(error?.message || 'Não foi possível importar os produtos.')
    } finally {
        // Clear review state and zone reference
        reviewProducts.value = []
        targetGridZone.value = null
        targetGridZones.value = []
        productImportExistingCount.value = 0
        productReviewInitialImportMode.value = 'replace'

        // Update layer panel
        if (canvas.value) {
            refreshCanvasObjects()
        }

        // Uma falha transitória no proxy/storage durante a criação do card
        // deixa o retângulo de reserva no lugar da imagem. Reaproveitamos o
        // mesmo recuperador da hidratação também após uma importação, para
        // tentar novamente sem exigir reload manual do editor.
        scheduleMissingProductImageRecovery(180, 10, getActiveProjectPageId())
        isConfirmingProductImport.value = false
    }
}

const handleProductReviewModalVisibility = (value: boolean) => {
    showProductReviewModal.value = value
    if (value || isConfirmingProductImport.value) return

    quickModeInitialProductText.value = ''
    quickModeInitialProductFile.value = null
    quickModeAutoParseProductText.value = false
    reviewProducts.value = []
    targetGridZone.value = null
    targetGridZones.value = []
    productImportExistingCount.value = 0
    productReviewInitialImportMode.value = 'replace'
}

