        window.removeEventListener('business-profile:updated', handleBusinessProfileUpdated)
    }
})

// === ZONE LOGIC ===

// normalizeGlobalStyles extraido para utils/globalStylesNormalize.ts.
// Wrapper local injeta DEFAULT_GLOBAL_STYLES.
const normalizeGlobalStyles = (styles?: Partial<GlobalStyles> | null): GlobalStyles =>
    normalizeGlobalStylesHelper(styles, DEFAULT_GLOBAL_STYLES)

function getZoneGlobalStyles(zone?: any): GlobalStyles {
    if (zone && typeof (zone as any)._zoneGlobalStyles === 'object' && (zone as any)._zoneGlobalStyles !== null) {
        return normalizeGlobalStyles((zone as any)._zoneGlobalStyles as Partial<GlobalStyles>);
    }
    return normalizeGlobalStyles(productZoneState.globalStyles.value);
}

// === Overrides explicitos de estilo de etiqueta (modelo "ultima edicao vence") ===
// Quando o usuario muda uma prop de estilo pelo painel global da zona, marcamos
// um override explicito na zona (`_zoneStyleOverrides`). Esse override e' SEMPRE
// reaplicado por cima do template em (re)aplicacao/refresh — evitando que a
// edicao reverta sozinha. Editar a mesma prop no Mini Editor limpa o override
// (o template volta a ser a fonte de verdade). Persistido via CANVAS_CUSTOM_PROPS.
const getZoneStyleOverrides = (zone: any): Record<string, true> => {
    const o = zone && (zone as any)._zoneStyleOverrides;
    return o && typeof o === 'object' ? o as Record<string, true> : {};
};
const zoneHasStyleOverride = (zone: any, prop: any): boolean =>
    !!getZoneStyleOverrides(zone)[String(prop || '').trim()];
const markZoneStyleOverride = (zone: any, prop: any) => {
    if (!zone || !isLabelStyleOverridableProp(prop)) return;
    const current = (zone as any)._zoneStyleOverrides;
    const map: Record<string, true> = current && typeof current === 'object' ? current : {};
    map[String(prop).trim()] = true;
    (zone as any)._zoneStyleOverrides = map;
};
const clearZoneStyleOverrides = (zone: any, props: Iterable<string>) => {
    const map = (zone as any)?._zoneStyleOverrides;
    if (!map || typeof map !== 'object') return;
    for (const p of props) delete map[String(p || '').trim()];
};

// === Override de estilo POR CARD ("editar so esta etiqueta") ===
// Precedencia: template < estilos da zona (_zoneGlobalStyles) < override do card.
// `_cardStyleOverrides` e' um mapa prop->valor no proprio card (presenca = override).
// Vence a zona, persiste (CANVAS_CUSTOM_PROPS) e e' respeitado em reaplicar/resize/swap.
const getCardStyleOverrides = (card: any): Record<string, any> => {
    const o = card && (card as any)._cardStyleOverrides;
    return o && typeof o === 'object' ? o as Record<string, any> : {};
};
const cardHasStyleOverride = (card: any, prop: any): boolean =>
    Object.prototype.hasOwnProperty.call(getCardStyleOverrides(card), String(prop || '').trim());
const setCardStyleOverride = (card: any, prop: any, value: any) => {
    if (!card || !isLabelStyleOverridableProp(prop)) return;
    const current = (card as any)._cardStyleOverrides;
    const map: Record<string, any> = current && typeof current === 'object' ? current : {};
    map[String(prop).trim()] = value;
    (card as any)._cardStyleOverrides = map;
};
const clearCardStyleOverrides = (card: any, props?: Iterable<string>) => {
    const map = (card as any)?._cardStyleOverrides;
    if (!map || typeof map !== 'object') return;
    if (!props) { (card as any)._cardStyleOverrides = {}; return; }
    for (const p of props) delete map[String(p || '').trim()];
};

// Etiquetas individuais precisam ser diferenciadas das etiquetas herdadas da
// zona. Antes desse marcador, o ID ficava salvo no card tanto para uma escolha
// individual quanto para uma troca em lote; ao reabrir o encarte a zona podia
// apontar para um modelo e cada card continuar renderizando outro.
const setCardLabelTemplateMetadata = (
    card: any,
    templateId?: string | null,
    explicitOverride = false
) => {
    if (!card) return;
    const id = String(templateId || '').trim();
    if (id) {
        (card as any).__cardLabelTemplateId = id;
        (card as any).__cardLabelTemplateOverride = explicitOverride === true;
    } else {
        delete (card as any).__cardLabelTemplateId;
        delete (card as any).__cardLabelTemplateOverride;
    }
};

const cardHasExplicitLabelTemplateOverride = (card: any): boolean =>
    (card as any)?.__cardLabelTemplateOverride === true;

// Estilos efetivos do card = estilos da zona + overrides do card por cima.
const getEffectiveStylesForCard = (card: any, zone?: any): GlobalStyles => {
    const base = getZoneGlobalStyles(zone);
    const cardOv = getCardStyleOverrides(card);
    return Object.keys(cardOv).length ? normalizeGlobalStyles({ ...base, ...cardOv }) : base;
};

// Reaplica somente a receita estrutural do card depois de um movimento que não
// precisou passar pelo resizeSmartObject (por exemplo, troca entre slots do
// mesmo tamanho). A etiqueta pode manter a âncora manual, mas sua área visual
// continua limitada pelo perfil configurado em Cards.
const reapplyProductCardConfigurationLayout = (
    card: any,
    zone?: any,
    dimensions?: { width?: number; height?: number }
): boolean => {
    if (!card || !productCardConfigurationState.isLoaded.value) return false;

    const width = Math.abs(Number(
        dimensions?.width ??
        (card as any)?._cardWidth ??
        card?.width ??
        card?.getScaledWidth?.() ??
        0
    ) || 0);
    const height = Math.abs(Number(
        dimensions?.height ??
        (card as any)?._cardHeight ??
        card?.height ??
        card?.getScaledHeight?.() ??
        0
    ) || 0);
    if (!Number.isFinite(width) || !Number.isFinite(height) || width < 2 || height < 2) return false;

    const effectiveStyles = normalizeGlobalStyles({
        ...getEffectiveStylesForCard(card, zone),
        // A zona antiga pode ainda não ter recebido o cardLayout global no
        // momento exato da troca de slot. O estado carregado da configuração
        // é a fonte de verdade para esse relayout pontual.
        cardLayout: productCardConfigurationState.configuration.value
    });
    productCardConfiguration.applyProductCardConfigurationLayout(card, width, height, effectiveStyles);
    if (zone) harmonizeProductCardTypography(getZoneChildren(zone));
    return true;
};
// Resolve o card alvo: por _customId, senao a selecao atual (se for card de produto).
const resolveSelectedProductCard = (cardId?: string): any => {
    if (cardId) {
        for (const z of getRuntimeProductZones()) {
            const found = (getZoneChildren(z) || []).find((c: any) => String(c?._customId || '') === String(cardId));
            if (found) return found;
        }
    }
    const sel = selectedObjectRef.value;
    return (sel && isLikelyProductCard(sel)) ? sel : null;
};
// UI "editar so este card": grava override no card, aplica so nele e persiste.
const handleUpdateCardStyle = async (prop: string, value: any, cardId?: string) => {
    if (!canvas.value) return;
    const card = resolveSelectedProductCard(cardId);
    if (!card || !isLabelStyleOverridableProp(prop)) return;
    setCardStyleOverride(card, prop, value);
    const zoneId = String((card as any)?.parentZoneId || '').trim();
    const zone = zoneId ? findProductZoneById(zoneId) : null;
    const eff = getEffectiveStylesForCard(card, zone);
    (card as any).__forceCardRelayout = true;
    applyGlobalStylesToCards(eff, zone, { cards: [card], prop });
    safeRequestRenderAll();
    refreshSelectedRef();
    await saveCurrentState({ reason: `card-style:${prop}`, skipIfUnchanged: false });
};
// UI "voltar ao padrao da zona": remove os overrides do card e reaplica a zona.
const handleResetCardStyle = async (cardId?: string) => {
    if (!canvas.value) return;
    const card = resolveSelectedProductCard(cardId);
    if (!card) return;
    const hadProps = Object.keys(getCardStyleOverrides(card));
    if (!hadProps.length) return;
    clearCardStyleOverrides(card);
    const zoneId = String((card as any)?.parentZoneId || '').trim();
    const zone = zoneId ? findProductZoneById(zoneId) : null;
    (card as any).__forceCardRelayout = true;
    // Reconstroi o card a partir do template da zona (para ficar igual aos irmaos),
    // depois reaplica apenas os overrides EXPLICITOS da zona por cima.
    const tplId = String(
        (zone as any)?._zoneGlobalStyles?.splashTemplateId ||
        (zone as any)?._zoneTemplateSnapshotId ||
        ''
    ).trim();
    try {
        if (tplId) await applyLabelTemplateToCard(card, tplId);
    } catch (err) {
        console.warn('[card-style] Falha ao reconstruir card do template no reset:', err);
    }
    const zoneStyles = getZoneGlobalStyles(zone);
    const zoneOv = getZoneStyleOverrides(zone);
    Object.keys(zoneOv).forEach((prop) => applyGlobalStylesToCards(zoneStyles, zone, { cards: [card], prop }));
    safeRequestRenderAll();
    refreshSelectedRef();
    await saveCurrentState({ reason: 'card-style:reset', skipIfUnchanged: false });
};

// O snapshot acompanha a seleção, mas a alteração sempre usa o card real pelo ID.
const quickSelectedCardConfiguration = computed(() => {
    const selected = selectedObjectRef.value;
    if (!isQuickMode.value || !selected || String(selected.type || '').toLowerCase() === 'activeselection') return null;
    const id = String(selected.parentCardId || (isLikelyProductCard(selected) ? selected._customId : '') || '').trim();
    if (!id) return null;
    return { id, profile: String(selected.__cardConfigurationProfile || '').trim() };
});
const quickCardConfigurationOptions = computed(() => {
    if (!productCardConfigurationState.isLoaded.value || !productCardConfigurationState.configuration.value.enabled) return [];
    const names = { compact: 'Compacto', standard: 'Médio', wide: 'Largo', tall: 'Vertical estreito', featured: 'Destaque' };
    return PRODUCT_CARD_CONFIGURATION_PROFILE_KEYS
        .filter(key => productCardConfigurationState.configuration.value.profiles?.[key])
        .map(key => ({ id: key, name: names[key] }));
});

// Permite escolher manualmente um dos modelos cadastrados para um unico card.
// Sem escolha explicita, o layout continua sendo resolvido automaticamente
// pelo formato e pela funcao da zona.
const handleUpdateCardConfigurationProfile = async (profileValue: string, cardId?: string) => {
    if (!canvas.value) return;
    const card = resolveSelectedProductCard(cardId);
    if (!card) return;

    const nextProfile = PRODUCT_CARD_CONFIGURATION_PROFILE_KEYS.find((key) => key === String(profileValue || '').trim()) || '';
    const currentProfile = String((card as any).__cardConfigurationProfile || '').trim();
    if (currentProfile === nextProfile) {
        refreshSelectedRef();
        return;
    }

    if (nextProfile) (card as any).__cardConfigurationProfile = nextProfile;
    else delete (card as any).__cardConfigurationProfile;

    const zoneId = String((card as any)?.parentZoneId || '').trim();
    const zone = zoneId ? findProductZoneById(zoneId) : null;
    const effectiveStyles = getEffectiveStylesForCard(card, zone);
    (card as any).__forceCardRelayout = true;
    applyGlobalStylesToCards(effectiveStyles, zone, {
        cards: [card],
        prop: 'cardConfigurationProfile'
    });
    safeRequestRenderAll();
    refreshSelectedRef();
    await saveCurrentState({ reason: 'card-configuration-profile', skipIfUnchanged: false });
};

// DEBOUNCED_GLOBAL_STYLE_PROPS e isDebouncedGlobalStyleProp extraidos para
// utils/globalStylePropClassifiers.ts.

const scheduleGlobalStylesStateSave = (prop: string) => {
    const immediate = !isDebouncedGlobalStyleProp(prop);
    if (globalStylesSaveTimer) {
        clearTimeout(globalStylesSaveTimer);
        globalStylesSaveTimer = null;
    }

    if (immediate) {
        saveCurrentState({ reason: `global-style:${prop}`, skipIfUnchanged: false });
        return;
    }

    globalStylesSaveTimer = setTimeout(() => {
        globalStylesSaveTimer = null;
        saveCurrentState({ reason: 'global-style:debounced', skipIfUnchanged: false });
    }, 180);
};

const getCurrentZoneObject = () => {
    if (!canvas.value) return null;

    // 1. Check active canvas object first (the real Fabric object)
    const active = canvas.value.getActiveObject?.();
    if (active && isLikelyProductZone(active)) return active;

    // 2. If active is a product card, find its parent zone on canvas
    if (active && isLikelyProductCard(active)) {
        const parentZoneId = (active as any).parentZoneId;
        if (parentZoneId) {
            const zone = findProductZoneById(parentZoneId);
            if (zone) return zone;
        }
    }

    // 3. If selected snapshot looks like a zone, find the REAL Fabric object by _customId
    // CRITICAL: Use isLikelyProductZone() for FULL detection (flags, name, custom props, strokeDashArray)
    // instead of checking individual properties. This is essential for legacy arts where flags
    // may not have been serialized originally.
    const selected = selectedObjectRef.value as any;
    if (selected && (selected.isGridZone || selected.isProductZone || selected.name === 'gridZone' || selected.name === 'productZoneContainer'
        || (typeof selected._zonePadding === 'number' && typeof selected._zoneWidth === 'number')
    )) {
        const zoneId = selected._customId;
        if (zoneId) {
            // First try with full detection
            let zone = findProductZoneById(zoneId);
            if (zone) return zone;
            // Fallback: find by _customId alone and set flags if it's a group
            // (handles edge case where real object lost flags but snapshot preserved them)
            zone = canvas.value.getObjects().find((o: any) => o._customId === zoneId && o.type === 'group');
            if (zone) {
                zone.isGridZone = true;
                ensureZoneSanity(zone);
                return zone;
            }
        }
    }

    // 4. If selected snapshot is a product card, find parent zone on canvas
    if (selected && isLikelyProductCard(selected)) {
        const parentZoneId = selected.parentZoneId;
        if (parentZoneId) {
            const zone = findProductZoneById(parentZoneId);
            if (zone) return zone;
        }
    }

    // 5. FALLBACK: If snapshot has _customId, try to find any matching object on canvas
    // This handles cases where Fabric v7 lost flags but the object still exists
    if (selected && selected._customId) {
        const obj = canvas.value.getObjects().find((o: any) => o._customId === selected._customId);
        if (obj && obj.type === 'group' && isLikelyProductZone(obj)) {
            return obj;
        }
    }

    // Do not auto-pick a zone while rendering. The old single-zone fallback
    // called getRuntimeProductZones(), which builds/repairs runtime indexes and
    // can mutate reactive Fabric objects from a computed getter. A zone becomes
    // the current target only after an explicit Fabric selection or import
    // action has established that relationship.

    return null;
}

