const handleProductImageFill = async (count: number, direction = 'auto') => {
    const context = resolveSelectedProductImageActionContext()
    if (!context || !Number.isInteger(count) || count < 0 || count > 4) return
    const card = context.card
    card._productData = { ...card._productData, autoFillImages: true, imageFillInitialized: true, imageFillCount: count || undefined, imageFillDirection: ['auto', 'horizontal', 'vertical'].includes(direction) ? direction : 'auto' }
    for (const image of collectDirectProductCardImages(card)) {
        image.__manualTransform = false
        await autoTrimFabricImageAsync(image, { preserveVisualPosition: false })
    }
    card.__forceCardRelayout = true
    const fillStyles = { ...(card as any)._zoneGlobalStyles, cardLayout: productCardConfigurationState.configuration.value }
    resizeSmartObject(card, Number(card._cardWidth || card.width), Number(card._cardHeight || card.height), fillStyles)
    refreshCanvasObjects({ immediate: true })
    safeRequestRenderAll()
    await saveCurrentState({ reason: 'product-image-fill', skipIfUnchanged: false })
}

const handleProductImageRemove = () => {
    const context = resolveSelectedProductImageActionContext();
    if (!context || !canvas.value) return;
    const remaining = collectDirectProductCardImages(context.card).filter((image: any) => image !== context.image);
    const source = remaining[0]?.__originalSrc || remaining[0]?.getSrc?.() || '';
    context.card._productData = { ...context.card._productData, imageUrl: source, image: source, autoFillImages: false, imageFillInitialized: true };
    canvas.value.setActiveObject(context.image);
    deleteActiveSelectionFromCanvas();
};

const handleProductImageDuplicate = async () => {
    if (!canvas.value) return
    const context = resolveSelectedProductImageActionContext()
    if (!context) return

    if (context.card._productData) {
        context.card._productData.autoFillImages = false
        context.card._productData.imageFillInitialized = true
    }

    // A cópia mantém o mesmo tamanho/rotação, mas nasce com um pequeno
    // deslocamento horizontal. Assim o usuário confirma imediatamente que a
    // duplicação aconteceu, sem redistribuir as imagens do card.
    const duplicateOffset = Number(DUPLICATE_OFFSET) || 20
    const sourceTransform = getProductImageDuplicatePlacement(context.image, {
        offsetX: duplicateOffset,
        offsetY: 0
    })

    let cloned: any = null
    try {
        cloned = await duplicateObjectWithContext(context.image, { offsetX: 0, offsetY: 0 })
    } catch (error) {
        console.warn('[product-image-actions] Falha ao duplicar imagem', error)
    }
    if (!cloned) {
        notifyEditorError('Não foi possível duplicar a imagem do produto.')
        return
    }

    // Imagens duplicadas passam a fazer parte da composição manual do card.
    // Registrar a dimensão atual da célula permite que o relayout da zona
    // redimensione posição e escala de forma proporcional quando a quantidade
    // de produtos mudar (por exemplo, após excluir outro produto).
    const duplicateCardWidth = Number((context.card as any)?._cardWidth ?? context.card?.width ?? 0)
    const duplicateCardHeight = Number((context.card as any)?._cardHeight ?? context.card?.height ?? 0)
    const markManualProductImage = (image: any, overwriteBaseline = false) => {
        if (!image) return
        ;(image as any).__manualTransform = true
        if (duplicateCardWidth > 0 && (overwriteBaseline || !Number.isFinite(Number((image as any).__manualTransformCardW)))) {
            ;(image as any).__manualTransformCardW = duplicateCardWidth
        }
        if (duplicateCardHeight > 0 && (overwriteBaseline || !Number.isFinite(Number((image as any).__manualTransformCardH)))) {
            ;(image as any).__manualTransformCardH = duplicateCardHeight
        }
    }
    markManualProductImage(context.image)

    const sourceData = (context.image as any)?.data && typeof (context.image as any).data === 'object'
        ? (context.image as any).data
        : {}
    cloned.set?.({
        ...sourceTransform,
        visible: true,
        selectable: true,
        evented: true,
        data: { ...sourceData, smartType: 'product-image' },
        name: 'extra_image'
    })
    markManualProductImage(cloned, true)
    cloned.parentZoneId = undefined
    cloned.parentFrameId = undefined

    context.card.set?.({ dirty: true, subTargetCheck: true, interactive: true })
    context.card.setCoords?.()
    selectedProductImageSubTarget.value = cloned
    selectedProductImageSelectionKind.value = 'image'
    canvas.value.setActiveObject(cloned)
    refreshCanvasObjects()
    safeRequestRenderAll()
    updateSelection()
    await saveCurrentState({ reason: 'product-image-duplicate', skipIfUnchanged: false })
}

const handleProductImageResize = (direction: 'smaller' | 'larger') => {
    const context = resolveSelectedProductImageActionContext()
    if (!context) return
    const image = context.image
    const currentScaleX = Math.abs(Number(image.scaleX ?? 1)) || 1
    const currentScaleY = Math.abs(Number(image.scaleY ?? 1)) || 1
    const factor = direction === 'larger' ? 1.08 : 0.92
    const nextScaleX = Math.max(0.05, Math.min(8, currentScaleX * factor))
    const nextScaleY = Math.max(0.05, Math.min(8, currentScaleY * factor))
    image.set?.({ scaleX: nextScaleX, scaleY: nextScaleY, dirty: true })
    image.setCoords?.()
    applyContainmentConstraints(image)
    context.card.set?.({ dirty: true })
    context.card.setCoords?.()
    refreshSelectedRef()
    updateFloatingUI()
    safeRequestRenderAll()
    void saveCurrentState({ reason: 'product-image-resize', skipIfUnchanged: false })
}

const handleProductImageTemplateChange = async (templateId: string) => {
    const context = resolveSelectedProductImageActionContext()
    const id = String(templateId || '').trim()
    if (!context || !id) return

    const template = labelTemplates.value.find((item: any) => String(item?.id || '').trim() === id)
    if (!template) {
        notifyEditorError('A etiqueta selecionada não está disponível.')
        return
    }
    if (!isProductLabelTemplateCompatible(context.card, template)) {
        notifyEditorError('Escolha uma etiqueta compatível com os preços deste produto.')
        return
    }
    const hasPriceGroup = typeof context.card.getObjects === 'function' && context.card.getObjects().some((item: any) => (
        String(item?.type || '').toLowerCase() === 'group' && String(item?.name || '') === 'priceGroup'
    ))
    if (!hasPriceGroup) {
        notifyEditorError('Este card ainda não possui uma etiqueta de preço.')
        return
    }

    const previousTemplateId = String((context.card as any).__cardLabelTemplateId || '').trim()
    const hadPreviousTemplateId = Object.prototype.hasOwnProperty.call(context.card, '__cardLabelTemplateId')
    const previousTemplateOverride = (context.card as any).__cardLabelTemplateOverride
    const hadPreviousTemplateOverride = Object.prototype.hasOwnProperty.call(context.card, '__cardLabelTemplateOverride')
    // Registre a escolha antes do trabalho assíncrono. Se houver um autosave ou
    // uma troca de seleção durante a aplicação, o snapshot já carrega a opção
    // escolhida em vez de capturar a etiqueta anterior.
    setCardLabelTemplateMetadata(context.card, id, true)
    context.card.set?.({ dirty: true })
    try {
        await applyLabelTemplateToCard(context.card, id)
        setCardLabelTemplateMetadata(context.card, id, true)
        context.card.set?.({ dirty: true })
        context.card.setCoords?.()
        refreshSelectedRef()
        updateSelection()
        safeRequestRenderAll()
        if (isQuickMode.value) {
            await persistQuickModeDataChange('quick-product-image-template')
        } else {
            await saveCurrentState({ reason: 'product-image-template', skipIfUnchanged: false })
        }
    } catch (error) {
        if (hadPreviousTemplateId) (context.card as any).__cardLabelTemplateId = previousTemplateId
        else delete (context.card as any).__cardLabelTemplateId
        if (hadPreviousTemplateOverride) (context.card as any).__cardLabelTemplateOverride = previousTemplateOverride
        else delete (context.card as any).__cardLabelTemplateOverride
        console.warn('[product-image-actions] Falha ao trocar etiqueta do card', error)
        notifyEditorError('Não foi possível trocar a etiqueta deste card.')
    }
}

const handleProductLabelModeChange = (mode: ProductLabelInteractionMode) => {
    const context = resolveSelectedProductLabelActionContext()
    if (!context) return
    if (!isPriceGroupObject(context.priceGroup)) return

    canvas.value?.discardActiveObject?.()
    canvas.value?.setActiveObject?.(context.priceGroup)
    if (!setPriceGroupInteractionMode(context.priceGroup, mode)) return
    selectedPriceGroupSubTarget.value = context.priceGroup
    selectedPriceGroupSelectionKind.value = 'label'
    context.priceGroup.setCoords?.()
    refreshSelectedRef()
    updateSelection()
    safeRequestRenderAll()
}

const handleProductLabelSelectAll = () => {
    const context = resolveSelectedProductLabelActionContext()
    if (!context) return

    const canvasInstance = canvas.value
    if (!canvasInstance) return

    // Clear the previous selection first so its deselection handler cannot
    // immediately reset the edit mode we are about to enter.
    canvasInstance.discardActiveObject?.()
    if (!setPriceGroupInteractionMode(context.priceGroup, 'edit')) return

    const members = (context.priceGroup.getObjects?.() || []).filter((child: any) => (
        child &&
        child.visible !== false &&
        child.selectable !== false &&
        !isPriceGroupBackground(child)
    ))

    try {
        if (members.length === 1) {
            canvasInstance.setActiveObject(members[0])
        } else if (members.length > 1 && fabric?.ActiveSelection) {
            const selection = new fabric.ActiveSelection(members, { canvas: canvasInstance })
            canvasInstance.setActiveObject(selection)
        } else {
            canvasInstance.setActiveObject(context.priceGroup)
        }
    } catch {
        // A malformed legacy label should still fall back to selecting the
        // group instead of leaving the editor without an active target.
        canvasInstance.discardActiveObject?.()
        canvasInstance.setActiveObject?.(context.priceGroup)
    }

    selectedPriceGroupSubTarget.value = context.priceGroup
    selectedPriceGroupSelectionKind.value = 'label'
    context.priceGroup.setCoords?.()
    refreshSelectedRef()
    updateSelection()
    safeRequestRenderAll()
}

const handleProductLabelTemplateChange = async (templateId: string) => {
    const context = resolveSelectedProductLabelActionContext()
    const id = String(templateId || '').trim()
    if (!context || !id) return

    const template = labelTemplates.value.find((item: any) => String(item?.id || '').trim() === id)
    if (!template) {
        notifyEditorError('A etiqueta selecionada não está disponível.')
        return
    }
    if (!isProductLabelTemplateCompatible(context.card, template)) {
        notifyEditorError('Escolha uma etiqueta compatível com os preços deste produto.')
        return
    }

    const previousTemplateId = String((context.card as any).__cardLabelTemplateId || '').trim()
    const hadPreviousTemplateId = Object.prototype.hasOwnProperty.call(context.card, '__cardLabelTemplateId')
    const previousTemplateOverride = (context.card as any).__cardLabelTemplateOverride
    const hadPreviousTemplateOverride = Object.prototype.hasOwnProperty.call(context.card, '__cardLabelTemplateOverride')
    setCardLabelTemplateMetadata(context.card, id, true)
    context.card.set?.({ dirty: true })
    try {
        await applyLabelTemplateToCard(context.card, id)
        setCardLabelTemplateMetadata(context.card, id, true)
        context.card.set?.({ dirty: true })
        context.card.setCoords?.()

        const nextPriceGroup = getPriceGroupFromAny(context.card)
        if (nextPriceGroup) {
            setPriceGroupInteractionMode(nextPriceGroup, 'move')
            selectedPriceGroupSubTarget.value = null
            selectedPriceGroupSelectionKind.value = 'label'
            canvas.value?.discardActiveObject?.()
            canvas.value?.setActiveObject?.(nextPriceGroup)
        }
        refreshSelectedRef()
        updateSelection()
        safeRequestRenderAll()
        if (isQuickMode.value) {
            await persistQuickModeDataChange('quick-product-label-template')
        } else {
            await saveCurrentState({ reason: 'product-label-template', skipIfUnchanged: false })
        }
    } catch (error) {
        if (hadPreviousTemplateId) (context.card as any).__cardLabelTemplateId = previousTemplateId
        else delete (context.card as any).__cardLabelTemplateId
        if (hadPreviousTemplateOverride) (context.card as any).__cardLabelTemplateOverride = previousTemplateOverride
        else delete (context.card as any).__cardLabelTemplateOverride
        console.warn('[product-label-actions] Falha ao trocar etiqueta do card', error)
        notifyEditorError('Não foi possível trocar a etiqueta deste card.')
    }
}

type ZoneUpdateTargetMeta = {
    targetId?: string | null
}

const resolveZoneTargetsForUpdates = (opts: { allowAllFallback?: boolean; targetId?: string | null } = {}) => {
    if (!canvas.value) return [] as any[];

    const zones = getRuntimeProductZones();
    const byId = new Map<string, any>();
    zones.forEach((z: any) => {
        const id = String(z?._customId || '').trim();
        if (id) byId.set(id, z);
    });

    const resolved: any[] = [];
    const pushZone = (z: any) => {
        if (!z || !isLikelyProductZone(z)) return;
        if (!resolved.includes(z)) resolved.push(z);
    };

    const targetId = String(opts.targetId || '').trim();
    if (targetId) {
        const target = byId.get(targetId);
        if (target) {
            if (import.meta.dev) {
                console.debug('[product-zone:targeted-update]', {
                    targetId,
                    selectedId: String(canvas.value.getActiveObject?.()?._customId || selectedObjectRef.value?._customId || '').trim() || null
                });
            }
            return [target];
        }
        if (import.meta.dev) {
            console.debug('[product-zone:targeted-update:skip]', { targetId, reason: 'target-not-found' });
        }
        return [];
    }

    // 1) Primary source: currently resolved zone (active/snapshot/card parent).
    pushZone(getCurrentZoneObject());

    // 2) Snapshot selected zone id.
    const snap = selectedObjectRef.value as any;
    const snapId = String(snap?._customId || '').trim();
    if (snapId && byId.has(snapId)) pushZone(byId.get(snapId));

    // 3) Snapshot selected card parent zone.
    const parentId = String(snap?.parentZoneId || '').trim();
    if (parentId && byId.has(parentId)) pushZone(byId.get(parentId));

    // 4) If still unresolved and there is only one zone in canvas, use it.
    if (!resolved.length && zones.length === 1) pushZone(zones[0]);

    // 5) Emergency fallback: only use when the caller explicitly requests a broadcast.
    if (!resolved.length && opts.allowAllFallback && zones.length > 0) {
        zones.forEach((z: any) => pushZone(z));
    }

    return resolved;
}

// resolveZoneUpdatesPayload extraido para utils/zoneUpdatesPayload.ts.

// Estruturas por quantidade pertencem à biblioteca global. O JSON antigo do
// projeto continua sendo usado apenas como fallback enquanto a API carrega,
// mas nunca pode voltar a sobrescrever a configuração global já resolvida.
// A receita é global; a escolha da variação continua sendo local por zona.
const GLOBAL_PRODUCT_ZONE_STRUCTURE_PROPS = new Set([
    'structureByProductCountEnabled',
    'structureByProductCount',
    'structureByProductCountByPreviewFormat',
    'structureVariantsByProductCount',
    'structureVariantsByProductCountByPreviewFormat'
]);

const stripLocalProductZoneStructureUpdates = (updates: Record<string, any>): Record<string, any> => {
    if (!productZoneStructuresState.isLoaded.value) return updates;
    return Object.fromEntries(
        Object.entries(updates).filter(([prop]) => !GLOBAL_PRODUCT_ZONE_STRUCTURE_PROPS.has(prop))
    );
};

const handleUpdateZone = async (propOrPayload: string | Record<string, any>, val?: any, meta?: ZoneUpdateTargetMeta) => {
    const updates = stripLocalProductZoneStructureUpdates(resolveZoneUpdatesPayload(propOrPayload, val));
    const entries = Object.entries(updates).filter(([key]) => key && key !== 'prop' && key !== 'value');
    if (!entries.length) {
        console.warn('⚠️ [handleUpdateZone] Invalid payload received:', propOrPayload);
        return;
    }

    const targets = resolveZoneTargetsForUpdates({ allowAllFallback: false, targetId: meta?.targetId });
    if (!targets.length) {
        console.warn('⚠️ [handleUpdateZone] No zone resolved; skipping update to avoid UI/canvas divergence');
        return;
    }

    // 1. Update Reactive State
    productZoneState.updateZone(Object.fromEntries(entries));

    // 2. Apply to Canvas Object. Se algum prop falhar, logamos e seguimos — o estado
    // reativo ja reflete a intencao e o proximo save/render tentara sincronizar.
    try {
        await updateZoneOnCanvas(Object.fromEntries(entries), undefined, meta);
    } catch (err) {
        console.warn('⚠️ [handleUpdateZone] Falha ao aplicar updates no canvas:', err);
    }
}

const applyZoneUpdates = async (zone: any, updates: Record<string, any>, opts: { save?: boolean; saveReason?: string } = {}) => {
    if (!canvas.value || !zone) return;
    updates = stripLocalProductZoneStructureUpdates(updates);
    if (!Object.keys(updates).length) return;
    ensureZoneSanity(zone);

    // CRITICAL: Save zone reference BEFORE any Fabric layout operations.
    // In Fabric v7, triggerLayout() can deselect the active object,
    // causing refreshSelectedRef to lose the zone.
    const zoneId = zone._customId;

    const zoneRect = getZoneRect(zone);
    const relayoutProps = new Set([
        'padding',
        'gapHorizontal',
        'gapVertical',
        'columns',
        'rows',
        'cardAspectRatio',
        'lastRowBehavior',
        'layoutDirection',
        'verticalAlign',
        'structureByProductCountEnabled',
        'structureByProductCount',
        'structureVariantsByProductCount',
        'structureVariantByProductCount',
        'structureVariantByProductCountByPreviewFormat',
        'highlightCount',
        'highlightPos',
        'highlightSelection',
        'highlightIndexes',
        'highlightHeight'
    ]);

    let shouldRelayout = false;
    let hasRelayoutPropUpdate = false;
    const markRelayoutIfChanged = (current: any, next: any, tolerance = 0.001) => {
        const currentNum = Number(current);
        const nextNum = Number(next);
        const bothNumeric = Number.isFinite(currentNum) && Number.isFinite(nextNum);
        hasRelayoutPropUpdate = true;
        if (bothNumeric) {
            if (Math.abs(currentNum - nextNum) > tolerance) shouldRelayout = true;
            return;
        }
        if (String(current ?? '') !== String(next ?? '')) shouldRelayout = true;
    };

    // FIX: Permanently disable Fabric v7 LayoutManager on zone groups.
    // Zone layout is fully managed by recalculateZoneLayout — Fabric's auto-layout
    // only causes corruption by recalculating bounds from children at stale positions.
    // Previously this was temporarily disabled and restored, but the restore allowed
    // Fabric to re-trigger layout between operations (especially during preset changes
    // where multiple properties are set), shifting the group center and corrupting
    // all subsequent card position calculations.
    const zoneLm = (zone as any).layoutManager;
    if (zoneLm && typeof zoneLm.performLayout === 'function' && zoneLm.performLayout.toString() !== '() => {}') {
        zoneLm.performLayout = () => {};
    }

    try {
    Object.entries(updates).forEach(([prop, val]) => {
        if (prop === 'padding') {
            // Sanitiza padding: negativo nao faz sentido; acima de 200 quebra layout
            // (deixa cards muito pequenos). Clamp defensivo no handler evita JSON
            // injetado externamente corromper a zona.
            const n = Math.max(0, Math.min(200, Number(val) || 0));
            markRelayoutIfChanged(zone._zonePadding, n);
            zone._zonePadding = n;
            zone.set('padding', 0);
            return;
        }

        if (prop === 'name') {
            zone.set('zoneName', String(val || '').trim() || getNextProductZoneName(zone));
            ensureProductZoneNamesDistinct();
            return;
        }

        if (prop === 'highlightCount') {
            // Clamp para nao ultrapassar o numero de cards reais. Sem isso o UI
            // aceitava valores arbitrarios e o runtime silenciosamente reduzia,
            // divergindo do que o composable armazenava.
            const cardCount = getZoneChildren(zone)?.length || 0;
            const n = Math.max(0, Math.min(cardCount, Number(val) || 0));
            markRelayoutIfChanged((zone as any).highlightCount, n);
            zone.set('highlightCount', n);
            return;
        }

        if (prop === 'isLocked') {
            const locked = !!val;
            zone.set({
                isLocked: locked,
                lockMovementX: locked,
                lockMovementY: locked,
                lockScalingX: locked,
                lockScalingY: locked
            });
            // Cards filhos herdam o lock visual para nao ficarem editaveis com zona trancada.
            try {
                const children = getZoneChildren(zone) || [];
                children.forEach((card: any) => {
                    card.set({
                        lockMovementX: locked,
                        lockMovementY: locked,
                        lockScalingX: locked,
                        lockScalingY: locked,
                        selectable: !locked
                    });
                    card.setCoords?.();
                });
            } catch { /* ignore */ }
            zoneRect?.set?.('dirty', true);
            return;
        }

        // Visual props live on the inner rect. Persistem tambem na zone para sobreviver ao reload.
        if (prop === 'backgroundColor' && zoneRect) {
            zone.set('backgroundColor', val);
            zoneRect.set('fill', val || 'transparent');
            zoneRect.set('dirty', true);
            return;
        }
        if (prop === 'borderColor' && zoneRect) {
            zone.set('borderColor', val);
            zoneRect.set('stroke', val);
            zoneRect.set('dirty', true);
            return;
        }
        if (prop === 'borderWidth' && zoneRect) {
            const w = Number(val);
            zone.set('borderWidth', w);
            zoneRect.set('strokeWidth', w);
            zoneRect.set('dirty', true);
            return;
        }
        if (prop === 'borderRadius' && zoneRect) {
            const r = Number(val);
            zone.set('borderRadius', r);
            zoneRect.set({ rx: r, ry: r });
            zoneRect.set('dirty', true);
            return;
        }
        if (prop === 'showBorder' && zoneRect) {
            zone.set('showBorder', !!val);
            zoneRect.set('strokeWidth', val ? Math.max(zoneRect.strokeWidth || 0, 2) : 0);
            zoneRect.set('dirty', true);
            return;
        }

        if (
            prop === 'structureByProductCountEnabled' ||
            prop === 'structureByProductCount' ||
            prop === 'structureVariantsByProductCount' ||
            prop === 'structureVariantByProductCount' ||
            prop === 'structureVariantByProductCountByPreviewFormat'
        ) {
            hasRelayoutPropUpdate = true;
            shouldRelayout = true;
        } else if (relayoutProps.has(prop)) {
            markRelayoutIfChanged((zone as any)?.[prop], val);
        }
        zone.set(prop, val);
    });
    if (opts.saveReason === 'preset-change' && hasRelayoutPropUpdate) {
        shouldRelayout = true;
    }
    } finally {
        // FIX: LayoutManager stays permanently disabled — no restore needed.
        // Restoring it allowed Fabric to re-trigger layout between the property set
        // and the explicit recalculateZoneLayout, shifting the group origin and
        // corrupting card positions (especially during preset changes).
    }

    // FIX Fabric v7: Avoid triggerLayout() for non-structural changes.
    // triggerLayout() can deselect the zone group, breaking the UI loop.
    // Only recalculate group bounds when children/structure actually changed.
    let restoredViewportObjects = 0;
    if (shouldRelayout) {
        // FIX: Only restore viewport-culled objects that belong to this zone (by parentZoneId
        // or _zoneSlot), not ALL canvas objects. Restoring everything causes a visible flash
        // of unrelated objects before re-culling kicks in.
        const zoneChildIds = new Set<any>();
        const allObjs = canvas.value.getObjects?.() || [];
        for (const obj of allObjs) {
            if (!obj) continue;
            const boundId = String((obj as any)?.parentZoneId || '').trim();
            const slotId = String((obj as any)?._zoneSlot?.zoneId || '').trim();
            if ((zoneId && boundId === zoneId) || (zoneId && slotId === zoneId) || obj === zone) {
                zoneChildIds.add(obj);
            }
        }
        const zoneRelatedObjs = allObjs.filter((o: any) => zoneChildIds.has(o));
        restoredViewportObjects = restoreViewportCulledObjects(zoneRelatedObjs);
        // FIX: Also force-restore visibility for zone cards that lost their
        // __viewportCulled flag (e.g. after undo/redo or culling cleanup) but
        // remain invisible.  Without this, getZoneChildren skips them and the
        // relayout silently produces an empty grid.
        for (const obj of zoneRelatedObjs) {
            if (obj && obj !== zone && obj.visible === false && !(obj as any).__viewportCulled) {
                obj.visible = true;
                obj.dirty = true;
                restoredViewportObjects++;
            }
        }
        if (restoredViewportObjects > 0) {
            resetViewportCullSignature();
        }

        // Mark zone dirty and update coords (lightweight alternative to full addWithUpdate/triggerLayout)
        zone.dirty = true;
        zone.setCoords();
        // Cache children before relayout to prevent losing them
        const cachedChildren = getZoneChildren(zone);
        recalculateZoneLayout(zone, cachedChildren, { save: false, requestRender: false });

        // FIX: Force dirty flags on ALL cards and their children after relayout.
        // Fabric v7 caches group renders; without explicit dirty flags, cards may
        // display stale cached content after a preset change resizes them.
        // Reuse cachedChildren — relayout repositions cards in-place, doesn't add/remove them.
        for (const card of cachedChildren) {
            if (!card) continue;
            card.dirty = true;
            if (typeof card.getObjects === 'function') {
                for (const child of (card.getObjects() || [])) {
                    if (child) child.dirty = true;
                    // Also invalidate nested groups (e.g., priceGroup children)
                    if (child && typeof child.getObjects === 'function') {
                        for (const nested of (child.getObjects() || [])) {
                            if (nested) nested.dirty = true;
                        }
                    }
                }
            }
            card.setCoords();
        }
    } else {
        // For non-relayout property changes, just update coords and mark dirty
        zone.dirty = true;
        if (zoneRect) zoneRect.dirty = true;
        zone.setCoords();
    }

    // FIX Fabric v7: Re-select zone if it got deselected during layout recalculation
    const currentActive = canvas.value.getActiveObject?.();
    if (!currentActive || currentActive._customId !== zoneId) {
        try {
            canvas.value.setActiveObject(zone);
        } catch { /* ignore */ }
    }

    // Single render after all changes are applied
    safeRequestRenderAll();
    if (shouldRelayout || restoredViewportObjects > 0) {
        // FIX: Use requestAnimationFrame instead of queueMicrotask so that viewport
        // culling runs AFTER the first render completes. queueMicrotask runs before
        // the render frame, which can hide freshly-repositioned cards before they are
        // ever painted — causing the canvas to appear broken after preset changes.
        requestAnimationFrame(() => {
            applyViewportCulling('zone-relayout');
            // FIX: Second render pass after culling to ensure cards are properly displayed.
            // After a preset change (dramatic size change), Fabric v7 may cache stale group
            // renders from the first frame. This forces a clean second render.
            if (canvas.value) safeRequestRenderAll();
        });
    }
    if (opts.save !== false) {
        // FIX: Set flag to prevent object:modified event from also saving state (prevents duplicate entries).
        // Previously the flag was reset synchronously after an async saveCurrentState call, meaning
        // object:modified events during the actual save were NOT suppressed as intended.
        // Now we use try/finally with await to ensure the flag stays true until the save completes.
        applyingZoneUpdateCount++;
        try {
            await saveCurrentState({
                allowEmptyOverwrite: true,
                reason: opts.saveReason || 'object:modified(zone)'
            });
        } finally {
            applyingZoneUpdateCount = Math.max(0, applyingZoneUpdateCount - 1);
        }
    }
    // Refresh snapshot so PropertiesPanel picks up the new values
    refreshSelectedRef();
};

const updateZoneOnCanvas = async (propOrPayload: string | Record<string, any>, val?: any, meta?: ZoneUpdateTargetMeta) => {
    const updates = resolveZoneUpdatesPayload(propOrPayload, val);
    const entries = Object.entries(updates).filter(([key]) => key && key !== 'prop' && key !== 'value');
    if (!entries.length) {
        console.warn('⚠️ [updateZoneOnCanvas] Invalid payload received:', propOrPayload);
        return;
    }
    const normalizedUpdates = Object.fromEntries(entries);
    const targets = resolveZoneTargetsForUpdates({ allowAllFallback: false, targetId: meta?.targetId });
    if (!targets.length) {
        console.warn('⚠️ [updateZoneOnCanvas] No zone found! Cannot update canvas.');
        return;
    }
    if (targets.length === 1) {
        await applyZoneUpdates(targets[0], normalizedUpdates);
        return;
    }

    // Multiple target fallback (rare): apply without intermediate saves and commit once.
    for (const z of targets) {
        await applyZoneUpdates(z, normalizedUpdates, { save: false });
    }
    safeRequestRenderAll();
    await saveCurrentState();
    refreshSelectedRef();
}

// LIGHTWEIGHT_GLOBAL_STYLE_PROPS e isLightweightGlobalStyleProp extraidos para
// utils/globalStylePropClassifiers.ts.

// getCardBackgroundRect, getCardTitleText e getCardLimitText extraidos
// para utils/productCardLookup.ts.

const resolveCardTitleStateFromTarget = (target: any): { card: any | null; titleObj: any | null } => {
    if (!target) return { card: null, titleObj: null };

    if (isProductCardContainer(target)) {
        const titleObj = getCardTitleText(target);
        return titleObj ? { card: target, titleObj } : { card: null, titleObj: null };
    }

    const targetType = String(target?.type || '').toLowerCase();
    if (targetType !== 'text' && targetType !== 'i-text' && targetType !== 'textbox') {
        return { card: null, titleObj: null };
    }

    const card = findProductCardParentGroup(target);
    if (!card || !isProductCardContainer(card)) return { card: null, titleObj: null };

    const titleObj = getCardTitleText(card);
    if (!titleObj || titleObj !== target) return { card: null, titleObj: null };
    return { card, titleObj };
};

// getRenderedTextboxLinesForPersistence e buildPersistedCardTitleText
// extraidos para utils/cardTitlePersistence.ts.

function syncCardProductDataTitleWidthFromTarget(target: any): boolean {
    const { card, titleObj } = resolveCardTitleStateFromTarget(target);
    if (!card || !titleObj) return false;

    const currentText = String((titleObj as any).text ?? '').replace(/\r\n?/g, '\n');
    const renderedLines = getRenderedTextboxLinesForPersistence(titleObj);
    const hasPersistedWrap = currentText.includes('\n') || renderedLines.length > 1;
    if (!(titleObj as any).__manualTransform && !hasPersistedWrap) return false;

    const nextWidth = Number((titleObj as any).__manualTextWidth ?? titleObj.width ?? 0);
    if (!Number.isFinite(nextWidth) || nextWidth <= 0) return false;

    const cardW = Number((card as any)?._cardWidth ?? card?.width ?? card?.getScaledWidth?.() ?? 0);
    const rawRatio = Number((titleObj as any).__manualTextWidthRatio);
    const nextRatio = Number.isFinite(rawRatio) && rawRatio > 0
        ? Math.min(1, Math.max(0.1, rawRatio))
        : (Number.isFinite(cardW) && cardW > 0
            ? Math.min(1, Math.max(0.1, nextWidth / cardW))
            : null);

    const baseProductData = ((card as any)?._productData && typeof (card as any)._productData === 'object')
        ? (card as any)._productData
        : {};
    const currentWidth = Number(baseProductData.titleTextWidth);
    const currentRatio = Number(baseProductData.titleTextWidthRatio);
    const widthChanged = !Number.isFinite(currentWidth) || Math.abs(currentWidth - nextWidth) > 0.5;
    const ratioChanged = nextRatio !== null && (!Number.isFinite(currentRatio) || Math.abs(currentRatio - nextRatio) > 0.001);
    if (!widthChanged && !ratioChanged) return false;

    (titleObj as any).__manualTextWidth = nextWidth;
    if (nextRatio !== null) {
        (titleObj as any).__manualTextWidthRatio = nextRatio;
    }

    (card as any)._productData = {
        ...baseProductData,
        titleTextWidth: nextWidth,
        titleTextWidthRatio: nextRatio ?? baseProductData.titleTextWidthRatio
    };
    return true;
}

const applyGlobalStylePropToCardFast = (
    card: any,
    prop: string,
    styles: GlobalStyles
) => getEditorProductGridController().applyGlobalStylePropToCardFast(card, prop, styles);

const applyGlobalStylesToCards = (
    styles: Partial<GlobalStyles>,
    zone?: any,
    opts: { prop?: string; cards?: any[] } = {}
) => getEditorProductGridController().applyGlobalStylesToCards(styles, zone, opts);

const handleApplyZonePreset = async (presetId: string) => {
    if (!canvas.value) return;

    // Resolve the target zone before mutating reactive state. If we lose the zone here,
    // updating only the singleton composable makes the UI look changed while the canvas stays stale.
    const active = resolveZoneTargetsForUpdates({ allowAllFallback: false })[0] || getCurrentZoneObject();
    if (!active) {
        console.warn('⚠️ [handleApplyZonePreset] No zone resolved; skipping preset to avoid partial apply');
        return;
    }

    // FIX: Permanently disable Fabric v7 LayoutManager on the zone group.
    // Any prior call to triggerLayout() (e.g. from ensureZoneSanity, or Fabric internal set())
    // can recalculate the group's bounding box from ALL children, shifting the group center.
    // Since zone layout is fully managed by recalculateZoneLayout, auto-layout only corrupts positions.
    const zoneLm = (active as any).layoutManager;
    if (zoneLm && typeof zoneLm.performLayout === 'function' && zoneLm.performLayout.toString() !== '() => {}') {
        zoneLm.performLayout = () => {};
    }

    // FIX: Suppress global style updates during preset application.
    // When applyPreset() updates the composable state, Vue reactivity can cause
    // ProductZoneSettings to re-emit update-global-styles events, which triggers
    // applyGlobalStylesToCards with __forceCardRelayout — corrupting the layout before
    // our intended relayout even runs.
    _suppressGlobalStyleUpdates = true;

    try {
        // Now update composable state
        productZoneState.applyPreset(presetId);

        // CRITICAL FIX: Clear cached signatures and manual transform flags on ALL cards
        // before applying the new preset. Without this:
        // 1. __lastCardRelayoutSignature may match (if only grid changed but styles didn't),
        //    causing resizeSmartObject to skip child repositioning entirely
        // 2. __manualTransform / __preserveManualLayout on children prevents resizeSmartObject
        //    from moving price/splash elements to new positions for the new slot dimensions
        // 3. __priceLayoutSnapshot captures positions from the OLD card size, corrupting layout
        try {
            const presetCards = getZoneChildren(active);
            presetCards.forEach((card: any) => {
                card.__forceCardRelayout = true;
                card.__lastCardRelayoutSignature = null;
                card.__lastCardRelayoutAt = 0;
                // FIX: Also reset the card's LayoutManager to prevent Fabric v7
                // from auto-recalculating group bounds during resizeSmartObject
                const cardLm = (card as any).layoutManager;
                if (cardLm && typeof cardLm.performLayout === 'function') {
                    cardLm.performLayout = () => {};
                }
                if (typeof card.getObjects === 'function') {
                    card.getObjects().forEach((child: any) => {
                        if (child) {
                            child.__manualTransform = false;
                            child.__preserveManualLayout = false;
                            child.__priceLayoutSnapshot = null;
                            child.__priceLayoutSnapshotAt = null;
                        }
                    });
                }
            });
        } catch (e) {
            console.warn('[handleApplyZonePreset] Failed to clear card flags:', e);
        }

        const z = productZoneState.productZone.value;
        await applyZoneUpdates(active, {
            role: z.role ?? 'grid',
            padding: z.padding ?? 15,
            gapHorizontal: z.gapHorizontal ?? z.padding ?? 15,
            gapVertical: z.gapVertical ?? z.padding ?? 15,
            columns: z.columns ?? 0,
            rows: z.rows ?? 0,
            layoutDirection: z.layoutDirection ?? 'horizontal',
            cardAspectRatio: z.cardAspectRatio ?? 'fill',
            lastRowBehavior: z.lastRowBehavior ?? 'fill',
            verticalAlign: z.verticalAlign ?? 'stretch',
            highlightCount: z.highlightCount ?? 0,
            highlightPos: z.highlightPos ?? 'first',
            highlightSelection: z.highlightSelection ?? z.highlightPos ?? 'first',
            highlightIndexes: z.highlightIndexes ?? [1],
            highlightHeight: z.highlightHeight ?? 1.5,
            // CORRECAO: highlightStyle e overflowPolicy faziam parte do preset mas
            // nao eram propagados. Ao trocar preset, a zona ficava com estilo de
            // destaque stale do preset anterior.
            highlightStyle: z.highlightStyle ?? 'larger',
            overflowPolicy: z.overflowPolicy ?? 'warn'
        }, { saveReason: 'preset-change' });
    } finally {
        // FIX: Restore global style updates after preset application is complete.
        // Use requestAnimationFrame to ensure it happens AFTER any pending Vue reactivity
        // and the post-relayout viewport culling pass.
        requestAnimationFrame(() => {
            nextTick(() => {
                _suppressGlobalStyleUpdates = false;
            });
        });
    }
};

const handleSyncZoneGaps = async (padding: number, meta?: ZoneUpdateTargetMeta) => {
    const active = resolveZoneTargetsForUpdates({ allowAllFallback: false, targetId: meta?.targetId })[0] || (!meta?.targetId ? getCurrentZoneObject() : null);
    if (!active) {
        console.warn('⚠️ [handleSyncZoneGaps] No zone resolved; skipping sync to avoid UI/canvas divergence');
        return;
    }
    productZoneState.syncGapsWithPadding(padding);
    if (!canvas.value) return;
    const z = productZoneState.productZone.value;
    await applyZoneUpdates(active, {
        padding: z.padding,
        gapHorizontal: z.gapHorizontal ?? z.padding,
        gapVertical: z.gapVertical ?? z.padding
    });
};

// ALLOW_UNDEFINED_GLOBAL_STYLE_PROPS extraido para utils/globalStylePropClassifiers.ts.
// resolveGlobalStyleUpdatePayload extraido para utils/zoneUpdatesPayload.ts (renomeado para resolveScalarUpdatePayload).
const resolveGlobalStyleUpdatePayload = resolveScalarUpdatePayload;

const handleUpdateGlobalStyles = async (propOrPayload: string | Record<string, any>, val?: any, meta?: ZoneUpdateTargetMeta) => {
    if (!canvas.value) return;
    // CRITICAL FIX: Suppress style updates during page load / composable sync.
    // When rehydrateCanvasZones syncs composable state, ProductZoneSettings emits
    // update-global-styles back, which triggers applyGlobalStylesToCards with __forceCardRelayout=true.
    // This forces full relayout of all cards, destroying the saved internal layout (text sizes, positions).
    if (_suppressGlobalStyleUpdates) {
        return;
    }
    const parsed = resolveGlobalStyleUpdatePayload(propOrPayload, val);
    if (!parsed) {
        console.warn('⚠️ [handleUpdateGlobalStyles] Invalid payload received:', propOrPayload);
        return;
    }

    const prop = parsed.prop;
    const value = parsed.value;
    if (value === undefined && !ALLOW_UNDEFINED_GLOBAL_STYLE_PROPS.has(prop)) {
        console.warn(`⚠️ [handleUpdateGlobalStyles] Ignoring undefined value for "${prop}" to avoid unintended resets.`);
        return;
    }

    const perfStart = getEditorPerfNow();

    // Gather ALL zones in canvas first (for fallback).
    const allZones = getRuntimeProductZones();

    const targets = resolveZoneTargetsForUpdates({ allowAllFallback: false, targetId: meta?.targetId });
    const primaryZone = targets[0];

    // If no zone found but a card is selected, try to find its parent zone
    let zone = primaryZone;
    if (!zone && !meta?.targetId && selectedObjectRef.value && isLikelyProductCard(selectedObjectRef.value)) {
        const parentZoneId = selectedObjectRef.value.parentZoneId;
        if (parentZoneId) {
            zone = findProductZoneById(parentZoneId);
        }
    }

    // Reload safety: if a zone snapshot is selected but Fabric lost activeObject,
    // resolve the real zone directly by _customId.
    if (!zone && !meta?.targetId && selectedObjectRef.value?._customId) {
        const selectedId = String(selectedObjectRef.value._customId).trim();
        if (selectedId) {
            zone = findProductZoneById(selectedId);
        }
    }

    // Last deterministic fallback: pick the single zone if there's only one.
    if (!zone && !meta?.targetId && allZones.length === 1) {
        zone = allZones[0];
    }

    // Keep composable synchronized with EFFECTIVE styles (defaults + zone overrides),
    // so controls always operate on a complete style object.
    const baseStylesForState = zone
        ? getZoneGlobalStyles(zone)
        : normalizeGlobalStyles(productZoneState.globalStyles.value);
    const colorPatch = ['productPalette', 'templateProductPalette'].includes(prop) ? { cardColorMode: 'auto' as const, isProdBgTransparent: false } : prop === 'highlightCardColor' && baseStylesForState.templateProductPalette ? { productPalette: { ...baseStylesForState.productPalette, highlightCardColor: value } } : prop === 'cardColor' ? { cardColorMode: 'manual' as const } : prop === 'cardColorMode' && value === 'auto' ? { highlightCardColor: findFlyerAccent(canvas.value.getObjects()) || '#ffffff', isProdBgTransparent: false } : {}
    const nextStylesForState = normalizeGlobalStyles({ ...baseStylesForState, ...colorPatch, [prop]: value });
    productZoneState.updateGlobalStyles(nextStylesForState);

    // Persist styles on the zone so they survive undo/redo and reload.
    const effectiveTargets = targets.length > 0
        ? targets
        : (zone ? [zone] : []);
    const previousZoneStylesByTarget = new Map<any, GlobalStyles>();

    if (effectiveTargets.length > 0) {
        effectiveTargets.forEach((z: any) => {
            const prev = getZoneGlobalStyles(z);
            previousZoneStylesByTarget.set(z, prev);
            (z as any)._zoneGlobalStyles = normalizeGlobalStyles({ ...prev, ...colorPatch, [prop]: value });
            // "Ultima edicao vence": edicao explicita pelo painel marca override,
            // que sobrevive a (re)aplicacao de template / swap / refresh.
            markZoneStyleOverride(z, prop);
        });
    }

    const isTemplateChange = prop === 'splashTemplateId';
    let totalFullRelayout = 0;

    if (effectiveTargets.length > 0) {
        if (isTemplateChange) {
            let templateApplyFailed = false;
            for (const z of effectiveTargets) {
                // Keep UI and canvas consistent: when the user picks a template,
                // apply it to existing cards in the zone as well.
                const applied = await applyLabelTemplateToZone(z, value, {
                    applyToExisting: true,
                    forceCardTemplate: true
                });
                if (!applied) templateApplyFailed = true;
            }
            if (templateApplyFailed) {
                productZoneState.globalStyles.value = normalizeGlobalStyles(baseStylesForState);
                effectiveTargets.forEach((z: any) => {
                    const prev = previousZoneStylesByTarget.get(z);
                    if (prev) (z as any)._zoneGlobalStyles = normalizeGlobalStyles(prev);
                });
                refreshSelectedRef();
                return;
            }
        } else {
            let totalCardsTouched = 0;
            let totalFastApplied = 0;
            effectiveTargets.forEach((z: any) => {
                const zStyles = getZoneGlobalStyles(z);
                if (['cardColorMode', 'highlightCardColor', 'templateProductPalette', 'productPalette'].includes(prop)) {
                    const colorCards = getZoneChildren(z) || []
                    const colorHighlight = getZoneHighlightPredicate(z, colorCards)
                    colorCards.forEach((card: any, index: number) => { card._cardHighlighted = colorHighlight.isHighlighted(card, index) })
                }
                // Nao sobrescrever cards com override proprio desta prop ("editar so
                // este card" vence a zona). Demais cards recebem o estilo da zona.
                const zoneCards = getZoneChildren(z) || [];
                const overridden = zoneCards.filter((c: any) => cardHasStyleOverride(c, prop));
                const cardsForZoneApply = overridden.length
                    ? zoneCards.filter((c: any) => !cardHasStyleOverride(c, prop))
                    : undefined;
                if (overridden.length && !cardsForZoneApply!.length) return; // todos com override
                const stats = applyGlobalStylesToCards(zStyles, z, cardsForZoneApply ? { prop, cards: cardsForZoneApply } : { prop });
                totalCardsTouched += Number(stats?.cardsTouched || 0);
                totalFastApplied += Number(stats?.fastApplied || 0);
                totalFullRelayout += Number(stats?.fullRelayout || 0);
            });
            if (import.meta.dev) {
                const perfEnd = getEditorPerfNow();
                const elapsedMs = Math.max(0, perfEnd - perfStart);
                console.log('[perf:global-styles]', {
                    prop,
                    zones: effectiveTargets.length,
                    cardsTouched: totalCardsTouched,
                    fastApplied: totalFastApplied,
                    fullRelayout: totalFullRelayout,
                    elapsedMs: Number(elapsedMs.toFixed(2))
                });
            }
        }
    } else {
        console.warn('⚠️ [handleUpdateGlobalStyles] No target zone resolved; skipping apply to avoid cross-zone pollution');
        return;
    }

    // FIX: Somente re-grid quando resizeSmartObject rodou (fullRelayout > 0).
    // Para props lightweight (cor, fonte, etc.), o fast path altera apenas propriedades
    // visuais sem tocar dimensões — re-grid é desnecessário e reposiciona cards,
    // destruindo posições manuais ou salvas.
    if (!isTemplateChange && totalFullRelayout > 0) {
        effectiveTargets.forEach((z: any) => {
            try {
                const zCards = getZoneChildren(z);
                if (zCards.length > 0) {
                    // preserveStyles: reposiciona cards no grid correto e redimensiona se necessário,
                    // sem reaplicar estilos globais (já foram aplicados acima).
                    recalculateZoneLayout(z, zCards, { save: false, requestRender: false, preserveStyles: true });
                }
            } catch (e) {
                console.warn('[handleUpdateGlobalStyles] Re-grid failed:', e);
            }
        });
    }

    // CRITICAL: Force aggressive re-render. After loadFromJSON, Fabric v7 groups
    // may cache stale renders. Clearing renderCache on all affected cards ensures
    // the new styles are visually applied.
    // Template updates already request render internally via applyLabelTemplateToZone.
    if (!isTemplateChange) {
        safeRequestRenderAll();
    }
    if (!isTemplateChange && !isDebouncedGlobalStyleProp(prop)) {
        nextTick(() => {
            if (canvas.value) {
                // Force dirty on entire canvas to guarantee re-render
                canvas.value.getObjects().forEach((o: any) => {
                    if (o?.isSmartObject || o?.isProductCard) {
                        o.dirty = true;
                        if (typeof o.getObjects === 'function') {
                            (o.getObjects() || []).forEach((child: any) => {
                                if (child) child.dirty = true;
                            });
                        }
                    }
                });
                safeRequestRenderAll();
            }
        });
    }
    scheduleGlobalStylesStateSave(prop);
    refreshSelectedRef();
};

const handleApplyTemplateToZone = async () => {
    const zone = getCurrentZoneObject();
    if (!zone) return;

    const templateId = (zone as any)._zoneGlobalStyles?.splashTemplateId;
    if (!templateId) {
        return;
    }

    await applyLabelTemplateToZone(zone, templateId, {
        applyToExisting: true,
        forceCardTemplate: true
    });
    refreshSelectedRef();
};

// collectObjectsDeep / findByName / isTextLikeObject foram extraidos para
// utils/fabricObjectClassifiers.ts (Fase 2 da modularizacao).

// parsePriceToCents / formatCentsToPrice / splitPriceParts /
// resolveAtacVariantKeyFromPrice + tipo AtacVariantKey foram extraidos
// para utils/priceTagText.ts (Fase 2 da modularizacao). Reexport local
// do tipo mantem compat com o codigo abaixo.
type AtacVariantKey = import('~/utils/priceTagText').AtacVariantKey;

// parsePriceBR / normalizeUnitForLabel / PRICE_INTEGER_DECIMAL_GAP_PX
// foram extraidos para utils/priceTagText.ts (Fase 2 da modularizacao).
// Mantemos PriceUnitLabel reexportado localmente para compatibilidade com
// os tipos ja referenciados ao longo deste arquivo.
