layoutPriceGroup = priceGroupLayout.layoutPriceGroup
layoutAtacarejoPriceGroup = priceGroupLayout.layoutAtacarejoPriceGroup

// Builders de etiquetas ficam fora deste SFC para evitar concentrar todo o
// codigo de seeds no chunk principal do editor. O Fabric continua sendo
// resolvido em runtime, depois do import dinamico usado pelo canvas.
const priceGroupBuilders = createPriceGroupBuilders({
    fabric: () => fabric,
    layoutPriceGroup,
    applyAtacarejoPricingToPriceGroup,
    safeAddWithUpdate
})
buildDefaultPriceGroupForCard = priceGroupBuilders.buildDefaultPriceGroupForCard
buildBlackYellowPriceGroupForCard = priceGroupBuilders.buildBlackYellowPriceGroupForCard
buildOfertaAmarelaPriceGroupForCard = priceGroupBuilders.buildOfertaAmarelaPriceGroupForCard
buildBarlowBlackPriceGroupForCard = priceGroupBuilders.buildBarlowBlackPriceGroupForCard
buildRedBurstPriceGroupForCard = priceGroupBuilders.buildRedBurstPriceGroupForCard
buildAtacarejoPriceGroupForCard = priceGroupBuilders.buildAtacarejoPriceGroupForCard

// getPriceGroupFromAny + getCardGroupFromAny extraidos para
// utils/priceLayoutClassifiers.ts.

const enlivenObjectsAsync = (objectsJson: any[]) => {
    if (!fabric?.util?.enlivenObjects) return Promise.resolve([]);
    const fn = fabric.util.enlivenObjects;
    try {
        const maybe = fn(objectsJson);
        if (maybe && typeof maybe.then === 'function') return maybe;
    } catch (_) {
        // fall back to callback form below
    }
    return new Promise<any[]>((resolve, reject) => {
        try {
            fn(objectsJson, (enlivened: any[]) => resolve(enlivened));
        } catch (err) {
            reject(err);
        }
    });
};

// seedManualTemplateOriginalMetrics extraido para utils/templateSnapshotHelpers.ts.

// collectTemplateJsonNodes / isTemplateGroupJsonRenderable /
// isAtacarejoTemplateGroupJson / isRedBurstTemplateGroupJson foram
// extraidos para utils/canvasJsonClassifiers.ts.

// pickRenderableTemplateGroupJson extraido para utils/templateSnapshotHelpers.ts.
// Wrapper local injeta isTemplateGroupJsonRenderable + shouldUseAtacVariantSnapshotsForTemplate.
const pickRenderableTemplateGroupJson = (tpl: LabelTemplate, preferredVariantKey?: AtacVariantKey) =>
    pickRenderableTemplateGroupJsonHelper(
        tpl,
        preferredVariantKey,
        isTemplateGroupJsonRenderable,
        shouldUseAtacVariantSnapshotsForTemplate
    )

// templateSnapshotHasAtacStructure, shouldForceCanonicalAtacForTemplateJson e
// shouldUseAtacVariantSnapshotsForTemplate extraidos para
// utils/templateSnapshotHelpers.ts.

async function instantiatePriceGroupFromTemplate(tpl: LabelTemplate, opts?: { atacVariantKey?: AtacVariantKey }): Promise<any> {
    const preferredVariantKey = opts?.atacVariantKey;
    const baseGroupJson: any = tpl?.group;
    // BUG #13 FIX: clonar o JSON para evitar que múltiplas instâncias compartilhem o mesmo objeto
    const rawGroupJson: any = pickRenderableTemplateGroupJson(tpl, preferredVariantKey);
    const groupJson: any = cloneTemplateGroupJson(rawGroupJson) ?? rawGroupJson;
    sanitizeRedBurstTemplateGroupJson(baseGroupJson);
    if (groupJson && groupJson !== baseGroupJson) sanitizeRedBurstTemplateGroupJson(groupJson);
    if (!fabric || !groupJson) throw new Error('Template missing group JSON');
    const objectsJson = Array.isArray(groupJson.objects) ? groupJson.objects : [];
    if (objectsJson.length === 0) throw new Error('Template group JSON has no objects');
    // DEBUG: Log template JSON names to verify they exist in the source data
    const jsonNames = objectsJson.map((o: any) => `${o?.name || '(sem nome)'}[${o?.type || '?'}]`);
    if (import.meta.dev) console.log('[instantiatePriceGroupFromTemplate] JSON objectsJson names:', jsonNames.join(', '));
    const groupOpts = { ...groupJson };
    delete (groupOpts as any).objects;
    // Fabric objects have a fixed `type` based on the class; restoring `type` from JSON is ignored and warns.
    delete (groupOpts as any).type;
    // Never restore layoutManager from plain JSON (Fabric v7 expects class instance).
    delete (groupOpts as any).layoutManager;
    delete (groupOpts as any).layout;
    let enlivened: any[];
    try {
        enlivened = await enlivenObjectsAsync(objectsJson);
    } catch (enlivenErr: any) {
        // Fontes inválidas ou objetos corrompidos podem causar falha no enliven
        console.error('[instantiatePriceGroupFromTemplate] Falha ao reconstruir objetos do template (possível fonte inválida):', enlivenErr?.message || enlivenErr);
        throw new Error(`Falha ao reconstruir objetos do template: ${enlivenErr?.message || 'erro desconhecido'}`);
    }
    if (!Array.isArray(enlivened) || enlivened.length === 0) throw new Error('Template group failed to enliven objects');

    // FIX: Fabric v7 enlivenObjects does NOT restore `name` and custom props on children.
    // Re-apply them from the original JSON so setPriceOnPriceGroup can find named text fields.
    // restoreNamesFromJson extraido para utils/canvasJsonClassifiers.ts.
    restoreNamesFromJson(enlivened, objectsJson);

    const g = new fabric.Group(enlivened, groupOpts);
    migratePriceGroupToRichText(g, fabric);
    const cloneSafe = <T>(value: T): T => {
        try {
            return typeof structuredClone === 'function'
                ? structuredClone(value)
                : JSON.parse(JSON.stringify(value));
        } catch {
            return value;
        }
    };
    // IMPORTANT: Any label template coming from the template system must preserve
    // the geometry authored in Mini Editor. Automatic reflow is only for legacy/default
    // programmatic groups, not for user template instances.
    const preserveManualLayout = typeof (groupOpts as any).__preserveManualLayout === 'boolean'
        ? !!(groupOpts as any).__preserveManualLayout
        : true;
    // Ensure templates always start from a normalized transform.
    g.set({ name: 'priceGroup', originX: 'center', originY: 'center', left: 0, top: 0, scaleX: 1, scaleY: 1, angle: 0 });
    ensureObjectPersistentId(g);
    collectObjectsDeep(g).forEach((node: any) => {
        if (!node || node === g) return;
        ensureObjectPersistentId(node);
    });
    (g as any).__preserveManualLayout = preserveManualLayout;
    (g as any).__isCustomTemplate = true;
    // Keep Atacarejo templates on canonical layout across all value variants.
    (g as any).__forceAtacarejoCanonical = shouldForceCanonicalAtacForTemplateJson(baseGroupJson);
    const useVariantSnapshots = shouldUseAtacVariantSnapshotsForTemplate(baseGroupJson);
    if (baseGroupJson && typeof baseGroupJson === 'object') {
        const rehydrateKeys = [
            ...MANUAL_TEMPLATE_STABLE_PROPS,
            '__autoCollapseMissingPrices',
            '__atacarejoPalette',
            '__atacarejoLabelVariant',
            '__atacDisplayUnit',
            '__atacPackLineCompact',
            '__atacConditionFormat'
        ] as const;
        for (const key of rehydrateKeys) {
            if (key in (baseGroupJson as any)) {
                (g as any)[key] = cloneSafe((baseGroupJson as any)[key]);
            }
        }
        if (typeof (baseGroupJson as any).__atacValueVariants === 'object') {
            (g as any).__atacValueVariants = cloneSafe((baseGroupJson as any).__atacValueVariants);
        }
        if (useVariantSnapshots && typeof (baseGroupJson as any).__atacVariantGroups === 'object') {
            (g as any).__atacVariantGroups = cloneSafe((baseGroupJson as any).__atacVariantGroups);
        } else {
            (g as any).__atacVariantGroups = {};
        }
    }
    MANUAL_TEMPLATE_DERIVED_PROPS.forEach((key) => {
        try { delete (g as any)[key]; } catch { /* ignore */ }
    });
    ensureSinglePriceCurrencyCircleAnchor(g);
    ensureRedBurstPriceGroupVisibility(g);
    const repairedCollapsedGeometry = repairCollapsedSinglePriceTemplateGeometry(
        g,
        `instantiate:${String(tpl?.id || tpl?.name || 'template')}`
    );
    if (preserveManualLayout) seedManualTemplateOriginalMetrics(g);
    if (repairedCollapsedGeometry && tpl && typeof tpl === 'object') {
        const repairedJson = serializePriceGroupForTemplate(g);
        if (repairedJson) {
            (tpl as any).group = repairedJson;
            const tplId = String((tpl as any)?.id || '').trim();
            if (tplId && !autoHealedLabelTemplateIds.has(tplId)) {
                autoHealedLabelTemplateIds.add(tplId);
                queueMicrotask(async () => {
                    try {
                        (tpl as any).updatedAt = new Date().toISOString();
                        (tpl as any).previewDataUrl = await renderLabelTemplatePreview(tpl as any);
                        await upsertLabelTemplateToDb(tpl as any);
                    } catch (err) {
                        console.warn('[labelTemplates] Falha ao persistir template auto-recuperado', err);
                    }
                });
            }
        }
    }
    return g;
}

function normalizePriceGroupForPreview(pg: any) {
    if (!pg || typeof pg.getObjects !== 'function') return;
    pg.set({ originX: 'center', originY: 'center', left: 0, top: 0, scaleX: 1, scaleY: 1, angle: 0 });

    const all: any[] = pg.getObjects();

    // ===== ATACAREJO TEMPLATE SUPPORT =====
    // Check if this is an atacarejo (2-price) template by looking for the retail background
    const retailBg = all.find(o => o?.name === 'atac_retail_bg');
    const isAtacarejo = !!retailBg;

    if (isAtacarejo) {
        // Keep preview exactly aligned with runtime layout.
        layoutAtacarejoPriceGroup(pg, 320, 450);
        safeAddWithUpdate(pg);
        return;
    }

    // ===== STANDARD SINGLE-PRICE TEMPLATE =====
    const priceBg = all.find(o => o?.name === 'price_bg');
    const priceBgImage = all.find(o => o?.name === 'price_bg_image' || o?.name === 'splash_image');
    const currencyText = getSinglePriceCurrencyTextCandidate(all);
    const currencyCircle = ensureSinglePriceCurrencyCircleAnchor(pg, all);
    const priceText = all.find(o => o?.name === 'smart_price' || o?.name === 'price_value_text');
    const priceInteger = all.find(o => o?.name === 'price_integer_text' || o?.name === 'priceInteger');
    const priceDecimal = all.find(o => o?.name === 'price_decimal_text' || o?.name === 'priceDecimal');
    const priceUnit = all.find(o => o?.name === 'price_unit_text' || o?.name === 'priceUnit');

    // Drop legacy duplicates that inflate bounds (causes tiny/offset previews).
    const recognized = new Set<any>([
        priceBg,
        priceBgImage,
        currencyCircle,
        currencyText,
        priceText,
        priceInteger,
        priceDecimal,
        priceUnit
    ]);
    const cleanupNames = new Set([
        'priceSymbol',
        'price_currency',
        'price_currency_text',
        'priceInteger',
        'priceDecimal',
        'priceUnit',
        'smart_price',
        'price_value_text'
    ]);
    all.forEach((o) => {
        if (!o || recognized.has(o)) return;
        if (!cleanupNames.has(String(o.name || ''))) return;
        pg.remove(o);
    });

    // If there's a splash image, crop it so its real bounds match the pill.
    if (priceBgImage && priceBg && priceBgImage.type === 'image' && priceBg.type === 'rect') {
        const img: any = priceBgImage;
        const pillW = priceBg.width || 1;
        const pillH = priceBg.height || 1;
        img.set({ originX: 'center', originY: 'center', left: 0, top: 0 });

        const el: any = img._originalElement || img._element;
        const iw = el?.naturalWidth || el?.width || img.width || 0;
        const ih = el?.naturalHeight || el?.height || img.height || 0;
        if (iw > 0 && ih > 0) {
            const visibleBounds = detectImageTrimBounds(img, { alphaThreshold: 12, padding: 0 });
            const sourceLeft = Math.max(0, Number(visibleBounds?.left || 0));
            const sourceTop = Math.max(0, Number(visibleBounds?.top || 0));
            const sourceW = Math.max(1, Number(visibleBounds?.width || iw));
            const sourceH = Math.max(1, Number(visibleBounds?.height || ih));
            let scale = Math.max(pillW / sourceW, pillH / sourceH);
            if (!Number.isFinite(scale) || scale <= 0) scale = 1;
            scale = Math.min(scale, 20);
            const cropW = Math.min(sourceW, pillW / scale);
            const cropH = Math.min(sourceH, pillH / scale);
            const cropX = sourceLeft + Math.max(0, (sourceW - cropW) / 2);
            const cropY = sourceTop + Math.max(0, (sourceH - cropH) / 2);
            img.set({ cropX, cropY, width: cropW, height: cropH, scaleX: scale, scaleY: scale });
        } else {
            img.set({ cropX: 0, cropY: 0, width: pillW, height: pillH, scaleX: 1, scaleY: 1 });
        }
    }

    safeAddWithUpdate(pg);
}

function serializePriceGroupForTemplate(pg: any) {
    if (!pg || typeof pg.toObject !== 'function') return null;
    ensureRedBurstPriceGroupVisibility(pg);
    repairCollapsedSinglePriceTemplateGeometry(pg, 'serialize-template');
    ensureObjectPersistentId(pg);
    collectObjectsDeep(pg).forEach((node: any) => {
        if (!node || node === pg) return;
        ensureObjectPersistentId(node);
    });

    const prev = {
        left: pg.left,
        top: pg.top,
        scaleX: pg.scaleX,
        scaleY: pg.scaleY,
        angle: pg.angle,
        originX: pg.originX,
        originY: pg.originY
    };

    // Normalize so saved templates are position/scale-independent.
    pg.set({ left: 0, top: 0, scaleX: 1, scaleY: 1, angle: 0, originX: 'center', originY: 'center' });
    safeAddWithUpdate(pg);
    const j: any = pg.toObject(LABEL_TEMPLATE_EXTRA_PROPS);
    const useVariantSnapshots = shouldUseAtacVariantSnapshotsForTemplate(pg);
    // Deep clone para impedir que templates serializados compartilhem por
    // referencia as estruturas aninhadas com a etiqueta original. Sem isso,
    // editar variantes em uma zona duplicada/template salvo alterava o objeto
    // vivo da etiqueta no canvas (e vice-versa).
    const safeDeepClone = (value: any): any => {
        if (value === null || typeof value !== 'object') return value;
        try { return JSON.parse(JSON.stringify(value)); } catch { return value; }
    };
    if (typeof (pg as any).__atacValueVariants === 'object' && (pg as any).__atacValueVariants !== null) {
        j.__atacValueVariants = safeDeepClone((pg as any).__atacValueVariants);
    }
    [
        '__autoCollapseMissingPrices',
        '__atacarejoPalette',
        '__atacarejoLabelVariant',
        '__atacDisplayUnit',
        '__atacPackLineCompact',
        '__atacConditionFormat'
    ].forEach((key) => {
        if (key in (pg as any)) j[key] = safeDeepClone((pg as any)[key]);
    });
    if (useVariantSnapshots && typeof (pg as any).__atacVariantGroups === 'object' && (pg as any).__atacVariantGroups !== null) {
        j.__atacVariantGroups = safeDeepClone((pg as any).__atacVariantGroups);
    } else {
        delete j.__atacVariantGroups;
    }
    MANUAL_TEMPLATE_DERIVED_PROPS.forEach((key) => {
        delete j[key];
    });
    pg.set(prev);
    safeAddWithUpdate(pg);
    delete j.layoutManager;
    delete j.layout;

    // Mark this as a custom template and store original dimensions for proportional scaling
    (j as any).__isCustomTemplate = true;

    // Store original values on each object for proportional scaling
    collectTemplateJsonNodesDeep(j).forEach((obj: any) => {
        if (!obj || obj === j) return;

        // Store original position
        obj.__originalLeft = obj.left;
        obj.__originalTop = obj.top;
        obj.__originalOriginX = obj.originX;
        obj.__originalOriginY = obj.originY;
        obj.__originalScaleX = obj.scaleX || 1;
        obj.__originalScaleY = obj.scaleY || 1;

        // For text objects, store original font size and font family
        if (isTextLikeObject(obj)) {
            if (typeof obj.fontSize === 'number') {
                obj.__originalFontSize = obj.fontSize;
            }
            if (typeof obj.fontFamily === 'string') {
                obj.__originalFontFamily = obj.fontFamily;
            }
            if (typeof obj.width === 'number') {
                obj.__originalWidth = obj.width;
            }
            if (typeof obj.height === 'number') {
                obj.__originalHeight = obj.height;
            }
        }

        // For circles, store original radius
        if (obj.type === 'circle' && typeof obj.radius === 'number') {
            obj.__originalRadius = obj.radius;
        }

        // For rects, store original dimensions and radius
        if (obj.type === 'rect') {
            if (typeof obj.width === 'number') obj.__originalWidth = obj.width;
            if (typeof obj.height === 'number') obj.__originalHeight = obj.height;
            if (typeof obj.rx === 'number') obj.__originalRx = obj.rx;
            if (typeof obj.ry === 'number') obj.__originalRy = obj.ry;

            // For price_bg, store special metadata
            if (obj.name === 'price_bg') {
                obj.__originalWidth = obj.width;
                obj.__originalHeight = obj.height;
                obj.__roundness = typeof obj.rx === 'number' && obj.height > 0
                    ? (obj.rx * 2) / obj.height
                    : 1;
                if (typeof obj.strokeWidth === 'number') {
                    obj.__strokeWidth = obj.strokeWidth;
                }
                if (obj.shadow && typeof obj.shadow.blur === 'number') {
                    obj.__shadowBlur = obj.shadow.blur;
                }
                // Preservar fill original para restaurar após ciclo splash/transparent
                if (typeof obj.fill === 'string' && obj.fill !== 'transparent') {
                    obj.__originalFill = obj.fill;
                }
            }
        }

        // Store original stroke width
        if (typeof obj.strokeWidth === 'number') {
            obj.__originalStrokeWidth = obj.strokeWidth;
        }
    });

    return j;
}

function setPriceOnPriceGroup(pg: any, rawPrice: string, unitText?: string) {
    if (!pg || typeof pg.getObjects !== 'function') return;
    migratePriceGroupToRichText(pg, fabric);
    const parts = collectObjectsDeep(pg);
    const preserveTemplateVisual = shouldPreserveManualTemplateVisual(pg);
    const requestedUnit = normalizeUnitForLabel(unitText);

    // DEBUG: Log all named objects in the price group for diagnosis
    const allNames = parts.map((o: any) => `${o?.name || '(sem nome)'}[${String(o?.type || '?').toLowerCase()}]`);
    if (import.meta.dev) console.log('[setPriceOnPriceGroup] rawPrice:', rawPrice, '| total parts:', parts.length, '| names:', allNames.join(', '));

    const isVisibleNode = (obj: any): boolean => {
        if (!obj) return false;
        if (obj.visible === false) return false;
        const sx = Number(obj.scaleX ?? 1);
        const sy = Number(obj.scaleY ?? 1);
        if (!Number.isFinite(sx) || !Number.isFinite(sy)) return true;
        return sx !== 0 && sy !== 0;
    };

    const currency = parts.find((o: any) => o?.name === 'price_currency_text');
    if (currency && (!currency.text || String(currency.text).trim().length === 0)) currency.set?.('text', 'R$');

    const richPriceTxt = parts.find((o: any) => isRichPriceTextObject(o));
    let intTxt = parts.find((o: any) => o?.name === 'price_integer_text' || o?.name === 'priceInteger' || o?.name === 'price_integer');
    let decTxt = parts.find((o: any) => o?.name === 'price_decimal_text' || o?.name === 'priceDecimal' || o?.name === 'price_decimal');
    let unitTxt = parts.find((o: any) => o?.name === 'price_unit_text' || o?.name === 'priceUnit' || o?.name === 'price_unit');
    let legacy = parts.find((o: any) => (o?.name === 'smart_price' || o?.name === 'price_value_text') && !isRichPriceTextObject(o));

    // FIX: Fabric v7 enlivenObjects drops `name` from children.
    // When no named fields are found, identify price text objects by their content pattern.
    if (!intTxt && !decTxt && !legacy && !richPriceTxt) {
        const textParts = parts.filter((o: any) => {
            const t = String(o?.type || '').toLowerCase();
            return (t === 'i-text' || t === 'text' || t === 'textbox') && o?.visible !== false;
        });
        for (const obj of textParts) {
            const txt = String(obj?.text || '').trim();
            // Currency text (R$, $)
            if (!currency && /^R?\$$/i.test(txt)) {
                if (!obj.name) obj.name = 'price_currency_text';
                continue;
            }
            // Decimal part: starts with comma followed by digits (e.g. ",99")
            if (!decTxt && /^,\d{1,2}$/.test(txt)) {
                decTxt = obj;
                obj.name = 'price_decimal_text';
                continue;
            }
            // Integer part: pure digits (e.g. "10", "34")
            if (!intTxt && /^\d{1,4}$/.test(txt)) {
                intTxt = obj;
                obj.name = 'price_integer_text';
                continue;
            }
            // Unit text: short label like "UN", "KG", "CADA", "PCT" or
            // "CX". Inclui aliases comuns para templates antigos sem nome.
            if (!unitTxt && /^[\/]?(?:UN[D.]?|KG|CADA|LT|ML|G|GR|PCT|PCTE|PAC(?:OTE|OTES)?|CX|CAIXA(?:S)?|FD|FARDO(?:S)?|DZ|DUZIA(?:S)?|BD|BANDEJA(?:S)?|SC|SACO(?:S)?|EMB)\.?$/i.test(txt)) {
                unitTxt = obj;
                obj.name = 'price_unit_text';
                continue;
            }
            // Legacy full price: "10,99" or "R$ 10,99"
            if (!legacy && /^\d{1,4}[,.]\d{1,2}$/.test(txt.replace(/R\$\s*/g, ''))) {
                legacy = obj;
                obj.name = 'smart_price';
                continue;
            }
        }
        if (intTxt || decTxt || legacy) {
            if (import.meta.dev) console.log('[setPriceOnPriceGroup] Fallback por conteudo: intTxt:', !!intTxt, '| decTxt:', !!decTxt, '| legacy:', !!legacy, '| unitTxt:', !!unitTxt);
        }
    }

    const priceParts = splitPriceParts(rawPrice);
    const integer = priceParts.integer;
    const decimalText = `,${priceParts.dec}`;

    if (richPriceTxt) {
        applyRichPriceTextValue(richPriceTxt, rawPrice);
        if (unitTxt) {
            const templateAllowsUnit = unitTxt.visible !== false && String(unitTxt.text || '').trim().length > 0;
            if (templateAllowsUnit && requestedUnit) {
                unitTxt.set?.({ text: requestedUnit, visible: true });
            } else {
                unitTxt.set?.({ text: '', visible: false });
            }
            unitTxt.initDimensions?.();
        }
        richPriceTxt.dirty = true;
        richPriceTxt.setCoords?.();
        if (preserveTemplateVisual) {
            fitManualSinglePriceValuesIntoTemplate(pg);
        }
        return;
    }

    const hasSplitPair = !!(intTxt && decTxt);
    const hasLegacy = !!legacy;
    const splitLooksLikeMainPrice = !!(
        hasSplitPair && (
            isVisibleNode(currency) ||
            !hasLegacy ||
            !isVisibleNode(legacy)
        )
    );

    if (preserveTemplateVisual && hasSplitPair) {
        // Capture the Mini Editor geometry before replacing the text with product values.
        // If we recompute after "1,99" / "1.299,99", the cents anchor inherits the
        // transient text width and the template can be born with exaggerated gaps.
        readSingleManualPriceAnchors(pg) || readSingleManualPriceAnchors(pg, { force: true });
    }

	    if (hasSplitPair && splitLooksLikeMainPrice) {
        intTxt.set?.('text', integer);
        decTxt.set?.('text', decimalText);
        if (typeof intTxt.initDimensions === 'function') intTxt.initDimensions();
        if (typeof decTxt.initDimensions === 'function') decTxt.initDimensions();

        if (unitTxt) {
            // Templates como o Preto/Amarelo deixam o campo de unidade escondido (visible=false).
            // Nesses casos, NAO repovoar a gramatura ao reabrir o projeto — texto fica vazio
            // para impedir que apareca caso algum fluxo de edicao religue a visibilidade.
            const templateAllowsUnit = unitTxt.visible !== false && String(unitTxt.text || '').trim().length > 0;
            if (templateAllowsUnit && requestedUnit) {
                unitTxt.set?.({ text: requestedUnit, visible: true });
            } else {
                unitTxt.set?.({ text: '', visible: false });
            }
            if (typeof unitTxt.initDimensions === 'function') unitTxt.initDimensions();
        }
        // Keep Mini Editor templates visually identical and only fit dynamic values.
        if (preserveTemplateVisual) {
            fitManualSinglePriceValuesIntoTemplate(pg);
        } else {
            expandManualTemplateWidthForDynamicPrice(pg);
        }
        return;
    }

    if (legacy) {
        legacy.set?.('text', `${integer}${decimalText}`);
        if (typeof legacy.initDimensions === 'function') legacy.initDimensions();
	    } else if (hasSplitPair) {
        // Fallback: if no legacy field exists, still update split fields.
        intTxt.set?.('text', integer);
        decTxt.set?.('text', decimalText);
        if (typeof intTxt.initDimensions === 'function') intTxt.initDimensions();
        if (typeof decTxt.initDimensions === 'function') decTxt.initDimensions();
        if (unitTxt) {
            // Mesma regra do caminho split principal: respeita visible=false do template.
            const templateAllowsUnit = unitTxt.visible !== false && String(unitTxt.text || '').trim().length > 0;
            if (templateAllowsUnit && requestedUnit) {
                unitTxt.set?.({ text: requestedUnit, visible: true });
            } else {
                unitTxt.set?.({ text: '', visible: false });
            }
            if (typeof unitTxt.initDimensions === 'function') unitTxt.initDimensions();
        }
    } else {
        console.warn('[setPriceOnPriceGroup] Nenhum campo de preco encontrado no template! rawPrice:', rawPrice, 'parts:', parts.length, 'names:', parts.map((o: any) => o?.name).filter(Boolean));
    }
    // Keep Mini Editor templates visually identical and only fit dynamic values.
    if (preserveTemplateVisual) {
        fitManualSinglePriceValuesIntoTemplate(pg);
    } else {
        expandManualTemplateWidthForDynamicPrice(pg);
    }
}

