const repairLegacyProductCardImageTransforms = (
    cards: any[],
    opts: { verbose?: boolean } = {}
): { cardsScanned: number; imagesScanned: number; imagesRepaired: number } => {
    const verbose = opts.verbose === true;
    if (!Array.isArray(cards) || cards.length === 0) {
        return { cardsScanned: 0, imagesScanned: 0, imagesRepaired: 0 };
    }

    let cardsScanned = 0;
    let imagesScanned = 0;
    let imagesRepaired = 0;

    cards.forEach((card: any) => {
        if (!card || card.type !== 'group') return;
        if (isStandalonePriceGroup(card)) return;

        cardsScanned += 1;
        const descendants = typeof card.getObjects === 'function' ? collectObjectsDeep(card) : [];
        const images = descendants.filter((o: any) => String(o?.type || '').toLowerCase() === 'image');

        images.forEach((img: any) => {
            imagesScanned += 1;
            let changed = false;

            let nextScaleX = Number(img.scaleX ?? 1);
            let nextScaleY = Number(img.scaleY ?? 1);
            if (!Number.isFinite(nextScaleX) || nextScaleX === 0) {
                nextScaleX = 1;
                changed = true;
            }
            if (!Number.isFinite(nextScaleY) || nextScaleY === 0) {
                nextScaleY = 1;
                changed = true;
            }
            if (nextScaleX < 0 || nextScaleY < 0) {
                nextScaleX = Math.abs(nextScaleX) || 1;
                nextScaleY = Math.abs(nextScaleY) || 1;
                changed = true;
            }

            if (img.flipX || img.flipY) changed = true;
            if (img.lockScalingFlip !== true) changed = true;
            if (img.lockSkewingX !== true || img.lockSkewingY !== true) changed = true;

            // Repair invalid intrinsic dimensions when legacy/corrupted state has zero or NaN sizes.
            const rawW = Number(img.width ?? 0);
            const rawH = Number(img.height ?? 0);
            let nextWidth = rawW;
            let nextHeight = rawH;
            if (!Number.isFinite(rawW) || rawW <= 0 || !Number.isFinite(rawH) || rawH <= 0) {
                const el: any = (img as any)._originalElement || (img as any)._element || null;
                const naturalW = Number(el?.naturalWidth ?? el?.width ?? 0);
                const naturalH = Number(el?.naturalHeight ?? el?.height ?? 0);
                if (Number.isFinite(naturalW) && naturalW > 0 && Number.isFinite(naturalH) && naturalH > 0) {
                    nextWidth = naturalW;
                    nextHeight = naturalH;
                    changed = true;
                }
            }

            if (changed) {
                img.set({
                    scaleX: nextScaleX,
                    scaleY: nextScaleY,
                    flipX: false,
                    flipY: false,
                    lockScalingFlip: true,
                    lockSkewingX: true,
                    lockSkewingY: true
                });
                if (Number.isFinite(nextWidth) && nextWidth > 0 && Number.isFinite(nextHeight) && nextHeight > 0) {
                    img.set({
                        width: nextWidth,
                        height: nextHeight
                    });
                }
                img.setCoords?.();
                imagesRepaired += 1;
            }

            // Always clamp inside card after load to prevent detached images from legacy states.
            applyContainmentConstraints(img);
        });
    });

    if (verbose && imagesRepaired > 0) {
        console.log('[repairLegacyProductCardImageTransforms] repaired:', {
            cardsScanned,
            imagesScanned,
            imagesRepaired
        });
    }

    return { cardsScanned, imagesScanned, imagesRepaired };
}

const preserveValidZoneStructureVariantSelection = (zone: any) => {
    if (!zone) return;

    const variantsByCount = zone.structureVariantsByProductCount;
    const currentSelection = zone.structureVariantByProductCount;
    if (!currentSelection || typeof currentSelection !== 'object' || Array.isArray(currentSelection)) {
        zone.structureVariantByProductCount = {};
        return;
    }

    zone.structureVariantByProductCount = Object.fromEntries(
        Object.entries(currentSelection).filter(([count, selectedId]) => {
            const variants = variantsByCount?.[count];
            if (!Array.isArray(variants)) return false;
            const id = String(selectedId || '').trim();
            return !!id && variants.some((variant: any) => String(variant?.id || '').trim() === id);
        })
    );
};

const preserveValidZoneStructureVariantSelectionsByPreviewFormat = (zone: any) => {
    const variantsByPreviewFormat = zone?.structureVariantsByProductCountByPreviewFormat;
    if (!variantsByPreviewFormat || typeof variantsByPreviewFormat !== 'object') return;

    const currentSelections = zone.structureVariantByProductCountByPreviewFormat;
    const safeSelections = currentSelections && typeof currentSelections === 'object' && !Array.isArray(currentSelections)
        ? currentSelections
        : {};
    const nextSelections: Record<string, Record<string, string>> = {};

    Object.entries(variantsByPreviewFormat).forEach(([format, variantsByCount]: [string, any]) => {
        const selections = (safeSelections[format] && typeof safeSelections[format] === 'object'
            ? safeSelections[format]
            : {}) as Record<string, unknown>;
        nextSelections[format] = Object.fromEntries(
            Object.entries(selections).filter(([count, selectedId]) => {
                const variants = variantsByCount?.[count];
                if (!Array.isArray(variants)) return false;
                const id = String(selectedId || '').trim();
                return !!id && variants.some((variant: any) => String(variant?.id || '').trim() === id);
            }).map(([count, selectedId]) => [count, String(selectedId)])
        ) as Record<string, string>;
    });

    zone.structureVariantByProductCountByPreviewFormat = nextSelections;
    const activeFormat = getCurrentProductZonePreviewFormat();
    if (nextSelections[activeFormat]) {
        zone.structureVariantByProductCount = nextSelections[activeFormat];
    }
};

const ensureZoneSanity = (
