const getResolvedZoneFrameId = (zone: any): string | undefined => {
    if (!canvas.value || !zone) return undefined;

    let frameId = String((zone as any).parentFrameId || '').trim() || undefined;
    if (frameId && !getFrameById(frameId)) {
        frameId = undefined;
    }

    if (!frameId) {
        const detected = findFrameUnderObject(zone);
        if (detected && detected._customId) {
            frameId = String(detected._customId);
        }
    }

    if ((zone as any).parentFrameId !== frameId) {
        (zone as any).parentFrameId = frameId;
        invalidateFrameRuntimeCache();
    }

    return frameId;
}

// applyCardFrameBinding extraido para utils/fabricObjectOps.ts.
// Wrapper local injeta invalidateFrameRuntimeCache.
const applyCardFrameBinding = (card: any, frameId?: string) =>
    applyCardFrameBindingHelper(card, frameId, invalidateFrameRuntimeCache)

const syncZoneCardFrameBindings = (zone: any, cards?: any[]) => {
    if (!zone) return;
    const zoneFrameId = getResolvedZoneFrameId(zone);
    const list = Array.isArray(cards) ? cards : getZoneChildren(zone);
    list.forEach((card: any) => applyCardFrameBinding(card, zoneFrameId));
}

type ZoneRuntimeIndex = {
    canvas: any;
    zonesById: Map<string, any>;
    cardsByZoneId: Map<string, any[]>;
    hasLegacyCandidates: boolean;
};

let zoneRuntimeIndex: ZoneRuntimeIndex | null = null;

const invalidateZoneRuntimeIndex = () => {
    zoneRuntimeIndex = null;
};

const appendUniqueZoneRuntimeObject = (target: any[], value: any) => {
    if (!value || target.includes(value)) return;
    target.push(value);
};

const getZoneRuntimeCardCandidates = (topLevel: any[]) => {
    const candidates: any[] = [];
    const isCandidateGroup = (o: any) => {
        if (!o) return false;
        const hasZoneBinding = !!(
            String((o as any)?.parentZoneId || '').trim() ||
            String((o as any)?._zoneSlot?.zoneId || '').trim()
        );
        if (o.visible === false && !hasZoneBinding) return false;
        if ((o as any).excludeFromExport) return false;
        if ((o as any).isFrame) return false;
        if (isLikelyProductZone(o)) return false;
        if (o.type !== 'group' || typeof o.getObjects !== 'function') return false;
        if (isStandalonePriceGroup(o)) return false;
        return true;
    };

    topLevel.forEach((obj: any) => {
        if (isCandidateGroup(obj)) appendUniqueZoneRuntimeObject(candidates, obj);
    });

    const seen = new Set<any>();
    const stack = [...topLevel];
    while (stack.length > 0) {
        const cur = stack.pop();
        if (!cur || seen.has(cur)) continue;
        seen.add(cur);
        if (cur.type !== 'group' || typeof cur.getObjects !== 'function') continue;
        if (isCandidateGroup(cur)) appendUniqueZoneRuntimeObject(candidates, cur);
        const children = cur.getObjects() || [];
        for (const child of children) {
            if (child?.type === 'group') stack.push(child);
        }
    }

    return candidates;
};

const ensureZoneRuntimeIndex = (): ZoneRuntimeIndex | null => {
    if (!canvas.value) return null;
    if (zoneRuntimeIndex && zoneRuntimeIndex.canvas === canvas.value) return zoneRuntimeIndex;

    const topLevel = canvas.value.getObjects?.() || [];
    const zonesById = new Map<string, any>();
    topLevel.forEach((obj: any) => {
        if (!obj || !isLikelyProductZone(obj)) return;
        const id = String((obj as any)?._customId || '').trim();
        if (id) zonesById.set(id, obj);
    });

    const cardsByZoneId = new Map<string, any[]>();
    let hasLegacyCandidates = false;

    getZoneRuntimeCardCandidates(topLevel).forEach((card: any) => {
        const explicitCard = !!(card.isProductCard || card.isSmartObject || String(card.name || '').startsWith('product-card'));
        const likelyCard = explicitCard ? true : isLikelyProductCard(card);
        if (!likelyCard) return;

        const boundId = String((card as any)?.parentZoneId || '').trim();
        const slotZoneId = String((card as any)?._zoneSlot?.zoneId || '').trim();
        const boundExists = !!(boundId && zonesById.has(boundId));
        const slotExists = !!(slotZoneId && zonesById.has(slotZoneId));
        const hasFrameMismatch = (zoneId: string) => {
            const zone = zonesById.get(zoneId);
            if (!zone) return false;
            const cardFrameId = String((card as any)?.parentFrameId || '').trim();
            const zoneFrameId = String(getResolvedZoneFrameId(zone) || (zone as any)?.parentFrameId || '').trim();
            return !!(cardFrameId && zoneFrameId && cardFrameId !== zoneFrameId);
        };

        if (boundExists && (!slotZoneId || slotZoneId === boundId) && !hasFrameMismatch(boundId)) {
            const list = cardsByZoneId.get(boundId) || [];
            appendUniqueZoneRuntimeObject(list, card);
            cardsByZoneId.set(boundId, list);
            return;
        }

        if (!boundId && slotExists && !hasFrameMismatch(slotZoneId)) {
            const list = cardsByZoneId.get(slotZoneId) || [];
            appendUniqueZoneRuntimeObject(list, card);
            cardsByZoneId.set(slotZoneId, list);
            return;
        }

        // Keep legacy/corruption recovery on the old geometric path.
        hasLegacyCandidates = true;
    });

    zoneRuntimeIndex = {
        canvas: canvas.value,
        zonesById,
        cardsByZoneId,
        hasLegacyCandidates
    };
    return zoneRuntimeIndex;
};

const getRuntimeProductZones = (): any[] => {
    if (!canvas.value) return [];
    const runtimeIndex = ensureZoneRuntimeIndex();
    if (runtimeIndex && runtimeIndex.canvas === canvas.value) {
        return Array.from(runtimeIndex.zonesById.values()).filter((zone: any) => (
            zone && isLikelyProductZone(zone) && (!zone.canvas || zone.canvas === canvas.value)
        ));
    }
    return (canvas.value.getObjects?.() || []).filter((obj: any) => isLikelyProductZone(obj));
};

const getRuntimeProductZoneById = (zoneIdRaw: any): any | null => {
    if (!canvas.value) return null;
    const zoneId = String(zoneIdRaw || '').trim();
    if (!zoneId) return null;

    const runtimeIndex = ensureZoneRuntimeIndex();
    const cached = runtimeIndex && runtimeIndex.canvas === canvas.value
        ? runtimeIndex.zonesById.get(zoneId)
        : null;
    if (cached && isLikelyProductZone(cached) && (!cached.canvas || cached.canvas === canvas.value)) {
        return cached;
    }

    return (canvas.value.getObjects?.() || []).find((obj: any) => (
        isLikelyProductZone(obj) && String((obj as any)?._customId || (obj as any)?.id || '').trim() === zoneId
    )) || null;
};

const normalizeZoneRuntimeCard = (card: any, explicitCard: boolean) => {
    if (!card) return;
    if (!explicitCard) {
        card.isProductCard = true;
        card.isSmartObject = true;
    }

    card.subTargetCheck = true;
    card.interactive = true;
    card.selectable = true;
    card.evented = true;

    trimProductImagesInCard(card);

    if (typeof card.getObjects === 'function') {
        card.getObjects().forEach((child: any) => {
            const n = String(child?.name || '');
    const isBackground = n === 'offerBackground' || n === 'price_bg' || n === 'label_bg_image' || n === 'price_bg_image' || n === 'splash_image';
            child.selectable = !isBackground;
            child.evented = !isBackground;
            child.hasControls = !isBackground;
            child.hasBorders = !isBackground;
            enableCardElementRotationControl(child, !isBackground);
        });
        const priceGroup = card.getObjects().find((child: any) => isPriceGroupObject(child));
        if (priceGroup) setPriceGroupInteractionMode(priceGroup, 'move');
    }
    if (typeof card.setCoords === 'function') card.setCoords();
};

const getZoneChildCandidates = (zone: any) => {
    if (!canvas.value || !zone) return [];
    const zoneId = String((zone as any)?._customId || '').trim();
    const runtimeIndex = ensureZoneRuntimeIndex();
    if (zoneId && runtimeIndex && !runtimeIndex.hasLegacyCandidates) {
        return (runtimeIndex.cardsByZoneId.get(zoneId) || []).filter(Boolean);
    }

    const topLevel = canvas.value.getObjects() || [];
    const isCandidateGroup = (o: any) => {
        if (!o || o === zone) return false;
        // FIX: Do NOT skip invisible objects when they are explicitly bound to
        // this zone via parentZoneId.  Viewport culling sets visible=false but
        // may clear __viewportCulled during cleanup, leaving "orphan-hidden"
        // cards.  These cards must still be found so recalculateZoneLayout can
        // reposition and re-show them.
        const isBoundToThisZone = zoneId && String((o as any)?.parentZoneId || '').trim() === zoneId;
        if (o.visible === false && !isBoundToThisZone) return false;
        if ((o as any).excludeFromExport) return false;
        if ((o as any).isFrame) return false;
        if (isLikelyProductZone(o)) return false;
        if (o.type !== 'group' || typeof o.getObjects !== 'function') return false;
        // Exclude only bare price labels, not misnamed legacy product cards.
        if (isStandalonePriceGroup(o)) return false;
        return true;
    };

    const appendUnique = (target: any[], list: any[]) => {
        list.forEach((item: any) => {
            if (!item || target.includes(item)) return;
            target.push(item);
        });
    };

    const topCandidates = topLevel.filter(isCandidateGroup);

    // Legacy states can mix top-level cards with nested product cards.
    // Merge both sets instead of short-circuiting on the first top-level match.
    const deepCandidates: any[] = [];
    const seen = new Set<any>();
    const stack = [...topLevel];
    while (stack.length > 0) {
        const cur = stack.pop();
        if (!cur || seen.has(cur)) continue;
        seen.add(cur);
        if (cur.type === 'group' && typeof cur.getObjects === 'function') {
            if (isCandidateGroup(cur)) deepCandidates.push(cur);
            const children = cur.getObjects() || [];
            for (const child of children) {
                if (child?.type === 'group') stack.push(child);
            }
        }
    }

    const mergedCandidates: any[] = [];
    appendUnique(mergedCandidates, topCandidates);
    appendUnique(mergedCandidates, deepCandidates);
    return mergedCandidates;
};

const getZoneChildren = (zone: any) => {
    if (!canvas.value || !zone) return [];
    const zoneId = String((zone as any)?._customId || '').trim();
    const runtimeIndex = ensureZoneRuntimeIndex();
    if (zoneId && runtimeIndex && !runtimeIndex.hasLegacyCandidates) {
        const zoneFrameId = getResolvedZoneFrameId(zone);
        return (runtimeIndex.cardsByZoneId.get(zoneId) || [])
            .filter(Boolean)
            .filter((card: any) => {
                const cardFrameId = String((card as any)?.parentFrameId || '').trim();
                return !zoneFrameId || !cardFrameId || cardFrameId === zoneFrameId;
            })
            .map((card: any) => {
                const explicitCard = !!(card.isProductCard || card.isSmartObject || String(card.name || '').startsWith('product-card'));
                normalizeZoneRuntimeCard(card, explicitCard);
                applyCardFrameBinding(card, zoneFrameId);
                return card;
            });
    }

    const candidates = getZoneChildCandidates(zone);

    const zoneBounds = getZoneMetrics(zone) ?? zone.getBoundingRect(true);
    const zoneFrameId = getResolvedZoneFrameId(zone);
    const zonesByIdForFrameRepair = new Map<string, any>();
    try {
        (canvas.value.getObjects?.() || []).forEach((obj: any) => {
            if (!obj || !isLikelyProductZone(obj)) return;
            const id = String((obj as any)?._customId || '').trim();
            if (id) zonesByIdForFrameRepair.set(id, obj);
        });
    } catch {
        // best-effort repair map only
    }
    const isCardFrameCompatibleWithZone = (card: any) => {
        const cardFrameId = String((card as any)?.parentFrameId || '').trim();
        if (!zoneFrameId || !cardFrameId) return true;
        return cardFrameId === zoneFrameId;
    };
    const pointsToZoneInAnotherFrame = (zoneIdRaw: any, card: any) => {
        const otherZoneId = String(zoneIdRaw || '').trim();
        if (!otherZoneId || otherZoneId === zoneId) return false;
        const cardFrameId = String((card as any)?.parentFrameId || '').trim();
        if (!zoneFrameId || !cardFrameId || cardFrameId !== zoneFrameId) return false;
        const otherZone = zonesByIdForFrameRepair.get(otherZoneId);
        const otherFrameId = otherZone ? String(getResolvedZoneFrameId(otherZone) || (otherZone as any)?.parentFrameId || '').trim() : '';
        return !!otherFrameId && otherFrameId !== cardFrameId;
    };
    const recoveryCenterMargin = (() => {
        const pad = typeof (zone as any)._zonePadding === 'number' ? (zone as any)._zonePadding : 20;
        const base = Math.min(zoneBounds.width || 0, zoneBounds.height || 0);
        // Keep a small snap tolerance for legacy cards without stealing neighbors from adjacent zones.
        return Math.max(20, Math.min(72, pad * 0.5 + base * 0.04));
    })();

    const getZoneAssociation = (o: any) => {
        const objBounds = o.getBoundingRect();
        const center = typeof o.getCenterPoint === 'function'
            ? o.getCenterPoint()
            : { x: (o.left ?? 0), y: (o.top ?? 0) };
        const isInside =
            objBounds.left >= zoneBounds.left &&
            objBounds.top >= zoneBounds.top &&
            objBounds.left + objBounds.width <= zoneBounds.left + zoneBounds.width &&
            objBounds.top + objBounds.height <= zoneBounds.top + zoneBounds.height;
        const centerInside =
            center.x >= zoneBounds.left &&
            center.x <= (zoneBounds.left + zoneBounds.width) &&
            center.y >= zoneBounds.top &&
            center.y <= (zoneBounds.top + zoneBounds.height);
        const centerNearZone =
            center.x >= (zoneBounds.left - recoveryCenterMargin) &&
            center.x <= (zoneBounds.left + zoneBounds.width + recoveryCenterMargin) &&
            center.y >= (zoneBounds.top - recoveryCenterMargin) &&
            center.y <= (zoneBounds.top + zoneBounds.height + recoveryCenterMargin);

        const overlapLeft = Math.max(zoneBounds.left, objBounds.left);
        const overlapTop = Math.max(zoneBounds.top, objBounds.top);
        const overlapRight = Math.min(zoneBounds.left + zoneBounds.width, objBounds.left + objBounds.width);
        const overlapBottom = Math.min(zoneBounds.top + zoneBounds.height, objBounds.top + objBounds.height);
        const overlapWidth = Math.max(0, overlapRight - overlapLeft);
        const overlapHeight = Math.max(0, overlapBottom - overlapTop);
        const overlapArea = overlapWidth * overlapHeight;
        const objArea = Math.max(1, (objBounds.width || 0) * (objBounds.height || 0));
        const overlapRatio = overlapArea / objArea;

        let intersects = false;
        try {
            intersects = !!zone.intersectsWithObject(o);
        } catch {
            intersects = false;
        }

        return {
            centerInside,
            centerNearZone,
            intersects,
            isInside,
            overlapRatio
        };
    };

    const canSafelyRecoverCard = (o: any) => {
        const assoc = getZoneAssociation(o);
        if (assoc.isInside || assoc.centerInside) return true;
        if (assoc.intersects && assoc.overlapRatio >= 0.35) return true;
        return assoc.centerNearZone && assoc.overlapRatio >= 0.2;
    };

    const normalizeLegacyCard = (o: any, explicitCard: boolean) => {
        normalizeZoneRuntimeCard(o, explicitCard);
    };

    const explicitBound: any[] = [];
    const slotBound: any[] = [];
    const legacyCandidates: any[] = [];
    let zoneRuntimeBindingsMutated = false;

    const finalizeZoneChildren = (children: any[]) => {
        if (zoneRuntimeBindingsMutated) invalidateZoneRuntimeIndex();
        return children;
    };

    const hasStrongCardSignature = (o: any) => {
        if (!o || typeof o.getObjects !== 'function') return false;
        const cw = Number((o as any)?._cardWidth);
        const ch = Number((o as any)?._cardHeight);
        if (Number.isFinite(cw) && cw > 0 && Number.isFinite(ch) && ch > 0) return true;

        const children = o.getObjects() || [];
        if (!Array.isArray(children) || children.length === 0) return false;

        const hasOfferBg = children.some((c: any) => String(c?.name || '') === 'offerBackground');
        if (hasOfferBg) return true;

        const hasPriceGroup = children.some((c: any) => String(c?.type || '').toLowerCase() === 'group' && String(c?.name || '') === 'priceGroup');
        const hasImage = children.some((c: any) => String(c?.type || '').toLowerCase() === 'image');
        return hasPriceGroup && hasImage;
    };

    candidates.forEach((o: any) => {
        const explicitCard = !!(o.isProductCard || o.isSmartObject || String(o.name || '').startsWith('product-card'));
        const likelyCard = explicitCard ? true : isLikelyProductCard(o);
        if (!likelyCard) return;

        const boundId = String((o as any)?.parentZoneId || '').trim();
        if (zoneId && boundId && boundId === zoneId) {
            if (!isCardFrameCompatibleWithZone(o)) return;
            normalizeLegacyCard(o, explicitCard);
            applyCardFrameBinding(o, zoneFrameId);
            explicitBound.push(o);
            return;
        }

        // Keep deterministic binding when slot metadata exists (important after undo/reload).
        const slotZoneId = String((o as any)?._zoneSlot?.zoneId || '').trim();
        if (zoneId && slotZoneId && slotZoneId === zoneId) {
            if (!isCardFrameCompatibleWithZone(o)) return;
            // CORRECAO A5: se boundId existe e aponta para OUTRA zona, o parentZoneId
            // e autoritativo — nao sequestrar o card aqui. Isso evita que um card
            // pertencente a Z1 apareca tambem em Z2 so porque _zoneSlot ficou stale
            // depois de um drag/undo.
            if (boundId && boundId !== zoneId) {
                return;
            }
            normalizeLegacyCard(o, explicitCard);
            o.parentZoneId = zoneId;
            zoneRuntimeBindingsMutated = true;
            applyCardFrameBinding(o, zoneFrameId);
            slotBound.push(o);
            return;
        }

        // Frame-duplicate repair: copied cards can keep parentZoneId/_zoneSlot from the
        // original zone while parentFrameId already points at the copied frame. In that
        // state, replacing products in the copied zone edits/removes the original zone.
        // If the card is physically in this zone's frame and near this zone, rebind it here.
        if (
            zoneId &&
            zoneFrameId &&
            (pointsToZoneInAnotherFrame(boundId, o) || pointsToZoneInAnotherFrame(slotZoneId, o)) &&
            canSafelyRecoverCard(o)
        ) {
            normalizeLegacyCard(o, explicitCard);
            o.parentZoneId = zoneId;
            (o as any)._zoneSlot = null;
            zoneRuntimeBindingsMutated = true;
            applyCardFrameBinding(o, zoneFrameId);
            explicitBound.push(o);
            return;
        }

        // Hard stop: a card already bound to ANOTHER zone must never be auto-captured here.
        if ((boundId && boundId !== zoneId) || (slotZoneId && slotZoneId !== zoneId)) {
            return;
        }

        legacyCandidates.push(o);
    });

    // Recover unbound but strongly-identifiable product cards that are still inside/near the zone.
    // This keeps old/corrupted layouts responsive after resize without stealing objects from other zones.
    const recoveredUnbound = legacyCandidates.filter((o: any) => {
        const boundId = String((o as any)?.parentZoneId || '').trim();
        const slotZoneId = String((o as any)?._zoneSlot?.zoneId || '').trim();
        if (boundId || slotZoneId) return false;
        if (!hasStrongCardSignature(o)) return false;
        if (!canSafelyRecoverCard(o)) return false;

        const explicitCard = !!(o.isProductCard || o.isSmartObject || String(o.name || '').startsWith('product-card'));
        normalizeLegacyCard(o, explicitCard);
        o.parentZoneId = zoneId || zone._customId;
        zoneRuntimeBindingsMutated = true;
        applyCardFrameBinding(o, zoneFrameId);
        return true;
    });

    // If the zone already has explicit bindings, keep strict mode but include recovered unbound cards.
    // This prevents false positives while fixing detached cards from legacy/buggy states.
    if (explicitBound.length > 0 || slotBound.length > 0) {
        return finalizeZoneChildren([...explicitBound, ...slotBound, ...recoveredUnbound]);
    }

    // Legacy rescue mode: only when no explicit cards exist for the zone.
    return finalizeZoneChildren(legacyCandidates.filter((o: any) => {
        // Legacy rescue should only capture truly unbound cards with a strong card signature.
        const boundId = String((o as any)?.parentZoneId || '').trim();
        const slotZoneId = String((o as any)?._zoneSlot?.zoneId || '').trim();
        if (boundId || slotZoneId) return false;
        if (!hasStrongCardSignature(o)) return false;
        if (!canSafelyRecoverCard(o)) return false;

        const explicitCard = !!(o.isProductCard || o.isSmartObject || String(o.name || '').startsWith('product-card'));
        normalizeLegacyCard(o, explicitCard);
        o.parentZoneId = zoneId || zone._customId;
        zoneRuntimeBindingsMutated = true;
        applyCardFrameBinding(o, zoneFrameId);
        return true;
    }));
}

// O modo rápido reutiliza a mesma zona e o mesmo importador do editor completo;
// este composable só organiza a superfície reduzida apresentada ao usuário.
const applyCurrentStructureRecipe = (zone: any, count: number) => {
    if (!zone || !productZoneStructuresState.isLoaded.value) return
    const patch = getProductZoneStructureLibraryPatch(zone,
        productZoneStructuresState.structureMapsByPreviewFormat.value,
        productZoneStructuresState.structureVariantsByPreviewFormat.value,
        count, getCurrentProductZonePreviewFormat())
    Object.assign(zone, patch)
    // ensureZoneSanity also reads this persisted snapshot during relayout.
    const layout = zone._zoneStateSnapshot?.zone?.layout
    if (layout) Object.assign(layout, JSON.parse(JSON.stringify(patch)))
}

const getQuickModeZoneStructureForUi = (
    zone: any,
    productCount: number
): {
    structure: ProductZoneStructure | null
    variants: ProductZoneStructureVariant[]
    selectedVariantId: string
} => {
    const previewFormat = getCurrentProductZonePreviewFormat()
    const count = Math.min(24, Math.max(1, Math.round(Number(productCount) || 1)))
    const baseZone = zone && typeof zone === 'object' ? zone : {}
    const globalLibraryReady = productZoneStructuresState.isLoaded.value
    const structureMaps = normalizeProductZoneStructureMapByPreviewFormat(
        globalLibraryReady
            ? productZoneStructuresState.structureMapsByPreviewFormat.value
            : baseZone.structureByProductCountByPreviewFormat,
        baseZone,
        globalLibraryReady
            ? productZoneStructuresState.structureMap.value
            : baseZone.structureByProductCount
    )
    const structureVariantsByPreviewFormat = normalizeProductZoneStructureVariantMapByPreviewFormat(
        globalLibraryReady
            ? productZoneStructuresState.structureVariantsByPreviewFormat.value
            : baseZone.structureVariantsByProductCountByPreviewFormat,
        baseZone,
        structureMaps,
        globalLibraryReady
            ? productZoneStructuresState.structureVariants.value
            : baseZone.structureVariantsByProductCount
    )
    const viewZone = {
        ...baseZone,
        structureByProductCountByPreviewFormat: structureMaps,
        structureByProductCount: structureMaps[previewFormat],
        structureVariantsByProductCountByPreviewFormat: structureVariantsByPreviewFormat,
        structureVariantsByProductCount: structureVariantsByPreviewFormat[previewFormat]
    }
    const key = String(count)
    const variants = Array.isArray(structureVariantsByPreviewFormat[previewFormat]?.[key])
        ? structureVariantsByPreviewFormat[previewFormat][key]
        : []
    const requestedVariantId = String(
        baseZone.structureVariantByProductCountByPreviewFormat?.[previewFormat]?.[key]
            ?? baseZone.structureVariantByProductCount?.[key]
            ?? ''
    ).trim()
    const selectedVariant = variants.find((variant) => String(variant?.id || '').trim() === requestedVariantId)
        || variants[0]
        || null
    const structure = resolveProductZoneStructure(viewZone, count, previewFormat)
        || (selectedVariant
            ? normalizeProductZoneStructure(selectedVariant, count, baseZone)
            : normalizeProductZoneStructure(structureMaps[previewFormat]?.[key], count, baseZone))

    return {
        structure,
        variants,
        selectedVariantId: String(selectedVariant?.id || '').trim()
    }
}

const handleQuickGridRestore = async (payload: { zoneId: string; preset: 'model' | '2' | '3' }) => {
    const zone = findProductZoneById(payload.zoneId);
    if (!zone || isProcessing.value || !['model', '2', '3'].includes(payload.preset)) return;
    const cards = getZoneChildren(zone);
    if (!cards.length) return;
    await saveCurrentState({ reason: 'before-restore-grid', source: 'user', skipCoalesce: true });
    zone.quickGridPreset = payload.preset;
    zone.highlightCount = 0;
    recalculateZoneLayout(zone, cards, { save: false, preserveStyles: true });
    syncZoneDerivedMetadata(zone);
    refreshCanvasObjects();
    safeRequestRenderAll();
    await saveCurrentState({ reason: 'restore-grid', source: 'user', skipCoalesce: true, skipIfUnchanged: false });
    await flushPersistenceNow('restore-grid', { force: true });
};

const handleQuickModeZoneStructureChange = async (payload: { zoneId?: string; variantId?: string }) => {
    const zoneId = String(payload?.zoneId || '').trim()
    const variantId = String(payload?.variantId || '').trim()
    if (!zoneId || !variantId || !canvas.value || isProcessing.value) return

    const zone = findProductZoneById(zoneId)
    const count = zone ? getZoneCardsForUi(zone).length : 0
    if (!zone || count <= 0) return

    const structureInfo = getQuickModeZoneStructureForUi(zone, count)
    if (!structureInfo.variants.some((variant) => String(variant?.id || '').trim() === variantId)) {
        notifyEditorError('A estrutura escolhida não está disponível para esta quantidade de produtos.')
        return
    }

    const previewFormat = getCurrentProductZonePreviewFormat()
    const key = String(Math.min(24, Math.max(1, Math.round(count))))
    const currentByPreviewFormat = zone.structureVariantByProductCountByPreviewFormat
        && typeof zone.structureVariantByProductCountByPreviewFormat === 'object'
        ? zone.structureVariantByProductCountByPreviewFormat
        : {}
    const nextByPreviewFormat = {
        ...currentByPreviewFormat,
        [previewFormat]: {
            ...(currentByPreviewFormat[previewFormat] || {}),
            [key]: variantId
        }
    }
    const nextFlatSelection = {
        ...(zone.structureVariantByProductCount || {}),
        [key]: variantId
    }

    delete zone.quickGridPreset
    applyCurrentStructureRecipe(zone, count)
    setActiveProductZone(zone, { syncImportTarget: true })
    await handleUpdateZone({
        structureVariantByProductCount: nextFlatSelection,
        structureVariantByProductCountByPreviewFormat: nextByPreviewFormat
    }, undefined, { targetId: zoneId })
}

const {
    quickModeZones,
    quickModeTargetZoneId,
    quickModeTargetZone,
    selectQuickModeZone,
    openQuickProductImport
} = useQuickEditorControls({
    productZoneUiVersion,
    getRuntimeProductZones,
    getZoneChildren,
    getZoneCardsForUi,
    getProductZoneId,
    resolveImportTargetZone,
    setActiveProductZone,
    canvas,
    isProcessing,
    isParsingProducts,
    addGridZone,
    openProductReviewForZone,
    notifyEditorError,
    refreshCanvasObjects,
    getZoneStructureForUi: getQuickModeZoneStructureForUi,
    refreshQuickModeUi: invalidateQuickModeUi
})

type QuickModeProductItem = {
    id: string
    name: string
    price?: string
    imageUrl?: string
    labelName?: string
}

const getQuickModeProductImageUrl = (card: any, product: any): string => {
    const image = getPreferredProductImageFromGroup(card)
    // A referência persistida no produto é a fonte de verdade para a lista.
    // O filho Fabric é mantido como fallback para projetos antigos que ainda
    // não copiaram a key do Wasabi para _productData.
    const candidates = [
        String(resolveProductImageRef(product) || '').trim(),
        String((card as any)?.imageUrl || '').trim(),
        String(getImageSourceFromObject(image) || '').trim()
    ]
    for (const raw of [...new Set(candidates)].filter(Boolean)) {
        if (isLikelyPlaceholderImageSrc(raw)) continue
        const resolved = toWasabiProxyUrl(raw) || raw
        if (!isLikelyPlaceholderImageSrc(resolved)) return resolved
    }
    return ''
}

const getQuickModeProductId = (card: any, index: number): string => (
    String(card?._customId || card?._productData?.id || `quick-product-${index + 1}`).trim()
)

const quickModeProducts = computed<QuickModeProductItem[]>(() => {
    void productZoneUiVersion.value
    const zone = quickModeTargetZone.value
    if (!zone) return []
    return getZoneCardsForUi(zone).map((card: any, index: number) => {
        const product = (card?._productData && typeof card._productData === 'object')
            ? card._productData
            : card
        const available = getAvailablePrices(product)
        const priceValue = String(available.mainPrice || '').replace(/^R\$\s*/i, '').trim()
        const currentTemplateId = String(card?.__cardLabelTemplateId || zone?._zoneGlobalStyles?.splashTemplateId || '').trim()
        const currentTemplate = labelTemplates.value.find((template: any) => String(template?.id || '').trim() === currentTemplateId)
        return {
            id: getQuickModeProductId(card, index),
            name: String(product?.name || card?.productName || `Produto ${index + 1}`).trim() || `Produto ${index + 1}`,
            price: priceValue ? `R$ ${priceValue}` : undefined,
            imageUrl: getQuickModeProductImageUrl(card, product) || undefined,
            labelName: currentTemplate ? String(currentTemplate.name || '').trim() || undefined : undefined
        }
    })
})

const quickModeBulkLabelTemplates = computed(() => {
    void productZoneUiVersion.value
    const zone = quickModeTargetZone.value
    const cards = zone ? getZoneCardsForUi(zone) : []
    if (!cards.length) return []

    // A template can be applied in bulk only when every card in the active
    // zone accepts the same pricing model (simple or multi-price).
    let common = getCompatibleProductLabelTemplateOptions(cards[0])
    for (const card of cards.slice(1)) {
        const ids = new Set(getCompatibleProductLabelTemplateOptions(card).map((template: any) => template.id))
        common = common.filter((template: any) => ids.has(template.id))
        if (!common.length) break
    }
    return common
})

const findQuickModeProductCard = (productId: string): any | null => {
    const id = String(productId || '').trim()
    if (!id) return null
    const zone = quickModeTargetZone.value
    if (!zone) return null
    return getZoneCardsForUi(zone).find((card: any, index: number) => getQuickModeProductId(card, index) === id) || null
}

const discardQuickModeCardSelection = (cards: any[]) => {
    const list = Array.isArray(cards) ? cards.filter(Boolean) : []
    if (!canvas.value || list.length === 0) return
    const active = canvas.value.getActiveObject?.()
    const selectedImage = selectedProductImageSubTarget.value
    const belongsToCard = (target: any): boolean => {
        if (!target) return false
        if (list.includes(target)) return true
        try {
            const context = resolveSelectedProductCardContext(target)
            if (context?.card && list.includes(context.card)) return true
        } catch {
            // Ignore stale Fabric references while a product card is removed.
        }
        return false
    }
    if (belongsToCard(active) || belongsToCard(selectedImage)) {
        canvas.value.discardActiveObject?.()
        selectedProductImageSubTarget.value = null
        selectedProductImageSelectionKind.value = 'none'
        selectedObjectRef.value = null
    }
}

const handleQuickModeClearProducts = async () => {
    if (!canvas.value) return
    const zones = canvas.value.getObjects().filter((object: any) => isLikelyProductZone(object))
    const cards = Array.from(new Set(zones.flatMap((zone: any) => getZoneCardsForUi(zone))))
    if (!cards.length) return
    discardQuickModeCardSelection(cards)
    zones.forEach((zone: any) => clearProductZoneCards(zone))
    refreshCanvasObjects({ immediate: true })
    invalidateQuickModeUi()
    safeRequestRenderAll()
    updateSelection()
    await persistQuickModeDataChange('quick-products-clear')
}

const handleQuickModeDeleteProduct = async (productId: string) => {
    const card = findQuickModeProductCard(productId)
    if (!card || !canvas.value) return
    discardQuickModeCardSelection([card])
    try {
        canvas.value.remove(card)
    } catch {
        return
    }
    const zone = quickModeTargetZone.value
    if (zone) {
        relayoutProductZonesAfterCardRemoval([zone])
    }
    refreshCanvasObjects({ immediate: true })
    invalidateQuickModeUi()
    safeRequestRenderAll()
    updateSelection()
    await persistQuickModeDataChange('quick-product-delete')
}

const handleQuickModeMoveProduct = async (payload: { productId?: string; direction?: 'up' | 'down' }) => {
    const direction = payload?.direction === 'down' ? 'down' : 'up'
    const productId = String(payload?.productId || '').trim()
    const zone = quickModeTargetZone.value
    if (!productId || !zone || !canvas.value) return

    const cards = getZoneCardsForUi(zone).slice()
    const currentIndex = cards.findIndex((card: any, index: number) => getQuickModeProductId(card, index) === productId)
    if (currentIndex < 0) return
    const targetIndex = direction === 'down' ? currentIndex + 1 : currentIndex - 1
    if (targetIndex < 0 || targetIndex >= cards.length) return

    const currentCard = cards[currentIndex]
    const targetCard = cards[targetIndex]
    const currentOrder = Number.isFinite(Number(currentCard?._zoneOrder)) ? Number(currentCard._zoneOrder) : currentIndex
    const targetOrder = Number.isFinite(Number(targetCard?._zoneOrder)) ? Number(targetCard._zoneOrder) : targetIndex
    currentCard._zoneOrder = targetOrder
    targetCard._zoneOrder = currentOrder

    cards.sort((a: any, b: any) => Number(a?._zoneOrder || 0) - Number(b?._zoneOrder || 0))
    cards.forEach((card: any, index: number) => { card._zoneOrder = index })
    ensureZoneSanity(zone)
    recalculateZoneLayout(zone, cards, {
        save: false,
        requestRender: false,
        trustCachedChildren: true,
        preserveStyles: true
    })
    refreshCanvasObjects({ immediate: true })
    invalidateQuickModeUi()
    safeRequestRenderAll()
    await persistQuickModeDataChange('quick-product-reorder')
}

const handleQuickModeSelectProduct = (productId: string) => {
    const card = findQuickModeProductCard(productId)
    if (!card || !canvas.value) return
    const image = getPreferredProductImageFromGroup(card)
    selectedProductImageSubTarget.value = image || null
    selectedProductImageSelectionKind.value = image ? 'image' : 'card'
    try {
        canvas.value.setActiveObject(card)
    } catch {
        return
    }
    refreshSelectedRef()
    updateSelection()
    safeRequestRenderAll()
}

const handleQuickModeOpenProductImagePicker = async (productId: string) => {
    const card = findQuickModeProductCard(productId)
    if (!card || !canvas.value) return

    handleQuickModeSelectProduct(productId)
    const product = (card?._productData && typeof card._productData === 'object')
        ? card._productData
        : card
    const search = String(product?.name || card?.productName || '').trim()
    const image = getPreferredProductImageFromGroup(card)

    if (image) {
        if (!(image as any)._customId) {
            ;(image as any)._customId = makeCanvasObjectId()
        }
        await openProductImageUploadPickerModal('replace', {
            imageId: String((image as any)._customId),
            search
        })
        return
    }

    const cardId = String((card as any)._customId || '').trim()
    if (!cardId) {
        notifyEditorError('Não foi possível identificar este card para adicionar a imagem.')
        return
    }
    await openProductImageUploadPickerModal('add', { cardId, search })
}

const handleQuickModeBulkLabelChange = async (templateId: string) => {
    const id = String(templateId || '').trim()
    const zone = quickModeTargetZone.value
    if (!id || !zone || !canvas.value) return

    const template = labelTemplates.value.find((item: any) => String(item?.id || '').trim() === id)
    if (!template) {
        notifyEditorError('A etiqueta selecionada não está disponível.')
        return
    }

    const cards = getZoneCardsForUi(zone)
    const incompatible = cards.filter((card: any) => !isProductLabelTemplateCompatible(card, template))
    if (incompatible.length > 0) {
        notifyEditorError('Essa etiqueta não é compatível com todos os produtos desta zona.')
        return
    }

    let applied = 0
    for (const card of cards) {
        const previousTemplateId = String((card as any).__cardLabelTemplateId || '').trim()
        const hadPreviousTemplateId = Object.prototype.hasOwnProperty.call(card, '__cardLabelTemplateId')
        const previousTemplateOverride = (card as any).__cardLabelTemplateOverride
        const hadPreviousTemplateOverride = Object.prototype.hasOwnProperty.call(card, '__cardLabelTemplateOverride')
        // Uma troca em lote torna a etiqueta uma herança da zona. A escolha
        // individual só é marcada como override pelos handlers do card.
        setCardLabelTemplateMetadata(card, id, false)
        card.set?.({ dirty: true })
        try {
            await applyLabelTemplateToCard(card, id)
            setCardLabelTemplateMetadata(card, id, false)
            card.set?.({ dirty: true })
            card.setCoords?.()
            applied += 1
        } catch (error) {
            if (hadPreviousTemplateId) (card as any).__cardLabelTemplateId = previousTemplateId
            else delete (card as any).__cardLabelTemplateId
            if (hadPreviousTemplateOverride) (card as any).__cardLabelTemplateOverride = previousTemplateOverride
            else delete (card as any).__cardLabelTemplateOverride
            console.warn('[quick-editor] Falha ao trocar etiqueta em lote', error)
        }
    }
    if (!applied) {
        notifyEditorError('Não foi possível trocar as etiquetas dos produtos.')
        return
    }

    // A escolha em lote também atualiza a preferência da zona. Assim, ao
    // recarregar o encarte, o reconciliador global não ressuscita a etiqueta
    // anterior que estava salva no snapshot.
    const previousZoneStyles = getZoneGlobalStyles(zone);
    (zone as any)._zoneGlobalStyles = normalizeGlobalStylesHelper({
        ...previousZoneStyles,
        splashTemplateId: id
    }, DEFAULT_GLOBAL_STYLES);
    (zone as any)._zoneTemplateSnapshotId = id;
    (zone as any)._zoneTemplateSnapshot = cloneTemplateGroupJson((template as any)?.group) || null;

    refreshSelectedRef()
    updateSelection()
    safeRequestRenderAll()
    await persistQuickModeDataChange('quick-products-label-bulk')
}

const handleQuickModeImport = async (payload: { mode?: 'replace' | 'append'; text?: string; file?: File; autoFillImages?: boolean; oneProductPerPage?: boolean }) => {
    quickModeOneProductPerPage.value = payload.oneProductPerPage === true
    quickModeAutoFillImages.value = payload.autoFillImages === true
    quickModeInitialProductFile.value = payload.file || null
    quickModeInitialProductText.value = String(payload?.text || '').trim()
    quickModeAutoParseProductText.value = quickModeInitialProductText.value.length > 0
    await openQuickProductImport(payload?.mode === 'append' ? 'append' : 'replace')
}

const moveZoneChildren = (zone: any, dx: number, dy: number, children?: any[]) => {
    if (!zone || (!dx && !dy)) return;
    const list = children && children.length > 0 ? children : getZoneChildren(zone);
    list.forEach((child: any) => {
        child.set({
            left: child.left + dx,
            top: child.top + dy
        });
        child.setCoords();
    });
}

// normalizeZoneScale + applyZoneScaleToRect extraidos para utils/fabricObjectOps.ts.

// normalizeRectScale e normalizeGroupRects extraidos para utils/fabricObjectOps.ts.

// stableHash32 e getZoneHighlightPredicate extraidos para
// utils/zoneHighlightHelpers.ts.

type RecalculateZoneLayoutOptions = {
    save?: boolean;
    requestRender?: boolean;
    trustCachedChildren?: boolean;
    /** @deprecated No longer used — resizeSmartObject always runs to fix Fabric v7 group center shifts */
    preserveCardInternals?: boolean;
    /** When true, only reposition cards (set left/top) without calling resizeSmartObject.
     *  Used on rehydrate to preserve card internal layout (text sizes, positions) from JSON. */
    skipResize?: boolean;
    /** When true, resize cards proportionally but do NOT re-apply zone global styles
     *  (colors, fonts, borders). Used on zone move/resize to preserve existing card styling. */
    preserveStyles?: boolean;
};

const recalculateZoneLayout = (
    zone: any,
    cachedChildren?: any[],
    opts: RecalculateZoneLayoutOptions = {}
) => getEditorProductGridController().recalculateZoneLayout(zone, cachedChildren, opts);

const applyGlobalProductZoneStructuresToCanvas = (reason = 'global-structure-update') => {
    // O mapa default do composable não é uma configuração global carregada.
    // Enquanto a API não respondeu, preservamos a receita do projeto; assim
    // um reload não substitui silenciosamente uma zona antiga pelo default.
    if (!canvas.value || !productZoneStructuresState.isLoaded.value) return;
    const zones = canvas.value.getObjects().filter((obj: any) => (
        isLikelyProductZone(obj) &&
        !(isTemplateCompositionManagedZone(obj) && hasPersistedProductZoneStructure(obj))
    ));
    if (zones.length === 0) return;

    const activePreviewFormat = getCurrentProductZonePreviewFormat();
    const globalMaps = normalizeProductZoneStructureMapByPreviewFormat(
        productZoneStructuresState.structureMapsByPreviewFormat.value
    );
    const globalVariantsByPreviewFormat = normalizeProductZoneStructureVariantMapByPreviewFormat(
        productZoneStructuresState.structureVariantsByPreviewFormat.value,
        {},
        globalMaps
    );
    const globalMap = globalMaps[activePreviewFormat]
        || globalMaps[DEFAULT_PRODUCT_ZONE_PREVIEW_FORMAT];
    const globalVariants = globalVariantsByPreviewFormat[activePreviewFormat]
        || globalVariantsByPreviewFormat[DEFAULT_PRODUCT_ZONE_PREVIEW_FORMAT];
    zones.forEach((zone: any) => {
        zone.structureByProductCountByPreviewFormat = globalMaps;
        zone.structureByProductCount = globalMap;
        zone.structureVariantsByProductCountByPreviewFormat = globalVariantsByPreviewFormat;
        zone.structureVariantsByProductCount = globalVariants;
        preserveValidZoneStructureVariantSelection(zone);
        preserveValidZoneStructureVariantSelectionsByPreviewFormat(zone);
        zone.structureByProductCountEnabled = true;
        const cards = getZoneChildren(zone);
        if (cards.length > 0) {
            recalculateZoneLayout(zone, cards, {
                save: false,
                requestRender: false,
                preserveStyles: true
            });
        }
        syncZoneDerivedMetadata(zone);
    });

    refreshCanvasObjects();
    refreshSelectedRef();
    safeRequestRenderAll();
    void Promise.resolve(saveCurrentState({
        allowEmptyOverwrite: true,
        reason,
        source: 'system',
        // A live edit must render immediately, but canvas persistence can be
        // coalesced so dragging a field does not start one upload per keystroke.
        skipCoalesce: false,
        skipIfUnchanged: true
    })).catch(() => { /* a proxima persistencia tenta novamente */ });
}

function handleGlobalProductZoneStructuresUpdated() {
    scheduleGlobalProductLibrariesApply('global-structure-update');
}

const applyGlobalProductCardConfigurationToCanvas = (reason = 'global-card-configuration-update', includeTemplates = false) => {
    if (!canvas.value || !productCardConfigurationState.isLoaded.value) return;

    const cardLayout = normalizeProductCardConfiguration(productCardConfigurationState.configuration.value);
    const zones = canvas.value.getObjects().filter((obj: any) => (
        isLikelyProductZone(obj) &&
        (includeTemplates || !(isTemplateCompositionManagedZone(obj) && hasPersistedCardLayout(obj)))
    ));
    if (zones.length === 0) return;

    zones.forEach((zone: any) => {
        const previousStyles = getZoneGlobalStyles(zone);
        const nextStyles = normalizeGlobalStyles({ ...previousStyles, cardLayout });
        (zone as any)._zoneGlobalStyles = nextStyles;

        const cards = getZoneChildren(zone);
        if (cards.length > 0) {
            cards.forEach((card: any) => {
                (card as any).__forceCardRelayout = true;
            });
            applyGlobalStylesToCards(nextStyles, zone, {
                cards,
                prop: 'cardLayout'
            });
        }
        syncZoneDerivedMetadata(zone);
    });

    refreshCanvasObjects();
    refreshSelectedRef();
    safeRequestRenderAll();
    void Promise.resolve(saveCurrentState({
        allowEmptyOverwrite: true,
        reason,
        source: 'system',
        skipCoalesce: false,
        skipIfUnchanged: true
    })).catch(() => { /* a proxima persistencia tenta novamente */ });
};

// As bibliotecas globais podem terminar de carregar depois da primeira
// hidratação do Fabric. Agende uma aplicação coalescida e espere o canvas
// deixar o estado de loading antes de relayoutar as zonas. Isso evita que a
// receita antiga do JSON do encarte ganhe da configuração global por causa de
// uma corrida de boot, sem criar renders/saves em loop.
let globalProductLibrariesApplyTimer: number | null = null;
let globalProductLibrariesApplyReason = 'global-library-sync';
let globalProductLibrariesApplyRetry = 0;
let pendingExplicitCardConfigurationUpdate = false;

const scheduleGlobalProductLibrariesApply = (reason = 'global-library-sync') => {
    if (typeof window === 'undefined' || isCanvasDestroyed.value) return;
    globalProductLibrariesApplyReason = reason;
    if (globalProductLibrariesApplyTimer) return;
    globalProductLibrariesApplyRetry = 0;

    const run = () => {
        globalProductLibrariesApplyTimer = null;
        if (isCanvasDestroyed.value) return;

        const ready = !!canvas.value
            && !!isFabricReady.value
            && isInitialDesignLoadDone.value
            && !isDesignLoading.value
            && !isCanvasJsonLoadInProgress;
        if (!ready) {
            if (globalProductLibrariesApplyRetry >= 80) return;
            globalProductLibrariesApplyRetry += 1;
            globalProductLibrariesApplyTimer = window.setTimeout(run, 100);
            return;
        }

        globalProductLibrariesApplyRetry = 0;
        applyGlobalProductZoneStructuresToCanvas(globalProductLibrariesApplyReason);
        applyGlobalProductCardConfigurationToCanvas(globalProductLibrariesApplyReason, pendingExplicitCardConfigurationUpdate);
        pendingExplicitCardConfigurationUpdate = false;
    };

    globalProductLibrariesApplyTimer = window.setTimeout(run, 0);
};

watch(
    [
        () => productZoneStructuresState.isLoaded.value,
        () => productCardConfigurationState.isLoaded.value,
        () => canvas.value,
        () => activePage.value?.id || '',
        () => isInitialDesignLoadDone.value,
        () => isDesignLoading.value,
        () => pageReloadToken.value
    ],
    () => {
        if (productZoneStructuresState.isLoaded.value || productCardConfigurationState.isLoaded.value) {
            scheduleGlobalProductLibrariesApply('global-library-sync');
        }
    },
    { flush: 'post', immediate: true }
);

let globalLabelTemplatesApplyPromise: Promise<void> | null = null;

const getLabelTemplateGroupSignature = (group: any): string => {
    try {
        return JSON.stringify(group ?? null);
    } catch {
        return '';
    }
};

/**
 * O ID do modelo não é suficiente para saber se a etiqueta renderizada está
 * correta: projetos antigos podem ter o mesmo `tpl_barlow_black` salvo no
 * card, mas ainda carregar o `price_bg` vermelho de um default anterior.
 * Compare a assinatura visual do grupo enlivenado com a da biblioteca para
 * reconstruir somente cards herdados que realmente ficaram divergentes.
 */
const cardLabelVisualDriftsFromTemplate = (card: any, template: any): boolean => {
    if (!card || !template?.group) return true;
    const priceGroup = typeof card?.getObjects === 'function'
        ? (card.getObjects() || []).find((object: any) => (
            object && String(object.type || '').toLowerCase() === 'group' && String(object.name || '') === 'priceGroup'
        )) || getPriceGroupFromAny(card)
        : getPriceGroupFromAny(card);
    if (!priceGroup) return true;

    const currentSignature = buildLabelTemplateVisualSignature(priceGroup);
    const templateSignature = buildLabelTemplateVisualSignature(template.group);
    // An empty signature means the group is malformed or not yet enlivened;
    // letting the normal template application repair it is safer than
    // silently accepting a card whose visual tree cannot be compared.
    return !currentSignature || !templateSignature || currentSignature !== templateSignature;
};

/**
 * Reaplica a biblioteca global de etiquetas nas zonas do canvas.
 *
 * O JSON do projeto pode carregar `_zoneTemplateSnapshot` antigo. Ele é
 * apenas compatibilidade: quando a biblioteca externa está carregada, o
 * template pelo ID e o seu `group` atual vencem o snapshot. Se o ID foi
 * excluído da biblioteca, removemos a referência e voltamos ao preço padrão
 * para não ressuscitar uma etiqueta que não existe mais globalmente.
 */
const applyGlobalLabelTemplatesToCanvas = async (reason = 'global-label-template-update'): Promise<void> => {
    if (!canvas.value || !hasUsableLabelTemplateCatalog()) return;
    // Uma troca de página pode acontecer enquanto a página anterior ainda
    // está reconstruindo cards. Aguarde e execute novamente sobre o canvas
    // atual, em vez de perder a aplicação da segunda página.
    if (globalLabelTemplatesApplyPromise) {
        await globalLabelTemplatesApplyPromise;
        if (!canvas.value || !hasUsableLabelTemplateCatalog()) return;
    }

    const run = (async () => {
        const zones = canvas.value?.getObjects?.().filter((obj: any) => (
            isLikelyProductZone(obj) && !isTemplateCompositionManagedZone(obj)
        )) || [];
        if (!zones.length) return;

        let changed = false;
        for (const zone of zones) {
            const styles = getZoneGlobalStyles(zone);
            const styleTemplateId = String(styles?.splashTemplateId || '').trim();
            const snapshotTemplateId = String((zone as any)?._zoneTemplateSnapshotId || '').trim();
            const templateId = styleTemplateId || snapshotTemplateId;
            const template = templateId
                ? labelTemplates.value.find((item: any) => String(item?.id || '').trim() === templateId)
                : undefined;
            const snapshotGroup = (zone as any)?._zoneTemplateSnapshot;

            if (template) {
                const zoneCards = getZoneChildren(zone);
                // O snapshot da zona pode estar atualizado mesmo quando os
                // grupos reais dos cards ainda apontam para etiquetas antigas.
                // Esse era o motivo de uma zona mostrar Barlow Black enquanto
                // alguns produtos continuavam com Oferta (amarela) ou
                // Preto/Amarelo. IDs legados sem o marcador explícito são
                // considerados herdados e devem acompanhar a zona.
                const hasCardTemplateDrift = zoneCards.some((card: any) => {
                    const cardTemplateId = String((card as any)?.__cardLabelTemplateId || '').trim();
                    if (!cardTemplateId) return true;
                    const cardTemplateStillExists = labelTemplates.value.some((item: any) => (
                        String(item?.id || '').trim() === cardTemplateId
                    ));
                    if (!cardTemplateStillExists) return !cardHasExplicitLabelTemplateOverride(card);
                    // A card explicitly customized in the quick editor keeps
                    // its own label by design. Inherited cards, however, must
                    // match both the selected ID and the library's visual
                    // tree, including fill/stroke/font changes made after the
                    // project was saved.
                    if (cardHasExplicitLabelTemplateOverride(card)) return false;
                    if (cardTemplateId !== String(template.id)) return true;
                    return cardLabelVisualDriftsFromTemplate(card, template);
                });
                const currentGroupSignature = getLabelTemplateGroupSignature(snapshotGroup);
                const globalGroupSignature = getLabelTemplateGroupSignature((template as any)?.group);
                const needsReapply =
                    styleTemplateId !== String(template.id) ||
                    snapshotTemplateId !== String(template.id) ||
                    currentGroupSignature !== globalGroupSignature ||
                    hasCardTemplateDrift;

                if (!needsReapply) continue;
                const applied = await applyLabelTemplateToZone(zone, String(template.id), {
                    applyToExisting: true,
                    requestRender: false,
                    save: false
                });
                changed = changed || applied;
                continue;
            }

            if (templateId) {
                // A deleted/renamed global template must not fall back to the
                // immutable project snapshot. Clear the zone and its cards.
                const applied = await applyLabelTemplateToZone(zone, undefined, {
                    applyToExisting: true,
                    requestRender: false,
                    save: false
                });
                changed = changed || applied;
                continue;
            }

            // Metadata-less legacy zones can still carry a private snapshot.
            // Drop it once the external library is authoritative so future
            // imports/relayouts cannot use that stale definition.
            if (snapshotTemplateId || (snapshotGroup && typeof snapshotGroup === 'object')) {
                (zone as any)._zoneTemplateSnapshotId = undefined;
                (zone as any)._zoneTemplateSnapshot = undefined;
                changed = true;
            }
        }

        if (changed) {
            refreshSelectedRef();
            safeRequestRenderAll();
            // Template replacement is asynchronous and may happen after Fabric's
            // render scheduler already consumed its frame. Paint once immediately
            // as well, so the visible canvas cannot keep the previous label bitmap.
            try {
                if (canvas.value && typeof canvas.value.renderAll === 'function') {
                    canvas.value.renderAll();
                }
            } catch {
                // The scheduled safe render remains the fallback for a disposed
                // or temporarily unavailable canvas context.
            }
            const didQueueLabelReconciliationSave = await saveCurrentState({
                allowEmptyOverwrite: true,
                reason,
                source: 'system',
                // A reconciliação troca a árvore visual dos cards e precisa
                // entrar no próximo sync remoto. Sem marcar a página como
                // pendente, `saveProjectDB()` entendia que não havia nada
                // novo para enviar e o JSON antigo continuava no Storage.
                markUnsaved: true,
                skipCoalesce: false,
                skipIfUnchanged: true
            });
            // `source: system` não agenda autosave por política. Como aqui
            // houve uma alteração real no canvas, tenta-se a durabilidade já
            // nesta fila. O retry agendado continua como segunda barreira para
            // falhas transitórias de rede/Wasabi.
            if (didQueueLabelReconciliationSave) {
                if (activePage.value) {
                    ;(activePage.value as any).__needsCanvasUpload = true
                    activePage.value.dirty = true
                    hasUnsavedChanges.value = true
                }
                queueMicrotask(() => {
                    void flushAutoSave().catch((err: any) => {
                        console.warn('[labelTemplates] Falha ao persistir reconciliação no Storage:', err)
                    })
                })
            }
            triggerAutoSave();
        } else {
            refreshSelectedRef();
        }
    })();

    globalLabelTemplatesApplyPromise = run;
    try {
        await run;
    } finally {
        if (globalLabelTemplatesApplyPromise === run) {
            globalLabelTemplatesApplyPromise = null;
        }
    }
};

// Se a biblioteca real de etiquetas chegar depois do canvas (caso comum no
// modo rápido), reaplique-a quando a página terminar de carregar ou mudar.
// O helper já serializa chamadas concorrentes e só persiste quando encontra
// uma diferença efetiva no grupo da etiqueta.
watch(
    [
        () => isLabelTemplateLibraryAuthoritative.value,
        // Em sessões offline, a biblioteca embutida no projeto é a fonte de
        // fallback. Reexecute a reconciliação quando esse snapshot chegar,
        // mesmo sem a flag de catálogo externo autenticado.
        () => (labelTemplates.value || []).map((template: any) => `${String(template?.id || '').trim()}:${String(template?.updatedAt || '')}`).join('|'),
        () => canvas.value,
        () => activePage.value?.id || '',
        () => isInitialDesignLoadDone.value,
        () => isDesignLoading.value,
        () => pageReloadToken.value
    ],
    () => {
        if (hasUsableLabelTemplateCatalog()) {
            void applyGlobalLabelTemplatesToCanvas('global-label-library-sync').catch(() => {
                // Uma nova alteração de página/biblioteca agenda a tentativa seguinte.
            });
        }
    },
    { flush: 'post', immediate: true }
);

function handleGlobalProductCardConfigurationUpdated(event?: Event) {
    const origin = (event as CustomEvent | undefined)?.detail?.origin
    if (origin === 'local' || origin === 'remote') pendingExplicitCardConfigurationUpdate = true
    scheduleGlobalProductLibrariesApply('global-card-configuration-update');
}

const rehydrateCanvasZones = (
    opts: {
        relayout?: boolean;
        applyZoneStyles?: boolean;
        applyGlobalLibraries?: boolean;
        recoverZoneSnapshots?: boolean;
        legacyImageRepairMode?: 'auto' | 'force' | 'skip';
    } = {}
) => getEditorProductGridController().rehydrateCanvasZones(opts);

const handleRecalculateLayout = () => {
    const zone = getCurrentZoneObject();
    if (!zone) return;
    ensureZoneSanity(zone);
    recalculateZoneLayout(zone);
    // Re-select zone and refresh snapshot after layout recalculation
    if (canvas.value) {
        try { canvas.value.setActiveObject(zone); } catch { /* ignore */ }
        safeRequestRenderAll();
    }
    refreshSelectedRef();
}

const handleAutoOfferLayout = async () => {
    const zone = getCurrentZoneObject();
    if (!zone) {
        notifyEditorInfo('Selecione uma Zona de Produtos primeiro.');
        return;
    }
    ensureZoneSanity(zone);

    const cards = getZoneChildren(zone);
    if (!cards.length) {
        notifyEditorInfo('Importe produtos antes de aplicar o layout automático.');
        return;
    }

    const zoneBounds = getZoneMetrics(zone) ?? zone.getBoundingRect?.(true);
    const bounds = {
        left: Number(zoneBounds?.left ?? 0),
        top: Number(zoneBounds?.top ?? 0),
        width: Math.max(1, Number(zoneBounds?.width ?? (zone as any)._zoneWidth ?? 900)),
        height: Math.max(1, Number(zoneBounds?.height ?? (zone as any)._zoneHeight ?? 600))
    };

    const plannedProducts = applyAutoOfferRuntimeLayout(
        zone,
        cards.map((card: any, index: number) => getProductDataForAutoOfferPlan(card, index)),
        [],
        bounds,
        'replace',
        {
            sourceMode: (zone as any).contentSource || 'manual',
            autoLayout: true,
            persist: false
        }
    );

    const orderByProductId = new Map<string, number>();
    plannedProducts.forEach((product: any, index: number) => {
        orderByProductId.set(String(product?.id || product?.productInstanceId || '').trim(), index);
    });

    cards.forEach((card: any, index: number) => {
        const productId = String(
            (card as any)?._productData?.id ||
            (card as any)?._productData?.productInstanceId ||
            (card as any)?.productId ||
            (card as any)?._customId ||
            ''
        ).trim();
        const nextOrder = orderByProductId.get(productId);
        (card as any)._zoneOrder = typeof nextOrder === 'number' ? nextOrder : index;
        card.dirty = true;
    });

    const orderedCards = cards.slice().sort((a: any, b: any) => {
        const ao = Number((a as any)?._zoneOrder);
        const bo = Number((b as any)?._zoneOrder);
        return (Number.isFinite(ao) ? ao : 0) - (Number.isFinite(bo) ? bo : 0);
    });

    syncZoneCardFrameBindings(zone, orderedCards);
    recalculateZoneLayout(zone, orderedCards, {
        save: false,
        requestRender: false,
        trustCachedChildren: true
    });
    syncZoneDerivedMetadata(zone);
    refreshCanvasObjects();
    refreshSelectedRef();
    safeRequestRenderAll();
    await saveCurrentState({
        allowEmptyOverwrite: true,
        reason: 'auto-offer-layout',
        source: 'user',
        skipCoalesce: true,
        skipIfUnchanged: false
    });
    await flushPersistenceNow('auto-offer-layout', { force: true });
    notifyEditorInfo('Layout automático aplicado.');
}


</script>

<template>
  <div class="flex flex-col h-full min-h-0 min-w-0 w-full bg-background text-foreground antialiased font-sans overflow-hidden">

      <ProjectManager
        v-if="showProjectManager && !isQuickMode"
        :isOpen="showProjectManager"
        @close="showProjectManager = false"
        @load="(data) => loadCanvasData(data)"
      />

      <AiImageStudioModal
        v-if="aiStudioOpen && !isQuickMode"
        v-model="aiStudioOpen"
        :uploads="aiStudioUploads"
        :initial="aiStudioOptions.initial"
        @created="handleAiStudioCreated"
      />

      <div
        v-if="showProductImageUploadPicker"
        class="fixed inset-0 z-[500] bg-black/60 backdrop-blur-[1px] flex items-center justify-center p-4"
        @click.self="showProductImageUploadPicker = false; clearPendingProductImageOperation()"
      >
        <div class="w-full max-w-5xl max-h-[85vh] bg-[#1a1a1a] border border-white/10 rounded-xl shadow-2xl flex flex-col overflow-hidden">
          <div class="flex items-center justify-between px-4 py-3 border-b border-white/10">
            <div>
              <h3 class="text-sm font-semibold text-white">Escolher imagem do produto</h3>
              <p class="text-[11px] text-zinc-400">
                {{ productImagePickerMode === 'replace' ? 'Escolha se deseja trocar somente esta imagem ou todas neste card.' : 'Escolha uma imagem para este produto.' }}
              </p>
            </div>
            <button
              type="button"
              class="text-zinc-400 hover:text-white text-lg leading-none"
              @click="showProductImageUploadPicker = false; clearPendingProductImageOperation()"
            >
              ×
            </button>
          </div>

          <div class="px-4 py-3 border-b border-white/10 space-y-2">
            <label v-if="productImagePickerMode === 'replace'" class="block text-xs text-zinc-200">Aplicar a troca em
              <select v-model="productImageReplaceScope" class="ml-2 rounded bg-zinc-900 p-2 border border-white/20">
                <option value="single">Somente esta imagem</option>
                <option value="all">Todas as imagens deste produto no card</option>
              </select>
            </label>
            <div v-if="productImageFlavorQueries.length" class="flex flex-wrap gap-2 text-xs text-zinc-200">
              <button type="button" :disabled="productImagePickerLoading" class="rounded border border-violet-400 px-3 py-2 disabled:opacity-50" @click="searchExplicitProductFlavors">Buscar imagens dos sabores</button>
              <span>Ou buscar um sabor:</span>
              <button v-for="item in productImageFlavorQueries" :key="item.flavor" type="button" class="rounded bg-violet-700 px-3 py-2" @click="productImagePickerSearch = item.query; searchProductImagePickerUploads()">{{ item.flavor }}</button>
            </div>
            <div class="flex gap-2">
              <input
                v-model="productImagePickerSearch"
                type="text"
                placeholder="Buscar pelo nome do produto ou arquivo..."
                class="min-w-0 flex-1 h-10 bg-zinc-900 border border-white/10 rounded px-3 text-sm text-white focus:outline-none focus:border-violet-500/50"
                @keydown.enter.prevent="searchProductImagePickerUploads"
              />
              <button
                type="button"
                class="h-10 px-3 rounded bg-violet-600 hover:bg-violet-500 disabled:opacity-50 text-xs font-semibold text-white transition-colors"
                :disabled="productImagePickerLoading"
                @click="searchProductImagePickerUploads"
              >
                {{ productImagePickerLoading ? 'Buscando...' : 'Buscar' }}
              </button>
            </div>
            <div class="flex items-center justify-between gap-3">
              <p class="text-[10px] text-zinc-500">Somente imagens já salvas no Wasabi aparecem aqui.</p>
              <button
                type="button"
                class="shrink-0 text-[10px] font-semibold text-violet-300 hover:text-violet-200"
                @click="
                  showProductImageUploadPicker = false;
                  openLocalProductImagePicker(productImagePickerMode, {
                    imageId: productImagePickerTargetImageId,
                    cardId: productImagePickerTargetCardId,
                    scope: productImageReplaceScope
                  })
                "
              >
                Enviar nova imagem
              </button>
            </div>
            <p v-if="productImagePickerError" class="text-[10px] text-rose-300">{{ productImagePickerError }}</p>
          </div>

          <div class="flex-1 overflow-y-auto p-4">
            <div v-if="productImagePickerLoading" class="text-xs text-zinc-500">
              Buscando ou preparando imagem sem fundo...
            </div>
            <div v-else-if="!filteredProductImageUploads.length" class="text-xs text-zinc-500">
              <p>Nenhuma imagem encontrada no Wasabi para esta busca.</p>
              <div class="mt-3 flex flex-wrap items-center justify-center gap-2">
                <button
                  v-if="productImagePickerSearch.trim()"
                  type="button"
                  class="rounded border border-violet-400/40 bg-violet-500/10 px-3 py-2 text-[11px] font-semibold text-violet-200 hover:bg-violet-500/20"
                  @click="productImagePickerSearch = ''; searchProductImagePickerUploads()"
                >
                  Ver todas as imagens do Wasabi
                </button>
                <button
                  type="button"
                  class="rounded border border-white/15 bg-white/5 px-3 py-2 text-[11px] font-semibold text-zinc-200 hover:bg-white/10"
                  @click="
                    showProductImageUploadPicker = false;
                    openLocalProductImagePicker(productImagePickerMode, {
                      imageId: productImagePickerTargetImageId,
                      cardId: productImagePickerTargetCardId,
                    scope: productImageReplaceScope
                    })
                  "
                >
                  Enviar uma nova imagem
                </button>
              </div>
            </div>
            <div v-else class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              <button
                v-for="asset in filteredProductImageUploads"
                :key="asset.id"
                type="button"
                class="bg-zinc-900 border border-white/10 rounded-lg overflow-hidden text-left hover:border-violet-500/50 transition-colors"
                @click="applyProductImageFromUploadPicker(asset)"
              >
                <div class="aspect-square">
                  <img :src="toWasabiProxyUrl(asset.url) || toWasabiDirectUrl(asset.url) || asset.url" :alt="asset.name || 'Imagem do produto'" class="w-full h-full object-contain bg-zinc-950" />
                </div>
                <div class="px-2 py-1.5 border-t border-white/10">
                  <p class="text-[10px] text-zinc-200 truncate">{{ asset.name || 'Sem nome' }}</p>
                </div>
              </button>
            </div>
          </div>
        </div>
      </div>

      <!-- Central Workspace -->
      <div class="flex flex-1 min-h-0 min-w-0 overflow-hidden relative bg-[#1a1a1a]">
          <!-- Left Sidebar (New Component) -->
          <SidebarLeft v-if="!isMobile && !isQuickMode" :start-in-resources="project.isTemplate === true" @insert-asset="insertAssetToCanvas" @insert-element="insertElementToCanvas" @open-menu="showProjectManager = true" @generate-institutional="handleGenerateInstitutional">
              <template #layers-panel>
                  <LayersPanel
                      class="flex-1"
                      :objects="canvasObjects"
                      :selectedId="selectedObjectId"
                      :selectedIds="selectedObjectIds"
                      @select="selectObject"
                      @toggle-visible="toggleVisible"
                      @toggle-lock="toggleLock"
                      @delete="deleteObject"
                      @move-up="id => moveLayer(id, 'up')"
                      @move-down="id => moveLayer(id, 'down')"
                      @rename="renameLayer"
                      @reorder="reorderLayerByDrag"
                      @context-menu="handleLayersContextMenu"
                  />
              </template>
          </SidebarLeft>

          <OfferValidityPrompt
            v-if="!isQuickMode && project.isTemplate !== true && advancedValidityPromptOpen"
            :date-format="quickValidityDateFormat"
            :start-date="quickValidityStartDate"
            :end-date="quickValidityEndDate"
            :mode="quickValidityMode"
            :while-stocks="quickValidityWhileStocks"
            @confirm="handleAdvancedValidityPromptConfirm"
          />

          <QuickModeControls
            v-if="isQuickMode"
            :key="String(project.id || '')"
            @mobile-section="quickMobileSection = $event"
            @export="exportQuickDesign"
            :pages="project.pages"
            :current-page-id="currentPageId"
            :template-models="quickModeTemplateModels"
            :current-model-id="quickModeCurrentModelId"
            :product-palette-styles="quickCardColorSettings.styles"
            @product-palette="handleUpdateGlobalStyles('productPalette', $event, { targetId: quickModeTargetZoneId })"
            :card-color-mode="quickCardColorSettings.mode"
            :card-color="quickCardColorSettings.color"
            @card-colors="applyQuickCardColors"
            :zones="quickModeZones"
            :selected-zone-id="quickModeTargetZoneId"
            :products="quickModeProducts"
            :bulk-label-templates="quickModeBulkLabelTemplates"
            :busy="isParsingProducts || isProcessing"
            :business-profile="quickBusinessProfile"
            :business-field-visibility="quickModeBusinessFieldVisibility"
            :required-business-fields="quickModeRequiredBusinessFields"
            :completed-product-reviews="quickCompletedProductReviews"
            :business-setup-saving="isQuickBusinessProfileSaving"
            :business-setup-error="quickBusinessProfileSetupError"
            :validity-date-format="quickValidityDateFormat"
            :validity-start-date="quickValidityStartDate"
            :validity-end-date="quickValidityEndDate"
            :validity-mode="quickValidityMode"
            :validity-while-stocks="quickValidityWhileStocks"
            :show-validity="quickShowValidity"
            :validity-prompt-ready="isFabricReady"
            :offer-scope="quickOfferScope"
            @select-zone="selectQuickModeZone"
            @select-zone-structure="handleQuickModeZoneStructureChange"
            @restore-grid="handleQuickGridRestore"
            @select-product="handleQuickModeSelectProduct"
            @open-product-image-picker="handleQuickModeOpenProductImagePicker"
            @clear-products="handleQuickModeClearProducts"
            @delete-product="handleQuickModeDeleteProduct"
            @move-product="handleQuickModeMoveProduct"
            @change-all-labels="handleQuickModeBulkLabelChange"
            @import="handleQuickModeImport"
            @toggle-business-field="handleQuickModeBusinessFieldToggle"
            @save-business-setup="handleQuickModeBusinessSetup"
            @update-validity="handleQuickModeValidityUpdate"
            @open-business-profile="handleQuickBusinessProfileOpen"
            @select-page="switchToPage"
            @request-delete-page="requestDeleteQuickModePage"
            @use-template-model="useQuickModeTemplateModel"
          />

          <!-- Canvas Stage -->
          <main :class="['editor-canvas-stage flex-1 min-w-0 min-h-0 relative bg-[#1a1a1a] flex items-center justify-center overflow-hidden', isQuickMode ? 'quick-mode-stage' : 'cursor-grab active:cursor-grabbing']" :style="isMobile && !isQuickMode ? ((project.pages?.length || 0) > 1 ? 'padding-bottom: calc(var(--editor-mobile-nav-h) + var(--editor-mobile-pages-h))' : 'padding-bottom: var(--editor-mobile-nav-h)') : ''">
              <QuickModePageToolbar
                v-if="isQuickMode && project.pages?.length"
                :current-page-id="currentPageId"
                :page-number="Number(project.activePageIndex || 0) + 1"
                :page-count="project.pages.length"
                :model-name="quickModePageToolbarModelName"
                :format-label="quickModePageToolbarFormat.label"
                :width="quickModePageToolbarDimensions.width"
                :height="quickModePageToolbarDimensions.height"
                :busy="isParsingProducts || isProcessing || isQuickModePageResizeInFlight"
                @duplicate-page="duplicateQuickModePage"
                @add-page="addQuickModePage"
                @resize-page="resizeQuickModePage"
              />

              <QuickModeCanvasControls
                :mobile-open="quickMobileSection === 'tools'"
                v-if="isQuickMode && project.pages?.length"
                :current-zoom="currentZoom"
                :native-text-count="quickModeNativeTextObjects.length"
                :native-color-count="quickModeColorTargets.length"
                :color-targets="quickModeColorTargets"
                :selected-color-object-id="selectedObjectRef?._customId"
                :native-font-family="quickModeNativeFontFamily"
                :native-font-size="quickFontSize"
                :typography="quickTypography"
                :selected-text="!!selectedObjectRef && quickModeNativeTextObjects.length === 1"
                :apply-all-label="quickFontApplyAllLabel"
                :busy="isParsingProducts || isProcessing"
                @export="exportQuickDesign"
                @zoom-in="quickModeZoomIn"
                @zoom-out="quickModeZoomOut"
                @zoom-fit="quickModeZoomFit"
                @set-zoom="quickModeSetZoom"
                @pan="quickModePanViewport"
                @apply-font="applyQuickModeNativeFont"
                @apply-font-size="applyQuickFontSize"
                @apply-to-all="applyQuickTypographyToAll"
                @apply-typography="applyQuickTypography"
                @apply-color="applyQuickModeColorChange"
                @clear-color="clearQuickModeColor"
                @apply-opacity="applyQuickModeOpacityChange"
              />



              <section v-if="quickSelectedProductName" class="quick-product-name-colors flex flex-wrap items-center gap-3 rounded-lg border border-white/15 bg-zinc-900 px-3 py-2 text-xs text-white" @pointerdown.stop>
                <label class="flex items-center gap-2">Cor do nome
                  <input type="color" aria-label="Cor do nome do produto" :value="quickSelectedProductName.fill || '#000000'" @change="applyQuickProductNameColor(($event.target as HTMLInputElement).value)" />
                </label>
                <label class="flex items-center gap-2">Aplicar a
                  <select v-model="quickProductNameColorScope" class="rounded bg-zinc-800 px-2 py-1" aria-label="Produtos que receberão a cor">
                    <option value="selected">Este produto</option>
                    <option value="all">Todos os produtos da zona</option>
                    <option v-if="quickSelectedNameCard?._cardHighlighted" value="highlights">Somente destaques</option>
                  </select>
                </label>
                <button type="button" class="rounded bg-white/10 px-3 py-2" @click="applyQuickProductNameColor(quickSelectedProductName.fill)">Aplicar cor atual</button>
                <button type="button" class="rounded bg-violet-500/25 px-3 py-2" @click="applyQuickProductNameColor(null)">Cor automática</button>
              </section>

              <!-- Infinite Canvas Effect (Wrapper) -->
              <div class="canvas-workspace" :class="{ 'has-logo-panel': selectedQuickLogo }">
                  <div ref="wrapperEl" class="quick-mode-canvas-viewport w-full h-full min-w-0 min-h-0 relative flex items-center justify-center overflow-hidden bg-[#1a1a1a]">
                  <canvas ref="canvasEl" class="block canvas-touch-surface" @contextmenu.prevent.stop></canvas>
                   <label
                     v-if="quickSelectedCardConfiguration && quickCardConfigurationOptions.length > 1 && selectedObjectPos.visible && !isDesignLoading && !figmaCrop.isCropActive.value"
                     class="absolute z-[118] flex max-w-[calc(100%-16px)] items-center gap-2 rounded-lg border border-violet-400/30 bg-[#18181b]/95 px-2 py-1.5 text-xs text-white shadow-xl"
                     :style="{ top: `${Math.max(8, selectedObjectPos.top - 76)}px`, left: `${Math.max(8, Math.min(selectedObjectPos.left, (wrapperEl?.clientWidth || 300) - 260))}px` }"
                     @pointerdown.stop
                     @mousedown.stop
                     @click.stop
                     @keydown.stop
                   >
                     <span>Modelo do card</span>
                     <select
                       :value="quickSelectedCardConfiguration.profile"
                       aria-label="Modelo deste card"
                       class="min-h-8 min-w-0 rounded-md border border-white/15 bg-[#27272a] px-2 text-xs text-white"
                       @change="handleUpdateCardConfigurationProfile(($event.target as HTMLSelectElement).value, quickSelectedCardConfiguration.id)"
                     >
                       <option value="">Automático</option>
                       <option v-for="option in quickCardConfigurationOptions" :key="option.id" :value="option.id">{{ option.name }}</option>
                     </select>
                   </label>
                   <ProductImageQuickActions
                     v-if="selectedProductImageQuickActions"
                     :visible="showProductImageQuickActions"
                     :top="selectedProductImageQuickActionsPos.top"
                     :left="selectedProductImageQuickActionsPos.left"
                     :width="selectedProductImageQuickActionsPos.width"
                     :height="selectedProductImageQuickActionsPos.height"
                     :fill-count="selectedProductImageQuickActions.card._productData?.autoFillImages ? (selectedProductImageQuickActions.card._productData.imageFillCount || 0) : 1"
                     :fill-direction="selectedProductImageQuickActions.card._productData?.imageFillDirection || 'auto'"
                     @remove="handleProductImageRemove"
                     @replace="handleAction('replace-product-image-upload')"
                     @add="handleAction('add-product-image-upload')"
                     @duplicate="handleProductImageDuplicate"
                     @fill="handleProductImageFill"
                     @resize="handleProductImageResize"
                   />

                  <!-- A cópia do editor permanece disponível ao trocar de página, mesmo sem seleção. -->
                  <div
                    v-if="!isQuickMode && editorClipboardSummary && !showDesignLoaderOverlay"
                    class="absolute top-3 right-3 z-[205] max-w-[calc(100%-1.5rem)] pointer-events-auto"
                    role="status"
                  >
                    <div class="flex items-center gap-2 rounded-xl border border-violet-300/25 bg-zinc-950/85 px-2.5 py-2 shadow-xl backdrop-blur-sm">
                      <Copy class="h-3.5 w-3.5 shrink-0 text-violet-200" />
                      <span class="hidden sm:inline whitespace-nowrap text-[11px] font-medium text-white/75">
                        {{ editorClipboardSummaryText }}
                      </span>
                      <button
                        type="button"
                        class="rounded-lg border border-violet-300/25 bg-violet-500/25 px-2 py-1 text-[11px] font-semibold text-white transition hover:bg-violet-500/40 focus:outline-none focus:ring-2 focus:ring-violet-300/70"
                        title="Colar nesta página (Ctrl/Cmd+Shift+V)"
                        v-if="!isQuickMode"
                        aria-label="Colar cópia do editor nesta página"
                        @click="triggerEditorClipboardPaste"
                      >
                        Colar nesta página
                      </button>
                    </div>
                  </div>

                  <CanvasRulers
                    v-if="!isQuickMode"
                    :visible="viewShowRulers"
                    :canvas="canvas"
                    :wrapper-el="wrapperEl"
                    :guides="rulerGuides"
                    @create-guide="handleCreateUserGuide"
                    @update-guide="handleUpdateUserGuide"
                    @delete-guide="handleDeleteUserGuide"
                  />

                  <!-- Design loader overlay (prevents "blank canvas until click" confusion) -->
                  <div
                    v-show="showDesignLoaderOverlay"
                    class="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[1px] cursor-wait"
                    style="z-index: 200;"
                    aria-live="polite"
                  >
                    <div class="px-4 py-3 rounded-lg bg-zinc-950/70 border border-white/10 shadow-xl">
                      <div class="flex items-center gap-2">
                        <div class="w-4 h-4 rounded-full border-2 border-white/20 border-t-white animate-spin"></div>
                        <p class="text-sm text-white/90">{{ designLoadMessage }}</p>
                      </div>
                      <p class="text-[11px] text-white/55 mt-1">{{ designLoadProgressLine || 'Aguarde alguns segundos.' }}</p>
                    </div>
                  </div>

                  <!-- Storage degraded banner (missing/blocked images) -->
                  <div
                    v-show="showStorageDegradedBanner"
                    class="editor-storage-notice absolute top-3 left-1/2 -translate-x-1/2"
                    style="z-index: 210;"
                  >
                    <div class="editor-storage-notice-content flex items-center gap-2 px-3 py-2 rounded-full bg-amber-950/60 border border-amber-300/20 text-amber-100 shadow-lg">
                      <span class="text-xs">{{ storageDegradedHint || 'Algumas imagens nao carregaram.' }}</span>
                      <button
                        type="button"
                        class="text-xs px-2 py-1 rounded-full bg-amber-200/10 hover:bg-amber-200/15 border border-amber-200/20"
                        @click="retryStorageReload"
                      >
                        Recarregar
                      </button>
                      <button
                        v-if="canRecoverLatestNonEmpty"
                        type="button"
                        class="text-xs px-2 py-1 rounded-full bg-white/5 hover:bg-white/10 border border-white/10"
                        @click="openHistoryModal"
                      >
                        Historico
                      </button>
                      <button
                        v-if="canRecoverLatestNonEmpty"
                        type="button"
                        class="text-xs px-2 py-1 rounded-full bg-red-200/10 hover:bg-red-200/15 border border-red-200/20"
                        :disabled="isRecoveringLatestNonEmpty"
                        @click="recoverLatestNonEmptyForActivePage"
                      >
                        {{ isRecoveringLatestNonEmpty ? 'Recuperando...' : 'Recuperar' }}
                      </button>
                    </div>
                  </div>

                  <ContextMenu
                    v-if="!isQuickMode"
                    v-model="canvasContextMenu.show"
                    :x="canvasContextMenu.x"
                    :y="canvasContextMenu.y"
                    :items="canvasContextMenuItems"
                    @select="handleCanvasContextMenuSelect"
                  />

                  <ContextMenu
                    v-if="!isQuickMode"
                    v-model="layersContextMenu.show"
                    :x="layersContextMenu.x"
                    :y="layersContextMenu.y"
                    :items="layersContextMenuItems"
                    @select="handleLayersContextMenuSelect"
                  />

                  <!-- Virtual Scrollbars (Figma Style) -->
                  <div
                    v-if="!isQuickMode"
                    v-show="scrollV.visible"
                    class="absolute right-1 w-1.5 bg-white/20 hover:bg-white/40 rounded-full z-50 transition-colors cursor-pointer"
                    :style="{ top: scrollV.top + 'px', height: scrollV.height + 'px' }"
                    @mousedown="handleVerticalScrollbarDrag"
                  ></div>
                  <div
                    v-if="!isQuickMode"
                    v-show="scrollH.visible"
                                        class="absolute bottom-1 h-1.5 bg-white/20 hover:bg-white/40 rounded-full z-60 transition-colors cursor-pointer"
                    :style="{ left: scrollH.left + 'px', width: scrollH.width + 'px' }"
                    @mousedown="handleHorizontalScrollbarDrag"
                  ></div>

                  <!-- Frame Label Overlays (clickable, always visible) -->
                    <FrameLabelsOverlay
                      v-if="!isQuickMode"
                      :labels="frameLabels"
                      @label-click="handleFrameLabelClick"
                      @label-mousedown="handleFrameLabelMouseDown"
                    />

                    <ProductLabelQuickActions
                      v-if="selectedProductLabelQuickActions"
                      :visible="showProductLabelQuickActions"
                      :top="selectedProductLabelQuickActionsPos.top"
                      :left="selectedProductLabelQuickActionsPos.left"
                      :width="selectedProductLabelQuickActionsPos.width"
                      :height="selectedProductLabelQuickActionsPos.height"
                      :mode="selectedProductLabelQuickActions.mode"
                      :templates="selectedProductLabelQuickActions.templates"
                      :selected-template-id="selectedProductLabelQuickActions.selectedTemplateId"
                      @mode="handleProductLabelModeChange"
                      @select-all="handleProductLabelSelectAll"
                      @template="handleProductLabelTemplateChange"
                      @manage-templates="openGlobalLabelTemplates"
                    />




                   <ZoneQuickActions
                    v-if="selectedZoneQuickActions && !isQuickMode"
                    :visible="showZoneQuickActions"
                    :top="selectedZoneQuickActionsPos.top"
                    :left="selectedZoneQuickActionsPos.left"
                    :width="selectedZoneQuickActionsPos.width"
                    :height="selectedZoneQuickActionsPos.height"
                    :name="selectedZoneQuickActions.name"
                    :role-label="selectedZoneQuickActions.roleLabel"
                    :status-label="selectedZoneQuickActions.statusLabel"
                    :frame-label="selectedZoneQuickActions.frameLabel"
                    :product-count="selectedZoneQuickActions.productCount"
                    :is-empty="selectedZoneQuickActions.isEmpty"
                    @fill="handleZoneQuickActionFill"
                    @append="handleZoneQuickActionAppend"
                    @replace="handleZoneQuickActionReplace"
                    @preset="handleZoneQuickActionPreset"
                    @duplicate="handleZoneQuickActionDuplicate"
                  />

                  <input type="file" ref="fileInput" class="hidden" @change="handleFileUpload" accept="image/*" multiple />
              </div>

                   <QuickLogoQuickActions
                     v-if="selectedQuickLogo"
                     :logo="selectedQuickLogo"
                     @update-property="updateQuickLogoProperty"
                     @close="closeQuickLogoActions"
                   />
              </div>

              <!-- Contextual Toolbar for Vector Paths (Above Main Toolbar) -->
              <PenContextualToolbar
                v-if="!isQuickMode"
	                :visible="showPenContextualToolbar"
	                :is-vector-path="!!selectedObjectRef?.isVectorPath || !!currentEditingPath?.isVectorPath"
	                :is-node-editing="isNodeEditing"
	                :can-delete-point="selectedPathNodeIndex !== null"
                @toggle-visible="selectedObjectRef && updateObjectProperty('visible', !selectedObjectRef.visible)"
                @toggle-handles="handleAction('toggle-handles')"
                @add-point="handleAction('add-path-point')"
                @delete-point="handleAction('delete-path-point')"
                @split-path="splitPath"
                @simplify-path="simplifyPath"
                @close-path="closePath"
              />

              <!-- Floating Toolbar (Figma Style) - Bottom Center -->
              <CanvasFloatingToolbar
                v-if="!isMobile && !isQuickMode"
                :is-drawing="isDrawing"
                :is-pen-mode="isPenMode"
                @select-tool="setTool('select')"
                @add-frame="addFrame"
                @add-shape="(type, options) => addShape(type as any, options as any)"
                @add-text="(variant) => addText(variant as any)"
                @toggle-pen-mode="togglePenMode"
                @toggle-drawing="toggleDrawing"
                @set-pen-width="setPenWidth"
                @add-grid-zone="addGridZone"
              />

              <!-- Mobile Undo/Redo Bar (always visible on mobile) -->
              <div
                v-if="isMobile && !isQuickMode"
                class="absolute top-2 left-2 z-200 flex items-center gap-1 px-1.5 py-1 rounded-lg bg-[#18181b]/90 backdrop-blur-md border border-white/10 shadow-lg"
              >
                <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 w-9 h-9" title="Desfazer" @click="undo()">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7v6h6"/><path d="M21 17a9 9 0 0 0-9-9 9 9 0 0 0-6 2.3L3 13"/></svg>
                </button>
                <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 w-9 h-9" title="Refazer" @click="redo()">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M21 7v6h-6"/><path d="M3 17a9 9 0 0 1 9-9 9 9 0 0 1 6 2.3L21 13"/></svg>
                </button>
              </div>

              <!-- Mobile Zoom Display (top right) -->
              <div
                v-if="isMobile && !isQuickMode"
                class="absolute top-2 right-2 z-200 flex items-center gap-1"
              >
                <!-- Botao Exportar destacado (atalho rapido para ExportDialog) -->
                <button
                  class="touch-target flex items-center gap-1 px-2.5 py-1.5 rounded-lg bg-violet-500 hover:bg-violet-600 active:bg-violet-700 text-white shadow-lg border border-violet-400/40"
                  title="Exportar (PNG / JPG / PDF)"
                  @click="exportDesign()"
                >
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" x2="12" y1="15" y2="3"/></svg>
                  <span class="text-[11px] font-semibold">Exportar</span>
                </button>

                <!-- Grupo de zoom -->
                <div class="flex items-center gap-1 px-1.5 py-1 rounded-lg bg-[#18181b]/90 backdrop-blur-md border border-white/10 shadow-lg">
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 w-9 h-9" title="Zoom -" @click="handleZoomOut()">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" x2="16.65" y1="21" y2="16.65"/><line x1="8" x2="14" y1="11" y2="11"/></svg>
                  </button>
                  <span class="text-[11px] text-white/50 min-w-9 text-center tabular-nums">{{ Math.round(currentZoom) }}%</span>
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 w-9 h-9" title="Zoom +" @click="handleZoomIn()">
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" x2="16.65" y1="21" y2="16.65"/><line x1="11" x2="11" y1="8" y2="14"/><line x1="8" x2="14" y1="11" y2="11"/></svg>
                  </button>
                </div>
              </div>

              <!-- Mobile Quick Actions Bar (appears when object is selected) -->
              <div
                v-if="isMobile && !isQuickMode && selectedObjectRef"
                class="absolute left-0 right-0 z-200 flex items-center justify-center px-2"
                :style="(project.pages?.length || 0) > 1 ? 'bottom: calc(var(--editor-mobile-nav-h) + var(--editor-mobile-pages-h) + 8px)' : 'bottom: calc(var(--editor-mobile-nav-h) + 8px)'"
              >
                <div class="flex items-center gap-0.5 px-2 py-1.5 rounded-xl bg-[#18181b]/95 backdrop-blur-md border border-white/10 shadow-xl overflow-x-auto max-w-full scrollbar-hide">
                  <!-- Product Zone: Import -->
                  <button
                    v-if="selectedZoneQuickActions"
                    class="touch-target flex items-center gap-1.5 justify-center rounded-lg bg-emerald-500/18 border border-emerald-400/25 text-emerald-100 hover:bg-emerald-500/28 active:bg-emerald-500/35 px-3 shrink-0"
                    title="Importar produtos para a zona selecionada"
                    @click="handleZoneQuickActionImport"
                  >
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="M7 10l5 5 5-5"/><path d="M12 15V3"/><path d="M4 3h16"/></svg>
                    <span class="text-[11px] font-semibold">Importar</span>
                  </button>
                  <button
                    v-if="selectedZoneQuickActions"
                    class="touch-target flex items-center gap-1.5 justify-center text-white/70 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2.5 shrink-0"
                    title="Editar layout da zona"
                    @click="handleZoneQuickActionPreset"
                  >
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>
                    <span class="text-[11px] font-semibold">Layout</span>
                  </button>
                  <div v-if="selectedZoneQuickActions" class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Layer stepper: easy access on mobile without opening Layers -->
                  <button
                    class="touch-target flex items-center gap-1.5 justify-center rounded-lg bg-violet-500/18 border border-violet-400/20 text-violet-100 hover:bg-violet-500/28 active:bg-violet-500/35 px-3 shrink-0"
                    title="Subir uma camada"
                    @click="arrangeActiveObjects('bring-forward')"
                  >
                    <ArrowUp class="w-4 h-4" />
                    <span class="text-[11px] font-semibold">Subir</span>
                  </button>
                  <button
                    class="touch-target flex items-center gap-1.5 justify-center rounded-lg bg-violet-500/18 border border-violet-400/20 text-violet-100 hover:bg-violet-500/28 active:bg-violet-500/35 px-3 shrink-0"
                    title="Descer uma camada"
                    @click="arrangeActiveObjects('send-backward')"
                  >
                    <ArrowDown class="w-4 h-4" />
                    <span class="text-[11px] font-semibold">Descer</span>
                  </button>
                  <div class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Copy -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Copiar para outra página" @click="triggerCopyShortcut">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect width="14" height="14" x="8" y="8" rx="2"/><path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/></svg>
                  </button>
                  <!-- Paste editor copy -->
                  <button v-if="!isQuickMode" class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Colar nesta página (Ctrl/Cmd+Shift+V)" @click="triggerEditorClipboardPaste">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M15 2H9a1 1 0 0 0-1 1v2c0 .6.4 1 1 1h6c.6 0 1-.4 1-1V3c0-.6-.4-1-1-1Z"/><path d="M8 4H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2M16 4h2a2 2 0 0 1 2 2v2"/><path d="M12 12h4"/><path d="M12 16h4"/></svg>
                  </button>
                  <div class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Duplicate -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Duplicar" @click="handleAction('duplicate')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect width="13" height="13" x="9" y="9" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
                  </button>
                  <!-- Delete -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-red-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Deletar" @click="deleteActiveSelectionFromCanvas()">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>
                  </button>
                  <div class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Flip H -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Flip Horizontal" @click="handleAction('flip-h')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3H5a2 2 0 0 0-2 2v14c0 1.1.9 2 2 2h3"/><path d="M16 3h3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-3"/><line x1="12" x2="12" y1="20" y2="4"/></svg>
                  </button>
                  <!-- Flip V -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Flip Vertical" @click="handleAction('flip-v')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8V5a2 2 0 0 1 2-2h14c1.1 0 2 .9 2 2v3"/><path d="M3 16v3a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-3"/><line x1="4" x2="20" y1="12" y2="12"/></svg>
                  </button>
                  <div class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Bring to Front -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Trazer para frente" @click="arrangeActiveObjects('bring-to-front')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m17 11-5-5-5 5"/><path d="m17 18-5-5-5 5"/></svg>
                  </button>
                  <!-- Send to Back -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Enviar para trás" @click="arrangeActiveObjects('send-to-back')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m7 6 5 5 5-5"/><path d="m7 13 5 5 5-5"/></svg>
                  </button>
                  <div class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Group -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Agrupar" @click="groupSelection()">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="2" width="8" height="8" rx="1"/><rect x="14" y="2" width="8" height="8" rx="1"/><rect x="2" y="14" width="8" height="8" rx="1"/><rect x="14" y="14" width="8" height="8" rx="1"/></svg>
                  </button>
                  <!-- Ungroup -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Desagrupar" @click="handleAction('ungroup')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="5" width="14" height="14" rx="2" stroke-dasharray="3 3"/><path d="M2 2h5v5H2z" fill="currentColor" opacity="0.3"/><path d="M17 2h5v5h-5z" fill="currentColor" opacity="0.3"/><path d="M2 17h5v5H2z" fill="currentColor" opacity="0.3"/><path d="M17 17h5v5h-5z" fill="currentColor" opacity="0.3"/></svg>
                  </button>
                  <div class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Align Left -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Alinhar Esquerda" @click="alignSelectionHorizontally('left')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><line x1="4" x2="4" y1="2" y2="22"/><rect x="8" y="4" width="12" height="5" rx="1"/><rect x="8" y="15" width="8" height="5" rx="1"/></svg>
                  </button>
                  <!-- Align Center H -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Centralizar H" @click="alignSelectionHorizontally('center')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><line x1="12" x2="12" y1="2" y2="22"/><rect x="5" y="4" width="14" height="5" rx="1"/><rect x="7" y="15" width="10" height="5" rx="1"/></svg>
                  </button>
                  <!-- Align Right -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Alinhar Direita" @click="alignSelectionHorizontally('right')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><line x1="20" x2="20" y1="2" y2="22"/><rect x="4" y="4" width="12" height="5" rx="1"/><rect x="8" y="15" width="8" height="5" rx="1"/></svg>
                  </button>
                  <div class="w-px h-5 bg-white/10 mx-0.5 shrink-0"></div>
                  <!-- Properties -->
                  <button class="touch-target flex items-center justify-center text-white/60 hover:text-white active:text-violet-400 rounded-lg hover:bg-white/10 px-2 shrink-0" title="Propriedades" @click="openMobilePanel('properties')">
                    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><line x1="4" x2="4" y1="21" y2="14"/><line x1="4" x2="4" y1="10" y2="3"/><line x1="12" x2="12" y1="21" y2="12"/><line x1="12" x2="12" y1="8" y2="3"/><line x1="20" x2="20" y1="21" y2="16"/><line x1="20" x2="20" y1="12" y2="3"/><line x1="2" x2="6" y1="14" y2="14"/><line x1="10" x2="14" y1="8" y2="8"/><line x1="18" x2="22" y1="16" y2="16"/></svg>
                  </button>
                </div>
              </div>
          </main>

          <EditorRightSidebar
            v-if="!isMobile && !isQuickMode"
            :collaborators="collaborators || []"
            :current-user="currentUser"
            :show-zoom-menu="showZoomMenu"
            :current-zoom="currentZoom"
            :get-color-from-string="getColorFromString"
            :get-initial="getInitial"
            :selected-object="selectedObjectRef"
            :active-mode="activeMode"
            :page-settings="pageSettings"
            :color-styles="project.colorStyles || []"
            :product-zone="productZoneState.productZone.value"
            :product-zone-inspector="selectedZoneInspectorData"
            :product-global-styles="productZoneState.globalStyles.value"
            :product-zone-structures-loaded="productZoneStructuresState.isLoaded.value"
            :label-templates="labelTemplates"
            :view-show-grid="viewShowGrid"
            :view-show-rulers="viewShowRulers"
            :view-show-guides="viewShowGuides"
            :snap-to-objects="snapToObjects"
            :snap-to-guides="snapToGuides"
            :snap-to-grid="snapToGrid"
            :grid-size="gridSize"
            @update:show-zoom-menu="showZoomMenu = $event"
            @present="startPresentation()"
            @open-share="shareDesign"
            @zoom-50="handleZoom50"
            @zoom-100="handleZoom100"
            @zoom-200="handleZoom200"
            @zoom-400="handleZoom400"
            @zoom-fit="zoomToFit"
            @zoom-selection="handleZoomToSelection"
            @toggle-grid="toggleGrid"
            @toggle-rulers="toggleRulers"
            @toggle-guides="toggleGuides"
            @toggle-snap-objects="toggleSnapObjects"
            @toggle-snap-guides="toggleSnapGuides"
            @toggle-snap-grid="toggleSnapGrid"
            @set-grid-size="setGridSize"
            @update-property="updateObjectProperty"
            @update-smart-group="updateSmartGroup"
            @update-page-settings="updatePageSettings"
            @action="handleAction"
            @add-color-style="addColorStyle"
            @apply-color-style="applyColorStyle"
            @update-zone="handleUpdateZone"
            @update-global-styles="handleUpdateGlobalStyles"
            @update-card-style="handleUpdateCardStyle"
            @reset-card-style="handleResetCardStyle"
            @update-card-configuration-profile="handleUpdateCardConfigurationProfile"
            @apply-template-to-zone="handleApplyTemplateToZone"
            @apply-preset="handleApplyZonePreset"
            @sync-gaps="handleSyncZoneGaps"
            @recalculate-layout="handleRecalculateLayout"
            @auto-offer-layout="handleAutoOfferLayout"
            @manage-label-templates="openGlobalLabelTemplates"
	            @open-zone-review="handleZoneQuickActionFill"
	            @change-mode="(mode: 'design' | 'prototype') => activeMode = mode"
	          />

      </div>

      <!-- Mobile Pages Carousel (estilo Canva: swipe horizontal entre páginas) -->
      <EditorMobilePagesCarousel
        v-if="isMobile && !isQuickMode && (project.pages?.length || 0) > 1"
        :pages="project.pages"
        :active-page-id="currentPageId"
        @select-page="switchToPage"
        @add-page="addNewPage"
        @duplicate-page="duplicatePage"
        @delete-page="deletePageByIdAfterFlush"
      />

      <!-- Mobile Bottom Nav -->
      <EditorMobileNav
        v-if="isMobile && !isQuickMode"
        ref="mobileNavRef"
        @open-panel="openMobilePanel"
      />

      <EditorMobilePanels
        v-if="isMobile && !isQuickMode && mobilePanel"
        :panel="mobilePanel"
        :title="getMobilePanelTitle(mobilePanel)"
        :current-zoom="currentZoom"
        :pages="project.pages || []"
        :current-page-id="currentPageId"
        :canvas-objects="canvasObjects"
        :selected-object-id="selectedObjectId"
        :selected-object-ids="selectedObjectIds"
        :current-user="currentUser"
        :selected-object="selectedObjectRef"
        :active-mode="activeMode"
        :page-settings="pageSettings"
        :color-styles="project.colorStyles || []"
        :product-zone="productZoneState.productZone.value"
        :product-zone-inspector="selectedZoneInspectorData"
        :product-global-styles="productZoneState.globalStyles.value"
        :product-zone-structures-loaded="productZoneStructuresState.isLoaded.value"
        :label-templates="labelTemplates"
        :view-show-grid="viewShowGrid"
        :view-show-rulers="viewShowRulers"
        :view-show-guides="viewShowGuides"
        :snap-to-objects="snapToObjects"
        :snap-to-guides="snapToGuides"
        :snap-to-grid="snapToGrid"
        :grid-size="gridSize"
        :get-color-from-string="getColorFromString"
        :get-initial="getInitial"
        @close="closeMobilePanel"
        @set-panel="mobilePanel = $event"
        @command="handleMobilePanelCommand"
        @insert-asset="asset => { insertAssetToCanvas(asset); closeMobilePanel(); }"
        @insert-element="element => { insertElementToCanvas(element); closeMobilePanel(); }"
        @generate-institutional="payload => { handleGenerateInstitutional(payload); closeMobilePanel(); }"
        @select-layer="selectObject"
        @toggle-visible="toggleVisible"
        @toggle-lock="toggleLock"
        @delete-layer="deleteObject"
        @move-layer="moveLayer"
        @rename-layer="renameLayer"
        @reorder-layer="reorderLayerByDrag"
        @update-property="updateObjectProperty"
        @update-smart-group="updateSmartGroup"
        @update-page-settings="updatePageSettings"
        @add-color-style="addColorStyle"
        @apply-color-style="applyColorStyle"
        @update-zone="handleUpdateZone"
        @update-global-styles="handleUpdateGlobalStyles"
        @update-card-style="handleUpdateCardStyle"
        @reset-card-style="handleResetCardStyle"
        @update-card-configuration-profile="handleUpdateCardConfigurationProfile"
        @apply-template-to-zone="handleApplyTemplateToZone"
        @apply-preset="handleApplyZonePreset"
        @sync-gaps="handleSyncZoneGaps"
        @recalculate-layout="handleRecalculateLayout"
        @auto-offer-layout="handleAutoOfferLayout"
        @manage-label-templates="openGlobalLabelTemplates(); closeMobilePanel()"
        @open-zone-review="handleZoneQuickActionFill"
        @change-mode="(mode: 'design' | 'prototype') => activeMode = mode"
        @select-page="switchToPage"
        @add-page="addNewPage"
        @duplicate-page="duplicatePage"
        @delete-page="deletePageAfterFlush"
        @reorder-pages="reorderPages"
      />

      <!-- MODALS SYSTEM (Internal Dialogs) -->
      <EditorModalsHost
        :show-save-modal="showSaveModal"
        :save-project-name="saveProjectName"
        :show-label-templates-modal="showLabelTemplatesModal"
        :label-templates="labelTemplates"
        :selected-template-id="activeZoneTemplateId()"
        :can-save-label-template-from-selection="canSaveLabelTemplateFromSelectionComputed"
        :show-a-i-modal="showAIModal"
        :ai-prompt="aiPrompt"
        :ai-reference-image-data-url="aiReferenceImageDataUrl"
        :ai-apply-mode="aiApplyMode"
        :ai-page-type="aiPageType"
        :ai-page-width="aiPageWidth"
        :ai-page-height="aiPageHeight"
        :is-processing="isProcessing"
        :show-paste-list-modal="showPasteListModal"
        :active-paste-tab="activePasteTab"
        :paste-list-text="pasteListText"
        :pasted-image="pastedImage"
        :is-analyzing-image="isAnalyzingImage"
        :show-delete-page-modal="showDeletePageModal"
        :show-product-review-modal="showProductReviewModal"
        :review-products="reviewProducts"
        :product-review-initial-text="quickModeInitialProductText"
        :product-review-initial-file="quickModeInitialProductFile"
        :product-review-auto-fill-images="quickModeAutoFillImages"
        :product-review-one-product-per-page="quickModeOneProductPerPage"
        :product-review-auto-parse="quickModeAutoParseProductText"
        :product-review-quick-mode="isQuickMode"
        :show-import-mode="!!(targetGridZone && isLikelyProductZone(targetGridZone))"
        :product-import-existing-count="productImportExistingCount"
        :product-review-initial-import-mode="productReviewInitialImportMode"
        :import-zone-label-template-id="importZoneLabelTemplateId"
        :import-target-zone-id="importTargetZoneId"
        :show-export-modal="showExportModal"
        :export-settings="exportSettings"
        :available-frames-for-export="availableFramesForExport"
        :available-pages-for-export="availablePagesForExport"
        :has-exportable-selected-object="hasExportableSelectedObject"
        :available-frames-for-import="availableFramesForImport"
        :available-zones-for-import="availableZonesForImport"
        :show-share-modal="showShareModal"
        :share-settings="shareSettings"
        :show-presentation-modal="showPresentationModal"
        :presentation-image="presentationImage"
        :presentation-hotspots="presentationHotspots"
        :figma-crop-active="figmaCrop.isCropActive.value"
        :crop-frame-rect="figmaCrop.cropFrameRect.value"
        :crop-frame-name="figmaCrop.cropFrameName.value"
        :crop-canvas-offset="cropCanvasOffset"
        @update:show-save-modal="showSaveModal = $event"
        @update:save-project-name="saveProjectName = $event"
        @save="saveProject"
        @update:show-label-templates-modal="showLabelTemplatesModal = $event"
        @edit-selection="beginEditSelectedLabel"
        @create-from-selection="createLabelTemplateFromSelection"
        @create-default="createDefaultLabelTemplate"
        @update-from-selection="updateLabelTemplateFromSelection"
        @insert-to-canvas="insertLabelTemplateToCanvas"
        @update-template="handleUpdateTemplateFromMiniEditor"
        @duplicate-template="duplicateLabelTemplateById"
        @delete-template="deleteLabelTemplateById"
        @apply-template-to-zone="applyTemplateToActiveZone"
        @set-template-splash-image="setTemplateSplashImage"
        @update:show-a-i-modal="showAIModal = $event"
        @update:ai-prompt="aiPrompt = $event"
        @update:ai-reference-image-data-url="aiReferenceImageDataUrl = $event"
        @update:ai-apply-mode="aiApplyMode = $event"
        @update:ai-page-type="aiPageType = $event"
        @update:ai-page-width="aiPageWidth = $event"
        @update:ai-page-height="aiPageHeight = $event"
        @generate-ai="generateFlyerWithAI"
        @update:show-paste-list-modal="showPasteListModal = $event"
        @update:active-paste-tab="activePasteTab = $event"
        @update:paste-list-text="pasteListText = $event"
        @update:pasted-image="pastedImage = $event"
        @update:is-analyzing-image="isAnalyzingImage = $event"
        @submit-paste-list="handlePasteList"
        @submit-paste-file="handlePasteFile"
        @update:show-delete-page-modal="setDeletePageModalVisibility"
        @confirm-delete-page="confirmDeletePage"
        @update:show-product-review-modal="handleProductReviewModalVisibility"
        @import-products="confirmProductImport"
        @update:show-export-modal="showExportModal = $event"
        @export="performExport"
        @update:show-share-modal="showShareModal = $event"
        @toggle-share-frame="toggleFrameSelection"
        @select-all-share-frames="selectAllFrames"
        @share="performShare"
        @update:show-presentation-modal="showPresentationModal = $event"
        @hotspot-click="handleHotspotClick"
        @update:figma-crop-active="figmaCrop.isCropActive.value = $event"
        @update:crop-frame-rect="handleCropRectUpdate"
        @crop-complete="handleCropComplete"
      />

      <div
        v-if="aiToast"
        class="fixed top-4 right-4 z-(--z-toast) px-3 py-2 rounded-lg border text-sm shadow-xl"
        :class="aiToast.type === 'error'
          ? 'bg-red-950/90 border-red-300/35 text-red-100'
          : (aiToast.type === 'success'
              ? 'bg-emerald-950/90 border-emerald-300/35 text-emerald-100'
              : 'bg-sky-950/90 border-sky-300/35 text-sky-100')"
      >
        {{ aiToast.message }}
      </div>

      <div
        v-if="isExportDownloadInProgress"
        class="fixed inset-0 z-(--z-toast) pointer-events-none flex items-center justify-center"
      >
        <div class="flex items-center gap-3 rounded-xl border border-violet-400/35 bg-zinc-950/90 px-4 py-3 shadow-2xl">
          <span class="inline-block h-4 w-4 rounded-full border-2 border-violet-300/30 border-t-violet-300 animate-spin" />
          <div class="text-left">
            <p class="text-sm font-semibold text-violet-100">{{ exportDownloadStatus }}</p>
            <p class="text-[11px] text-violet-200/75">Preparando download...</p>
          </div>
        </div>
      </div>

      <!-- Page History / Restore Modal -->
      <EditorPageHistoryModal
        :show="showHistoryModal"
        :loading="historyLoading"
        :error="historyError"
        :items="historyItems"
        :restoring-key="restoringHistoryKey"
        @close="showHistoryModal = false"
        @restore="restoreFromHistoryItem"
      />

  </div>
</template>

